local config = {
  ui_story_5086_50860100_1_dialog_content = "... PlayerName, Elvis... yo...",
  ui_story_5086_50860100_2_dialog_content = "Eh... ¿Jeno?",
  ui_story_5086_50860100_3_dialog_content = "¿Qué dijiste? No puedo escucharte...",
  ui_story_5086_50860100_4_dialog_content = "Sentí un momento en el que una marea milagrosa subió.",
  ui_story_5086_50860100_5_dialog_content = "Ha llegado el momento de que persiga una coyuntura crucial determinada por el destino.",
  ui_story_5086_50860100_6_dialog_content = "Así que por favor...",
  ui_story_5086_50860100_7_dialog_content = "¡Espera, Jeno!",
  ui_story_5086_50860100_8_dialog_content = "... ¿Estaba soñando justo ahora?",
  ui_story_5086_50860100_9_dialog_content = "Qué sueño tan extraño e incierto.",
  ui_story_5086_50860100_10_dialog_content = "¿Me pregunto si es por esa carta que recibí ayer?",
  ui_story_5086_50860100_11_dialog_content = "<color=#e8d9bb>\"Mis disculpas por enviar una carta tan urgente. Dejé un mensaje para ti en Harbor City. Por favor, ven solo para recibirlo. —Jeno\"</color>",
  ui_story_5086_50860100_12_dialog_content = "Su carta también es extraña e incierta... pero parece que está hablando en serio.",
  ui_story_5086_50860100_13_dialog_content = "Me pidió específicamente que viniera solo... ¿Significa esto que no quiere que traiga a Vice o a Carleen? Me pregunto qué podría ser...",
  ui_story_5086_50860100_14_dialog_content = "<color=#e8d9bb>La brisa marina sopla suavemente mientras las calles de la ciudad normalmente pacífica se agitan con multitudes de turistas.</color>",
  ui_story_5086_50860100_15_dialog_content = "No parece que haya pasado tanto tiempo, pero parece que Harbor City finalmente se ha recuperado de esa crisis.",
  ui_story_5086_50860100_16_dialog_content = "Si solo Elvis estuviera aquí para verlo, estoy seguro de que estaría tan orgulloso... ¿Eh?",
  ui_story_5086_50860100_17_dialog_content = "Es extraño... El Emerald estaba atracado justo aquí, ¿no es así?",
  ui_story_5086_50860100_18_dialog_content = "¿Cómo podría desaparecer un barco tan grande?",
  ui_story_5086_50860100_19_dialog_content = "¿Estás aquí para ver las actuaciones, amigo?",
  ui_story_5086_50860100_20_dialog_content = "Lamento decírtelo, pero perdiste tu oportunidad. El circo levantó ancla y se fue hace unos días.",
  ui_story_5086_50860100_21_dialog_content = "¿Despegó? ¿Pero por qué?",
  ui_story_5086_50860100_22_dialog_content = "No lo sé, pero escuché que tenía algo que ver con alguien que resultó herido en el caos anterior.",
  ui_story_5086_50860100_23_dialog_content = "No, no, ¡Lo tienes todo mal!",
  ui_story_5086_50860100_24_dialog_content = "¡Todos saben que el maestro de ceremonias tuvo una gran pelea con su amante, así que zarpó para ir a buscarlos!",
  ui_story_5086_50860100_25_dialog_content = "¿Qué? ¡Pensé que era porque una bestia maravillosa escapó del barco!",
  ui_story_5086_50860100_26_dialog_content = "Todos lo vieron, ¿no es así? ¡Esa enorme ballena estaba liderando el camino!",
  ui_story_5086_50860100_27_dialog_content = "Bueno, se fueron a toda prisa... Eso es seguro.",
  ui_story_5086_50860100_28_dialog_content = "Solo espero que no haya pasado nada malo.",
  ui_story_5086_50860100_29_dialog_content = "Entonces, ¿dónde se supone que debo encontrar a Jeno ahora?",
  ui_story_5086_50860100_30_dialog_content = "La carta no decía... Espera, ¡hay una dirección escrita en la parte de atrás! Supongo que no lo noté antes.",
  ui_story_5086_50860100_31_dialog_content = "130 Calle Coral—",
  ui_story_5086_50860100_32_dialog_content = "¡Bienvenido al maravilloso mundo submarino de Harbor City, un lugar donde los sueños y el mar se encuentran!",
  ui_story_5086_50860100_33_dialog_content = "¿Te gustaría nadar con tiburones?",
  ui_story_5086_50860100_34_dialog_content = "¿O tal vez relajarse y descansar con una tortuga marina?",
  ui_story_5086_50860100_35_dialog_content = "¡Incluso puedes unirte a esas medusas y soplar hermosas burbujas!",
  ui_story_5086_50860100_36_dialog_content = "¡Todo es posible en este lugar fantástico!",
  ui_story_5086_50860100_37_dialog_content = "... ¿Un acuario?",
  ui_story_5086_50860100_38_dialog_content = "¡Así es, un acuario!",
  ui_story_5086_50860100_39_dialog_content = "¡Tenemos todo tipo de adorables criaturas marinas que seguramente capturarán tu corazón! ¿Es tu primera vez aquí?",
  ui_story_5086_50860100_40_dialog_content = "Si es así, ¿puedo sugerir comenzar desde el lado izquierdo del primer piso...?",
  ui_story_5086_50860100_41_dialog_content = "Eh... ¿Qué estaba en exhibición allí de nuevo? Lo siento, tengo una memoria a corto plazo terrible. Permíteme revisar mis notas...",
  ui_story_5086_50860100_42_dialog_content = "Uh, no estoy aquí para—",
  ui_story_5086_50860100_43_dialog_content = "¡Ajá, ahí está! ¡Es la exhibición de arrecifes de coral!",
  ui_story_5086_50860100_44_dialog_content = "¡También estamos organizando un evento interactivo hoy! Los invitados pueden tocar algunas estrellas de mar allí, mientras que los niños de diez años y menores son gratis!",
  ui_story_5086_50860100_45_dialog_content = "Definitivamente parezco mayor de diez años, ¿no crees?",
  ui_story_5086_50860100_46_dialog_content = "Hmm... Supongo que sí.",
  ui_story_5086_50860100_47_dialog_content = "¡Probemos esto en su lugar!",
  ui_story_5086_50860100_48_dialog_content = "<color=#e8d9bb>La joven de repente cubre su ojo derecho con su mano.</color>",
  ui_story_5086_50860100_49_dialog_content = "¡Como solo puedo ver la mitad de ti, eso significa que tengo que considerarte como si tuvieras la mitad de tu edad normal!",
  ui_story_5086_50860100_50_dialog_content = "¡Genial, ahora puedes entrar gratis!",
  ui_story_5086_50860100_51_dialog_content = "Lo siento, señorita... ¿Maya, verdad? Aprecio el gesto, pero vine aquí por un asunto bastante serio. Si me disculpa—",
  ui_story_5086_50860100_52_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5086_50860100_53_dialog_content = "¡Ay! ¡Lo siento mucho!",
  ui_story_5086_50860100_54_dialog_content = "Esa voz.",
  ui_story_5086_50860100_55_dialog_content = "Perdón por la interrupción, señorita, pero mi compañero ha derribado accidentalmente su cartel de exhibición en la entrada.",
  ui_story_5086_50860100_56_dialog_content = "Por favor, permítanos compensarle completamente por los daños.",
  ui_story_5086_50860100_57_dialog_content = "Está bien, solo garabateé ese letrero yo mismo. Simplemente estoy feliz de que ninguno de ustedes esté herido.",
  ui_story_5086_50860100_58_dialog_content = "Lo siento mucho, de verdad por esto...",
  ui_story_5086_50860100_59_dialog_content = "Minos! Sanae! ¡Realmente sois vosotros dos!",
  ui_story_5086_50860100_60_dialog_content = "¡Sr. PlayerName! No esperaba verte aquí... ¡Ah! Lo siento, esa no es forma de saludar a un amigo!",
  ui_story_5086_50860100_61_dialog_content = "Um, c-cómo has estado...",
  ui_story_5086_50860100_62_dialog_content = "He estado bien, Sanae. Es bueno verte a ti y a Minos de nuevo.",
  ui_story_5086_50860100_63_dialog_content = "Buen día, Sr. PlayerName. Me alegra ver que has estado bien después de todo este tiempo.",
  ui_story_5086_50860100_64_dialog_content = "¿No está Nina con ustedes?",
  ui_story_5086_50860100_65_dialog_content = "Me temo que no... La señorita Nina está actualmente ocupada con un nuevo diseño... así que me pidió que... realizara una investigación de la industria en su lugar.",
  ui_story_5086_50860100_66_dialog_content = "En efecto. Yo, por otro lado, estoy aquí para ayudar en el asunto.",
  ui_story_5086_50860100_67_dialog_content = "... ¿Estás seguro de que no estás confundiendo tus roles?",
  ui_story_5086_50860100_68_dialog_content = "No se preocupe, señor. Aunque Sanae todavía tiene mucho que aprender como sirvienta—",
  ui_story_5086_50860100_69_dialog_content = "Como alguien de la misma edad que nuestra joven señorita, resulta que también comparte varias de sus sensibilidades nobles.",
  ui_story_5086_50860100_70_dialog_content = "Lo más importante, sin embargo, es el hecho de que la señorita Nina estaba dispuesta a depositar su confianza en ella.",
  ui_story_5086_50860100_71_dialog_content = "Mientras ella continúe cumpliendo con las expectativas de nuestra Lady, no tengo ninguna razón para interferir en sus deberes.",
  ui_story_5086_50860100_72_dialog_content = "Mi lady desea involucrarse en esta industria, pero como mayordomo de la familia Andersen, si descubro que hay demasiados factores inestables en juego...",
  ui_story_5086_50860100_73_dialog_content = "La mirada en tus ojos de repente es mucho más aterradora, Minos.",
  ui_story_5086_50860100_74_dialog_content = "¿Es eso cierto? Entonces por favor perdone mi rudeza. Simplemente quise decir que tomaría medidas correctivas si ese fuera el caso.",
  ui_story_5086_50860100_75_dialog_content = "<color=#e8d9bb>De repente, se puede escuchar un fuerte alboroto justo fuera de la puerta—</color>",
  ui_story_5086_50860100_76_dialog_content = "¿Qué está pasando ahí fuera?",
  ui_story_5086_50860100_77_dialog_content = "¡Maya, ven rápido! ¡Algunas personas de aspecto sospechoso están intentando entrar al acuario!",
  ui_story_5086_50860100_78_dialog_content = "<color=#e8d9bb>Un par de niños aparecen en la entrada, bloqueando frenéticamente a dos personas vestidas pesadamente para que no entren.</color>",
  ui_story_5086_50860100_79_dialog_content = "¡Skado! ¡Sebastián! ¡Formaciones defensivas! ¡No dejes que ninguno de esos dos irrumpa en el vestíbulo!",
  ui_story_5086_50860100_80_dialog_content = "Más fácil decirlo que hacerlo, ¡Froude! El bajito no debería ser un problema, pero ¿cómo se supone que debemos evitar que ese tipo alto entre?",
  ui_story_5086_50860100_81_dialog_content = "Ratas... ¿Es este realmente el final?",
  ui_story_5086_50860100_82_dialog_content = "Jejeje, ustedes niños son tan enérgicos, pero puedo asegurarles, no somos chicos malos.",
  ui_story_5086_50860100_83_dialog_content = "¡Eso es exactamente lo que diría un chico malo!",
  ui_story_5086_50860100_84_dialog_content = "Además, ¿quién lleva tanta ropa al acuario cuando hace tanto calor afuera?",
  ui_story_5086_50860100_85_dialog_content = "Si no puedes apreciar lo genial de nuestros atuendos, entonces todavía tienes un largo camino por recorrer antes de poder llamarte a ti mismo un espadachín como nosotros.",
  ui_story_5086_50860100_86_dialog_content = "¿Chapoteo-qué ahora?",
  ui_story_5086_50860100_87_dialog_content = "¿Eh—Quieres decir que no sabes sobre la profesión más genial del mundo? Entonces permíteme—",
  ui_story_5086_50860100_88_dialog_content = "Muy bien, ustedes dos, eso es suficiente ahora.",
  ui_story_5086_50860100_89_dialog_content = "!",
  ui_story_5086_50860100_90_dialog_content = "<color=#e8d9bb>En algún momento durante su discusión, Maya ha logrado aparecer detrás de ellos de alguna manera.</color>",
  ui_story_5086_50860100_91_dialog_content = "<color=#e8d9bb>Con un solo movimiento hábil, ella arrebata sus gafas de sol y máscaras de sus caras.</color>",
  ui_story_5086_50860100_92_dialog_content = "¿Goldie? ¿Sadie?",
  ui_story_5086_50860100_93_dialog_content = "UH oh...",
  ui_story_5086_50860100_94_dialog_content = "¡Se acercó a nosotros sin llamar nuestra atención en absoluto! ¿Quién en el mundo eres tú?",
  ui_story_5086_50860100_95_dialog_content = "Mi nombre es Maya. Soy una empleada aquí en el acuario.",
  ui_story_5086_50860100_96_dialog_content = "Lo siento, pero tengo que pedirte que evites usar ropa tan aterradora aquí. Hay muchos niños corriendo por el acuario, ya sabes.",
  ui_story_5086_50860100_97_dialog_content = "Además, ¿no preferirías disfrutar viendo todas las bonitas criaturas marinas sin llevar todo esto?",
  ui_story_5086_50860100_98_dialog_content = "¡Humph, no vine aquí para divertirme.",
  ui_story_5086_50860100_99_dialog_content = "Escuché sobre algo terrible que sucedió en Harbor City. ¡Como un noble espadachín, vine aquí para impartir justicia!",
  ui_story_5086_50860100_100_dialog_content = "¿Algo terrible? ¿En Harbor City?",
  ui_story_5086_50860100_101_dialog_content = "Por favor, no ofendas a nuestros invitados, Maya.",
  ui_story_5086_50860100_102_dialog_content = "Pero señorita Stellandine—",
  ui_story_5086_50860100_103_dialog_content = "Mis disculpas a todos. Mi nombre es Stellandine y soy la propietaria de este acuario.",
  ui_story_5086_50860100_104_dialog_content = "Mi empleado puede actuar un poco precipitadamente a veces. Lo siento si esto ha impactado negativamente su visita a nuestro establecimiento hoy.",
  ui_story_5086_50860100_105_dialog_content = "No, aquí también somos culpables.",
  ui_story_5086_50860100_106_dialog_content = "Entonces, como propietaria del acuario, permítanme invitarlos a todos a una comida como muestra de nuestras disculpas.",
  ui_story_5086_50860100_107_dialog_content = "Antes de eso, siéntase libre de observar cualquiera de las exhibiciones que tenemos para ofrecer.",
  ui_story_5086_50860100_108_dialog_content = "Pero tal como dice Maya, muchos de nuestros invitados son niños pequeños, así que por favor absténganse de cualquier comportamiento que pueda molestarlos.",
  ui_story_5086_50860100_109_dialog_content = "Si tienes más preguntas, puedes preguntarme en cualquier momento.",
  ui_story_5086_50860100_110_dialog_content = "No interrumpiremos tu visualización más tiempo. Ven, Maya.",
  ui_story_5086_50860100_111_dialog_content = "Pero el cartel de exhibición en la entrada...",
  ui_story_5086_50860100_112_dialog_content = "Todavía necesito ordenar algunos archivos. ¿Podrías ayudarme con esto, por favor?",
  ui_story_5086_50860100_113_dialog_content = "¡Por supuesto! ¡Sólo déjamelo a mi!",
  ui_story_5086_50860100_114_dialog_content = "Qué jefe tan bondadoso.",
  ui_story_5086_50860100_115_dialog_content = "De todos modos, hay tantas caras conocidas aquí hoy.",
  ui_story_5086_50860100_116_dialog_content = "La última vez que algo así sucedió fue en la Casa Embrujada de Andersen, y luego...",
  ui_story_5086_50860100_117_dialog_content = "Aunque no creo que algo así vuelva a suceder, debería preguntar al respecto solo para estar seguro.",
  ui_story_5086_50860100_118_dialog_content = "¡Hola Sadie, qué es esta cosa terrible de la que has oído hablar?",
  ui_story_5086_50860100_119_dialog_content = "¡Ah sí, esa cosa terrible! ¡Cualquier verdadero espadachín vendría corriendo ante el más mínimo indicio de problemas!",
  ui_story_5086_50860100_120_dialog_content = "Entonces... ¿Eso significa que viniste aquí solo porque escuchaste un rumor?",
  ui_story_5086_50860100_121_dialog_content = "Puede que haya sido solo un rumor, pero ver para creer después de todo.",
  ui_story_5086_50860100_122_dialog_content = "Si hay alguna señal de peligro, tengo el deber de enfrentarlo. Incluso si resulta ser un rumor, no me sentiré tranquilo hasta que vea la verdad por mí mismo.",
  ui_story_5086_50860100_123_dialog_content = "Prevenir incluso las crisis más improbables es parte de ser un espadachín!",
  ui_story_5086_50860100_124_dialog_content = "La verdad es, nos encontramos con una serie de rumores preocupantes.",
  ui_story_5086_50860100_125_dialog_content = "Pero cada uno era un poco diferente del último. Algunas personas afirmaban que una ballena colosal acechaba en las aguas de Harbor City, esperando devorar a cualquiera lo suficientemente imprudente como para nadar en el mar.",
  ui_story_5086_50860100_126_dialog_content = "Otros afirmaron que la gente seguía desapareciendo después de recoger extrañas tarjetas esparcidas por la ciudad.",
  ui_story_5086_50860100_127_dialog_content = "Fue demasiado difícil discernir la verdad desde Umbraton, por lo que Sadie insistió en venir aquí y comprobar las cosas por sí misma.",
  ui_story_5086_50860100_128_dialog_content = "Siempre existe la posibilidad de que esto pueda llevar a una batalla gloriosa y fatídica, una que hará famoso mi nombre en toda la tierra.",
  ui_story_5086_50860100_129_dialog_content = "Estaba un poco preocupado por Sadie saliendo aquí solo, así que decidí acompañarlo.",
  ui_story_5086_50860100_130_dialog_content = "Pero realmente, no esperábamos encontrarte aquí, PlayerName. ¡Qué feliz coincidencia!",
  ui_story_5086_50860100_131_dialog_content = "Veo que el Sr. Minos también está aquí, mejor vamos a saludar. ¿Te gustaría venir, PlayerName?",
  ui_story_5086_50860100_132_dialog_content = "De hecho, tengo algo importante que tratar ahora mismo.",
  ui_story_5086_50860100_133_dialog_content = "¡Bueno entonces, esperamos verte de nuevo por aquí!",
  ui_story_5086_50860100_134_dialog_content = "Claro.",
  ui_story_5086_50860100_135_dialog_content = "(Si tan solo pudiera encontrarme con el mensaje de Jeno de esta manera también.)",
  ui_story_5086_50860201_1_dialog_content = "Esto es agotador.",
  ui_story_5086_50860201_2_dialog_content = "He estado dando vueltas todo el día, pero aún no he encontrado nada.",
  ui_story_5086_50860201_3_dialog_content = "Quizás simplemente vaya a tomar un descanso en el área de descanso por ahora.",
  ui_story_5086_50860201_4_dialog_content = "Jeno dijo que dejó un mensaje para mí aquí, lo que significa que probablemente lo confió a alguien.",
  ui_story_5086_50860201_5_dialog_content = "Dado que también incluyó la dirección de este acuario, debe significar que esta persona está en algún lugar por aquí.",
  ui_story_5086_50860201_6_dialog_content = "Esas son las únicas dos pistas que tengo ahora mismo.",
  ui_story_5086_50860201_7_dialog_content = "Estoy bastante seguro de que es solo una coincidencia que tantos de mis amigos también estén aquí, pero ¿tal vez uno de ellos es el mensajero? Si es así, ¿se supone que debo preguntarles al respecto?",
  ui_story_5086_50860201_8_dialog_content = "No, eso derrotaría el propósito de mantener las cosas en secreto. No sería diferente a contarle todo a Astra al respecto.",
  ui_story_5086_50860201_9_dialog_content = "Eso concluye el evento interactivo de hoy, ¡todos! Es hora de que nuestra encantadora estrella de mar regrese a casa para un merecido descanso.",
  ui_story_5086_50860201_10_dialog_content = "También es hora de que ustedes, niños, vayan a casa. Recuerden no jugar en la calle de camino de regreso.",
  ui_story_5086_50860201_11_dialog_content = "¡Aww! ¡Pero aún es muy temprano! ¡No quiero ir a casa todavía! ¡Y todavía no nos has contado una historia!",
  ui_story_5086_50860201_12_dialog_content = "¡Tus historias siempre son tan divertidas, Maya!",
  ui_story_5086_50860201_13_dialog_content = "También quiero escuchar uno.",
  ui_story_5086_50860201_14_dialog_content = "Nos prometiste una historia la semana pasada, pero parece que ya te olvidaste de ella, Maya.",
  ui_story_5086_50860201_15_dialog_content = "Oh, ¿es eso así? Realmente debo haber olvidado... Lo siento.",
  ui_story_5086_50860201_16_dialog_content = "Ven a sentarte con nosotros, Maya.",
  ui_story_5086_50860201_17_dialog_content = "Muy bien, te contaré una historia que leí el otro día, pero después de eso, tienes que ir directamente a casa. ¿Trato?",
  ui_story_5086_50860201_18_dialog_content = "¡Acuerdo!",
  ui_story_5086_50860201_19_dialog_content = "Hace mucho, mucho tiempo, había un chico que se perdió durante sus viajes...",
  ui_story_5086_50860201_20_dialog_content = "(Bueno, Jeno probablemente no sabía cuándo vendría a buscar su mensaje.)",
  ui_story_5086_50860201_21_dialog_content = "(Más que confiarlo a un viajero, probablemente eligió a alguien que casi siempre está en el acuario.)",
  ui_story_5086_50860201_22_dialog_content = "(Aparte de Maya, la única otra persona que encaja es la propietaria...)",
  ui_story_5086_50860201_23_dialog_content = "(Una vez que termine de contar su historia, intentaré mencionarlo discretamente.)",
  ui_story_5086_50860201_24_dialog_content = "Viajó a través de densos bosques y desiertos vacíos e incluso llegó a las orillas del mar en el borde del mundo. Pero todo el tiempo, nunca pudo descifrar en qué dirección iba.",
  ui_story_5086_50860201_25_dialog_content = "Me parece un poco tonto.",
  ui_story_5086_50860201_26_dialog_content = "Si yo fuera él, llevaría toneladas de mapas conmigo para nunca perderme.",
  ui_story_5086_50860201_27_dialog_content = "¡Ya veo! Te gusta prepararte para todo, ¿no es así Skado?",
  ui_story_5086_50860201_28_dialog_content = "Pero el chico en esta historia no fue tan afortunado.",
  ui_story_5086_50860201_29_dialog_content = "Aunque normalmente estaba rodeado de sus amigos, había algunos viajes que tenía que enfrentar solo.",
  ui_story_5086_50860201_30_dialog_content = "Pero afortunadamente, apareció un pequeño gatito para salvarlo de su soledad.",
  ui_story_5086_50860201_31_dialog_content = "Era un gato muy amigable. Sin nada más que hacer, el chico decidió jugar con él.",
  ui_story_5086_50860201_32_dialog_content = "Así que los dos dieron un paseo por la playa y observaron las olas espumosas rompiendo sobre el arrecife de coral.",
  ui_story_5086_50860201_33_dialog_content = "Observaron cómo los peces voladores saltaban fuera del agua con un ruido silbante.",
  ui_story_5086_50860201_34_dialog_content = "Rodaron en la arena y se rieron mientras observaban a un cangrejo torpe tambalearse de un lado a otro.",
  ui_story_5086_50860201_35_dialog_content = "Al final del día, se acurrucaron bajo una palmera y dejaron que la suave brisa marina los llevara al sueño.",
  ui_story_5086_50860201_36_dialog_content = "¡Eso suena tan bien!",
  ui_story_5086_50860201_37_dialog_content = "Cuando el niñito despertó, se sorprendió al ver un pequeño pueblo ante sus ojos.",
  ui_story_5086_50860201_38_dialog_content = "Digo que era un pequeño pueblo, pero era tan bullicioso como una gran ciudad. Había tiendas de armas, tiendas de artículos y todo tipo de posadas.",
  ui_story_5086_50860201_39_dialog_content = "Las calles estaban llenas de valientes aventureros equipados con todo tipo de armas y armaduras, así como viajeros con atuendos maravillosos.",
  ui_story_5086_50860201_40_dialog_content = "De hecho, había un monstruo marino acechando en algún lugar de la ciudad.",
  ui_story_5086_50860201_41_dialog_content = "Durante el día, todo era perfectamente tranquilo. Pero por la noche, se podía escuchar un sonido de lamento proveniente del mar.",
  ui_story_5086_50860201_42_dialog_content = "Fue un sonido tan aterrador, por lo que todos pensaron que era el grito de un monstruo marino.",
  ui_story_5086_50860201_43_dialog_content = "¡Eso debe ser por qué había tantos aventureros en la ciudad! ¡Apuesto a que pensaron que quienquiera que derrotara al monstruo podría reclamar su tesoro!",
  ui_story_5086_50860201_44_dialog_content = "Tiene sentido, ya que hay muchas personas que piensan como tú, Froude. ¿Pero por qué había tantos viajeros también?",
  ui_story_5086_50860201_45_dialog_content = "Si hubiera un monstruo en esa ciudad, nunca querría ir allí por nada.",
  ui_story_5086_50860201_46_dialog_content = "Quizás fue porque el monstruo nunca mostró su verdadero rostro, a pesar de que sus gritos eran tan aterradores. No importa cuántas personas aparecieran, nunca se presentó ante nadie.",
  ui_story_5086_50860201_47_dialog_content = "Aunque había muchas personas que afirmaban haber visto al monstruo, el resto del pueblo descubrió que todos estaban mintiendo.",
  ui_story_5086_50860201_48_dialog_content = "Así que los rumores sobre el aterrador monstruo solo empeoraron.",
  ui_story_5086_50860201_49_dialog_content = "(Hey, yo también he leído esa historia antes.)",
  ui_story_5086_50860201_50_dialog_content = "(Si recuerdo correctamente, termina con el chico y el gato descubriendo una cueva oculta.)",
  ui_story_5086_50860201_51_dialog_content = "(En lugar de encontrar un monstruo marino allí, todo lo que encontraron fue una pequeña niña llorando sola.)",
  ui_story_5086_50860201_52_dialog_content = "(No tenía familia ni amigos, así que pasaba todas las noches llorando sola en esa cueva.)",
  ui_story_5086_50860201_53_dialog_content = "(Su sollozo silencioso resonó a través de la cueva hasta que todo el pueblo pudo escucharlo, que fue cómo comenzaron los rumores sobre el monstruo marino.)",
  ui_story_5086_50860201_54_dialog_content = "(El niñito la animó y prometió ser su amigo.)",
  ui_story_5086_50860201_55_dialog_content = "(Después de eso, el pueblo nunca volvió a escuchar al \"monstruo marino\" por la noche, pero...)",
  ui_story_5086_50860201_56_dialog_content = "Pero.",
  ui_story_5086_50860201_57_dialog_content = "¿Eh? ¿Ya está en esta parte de la historia?)",
  ui_story_5086_50860201_58_dialog_content = "¡Desafortunadamente, no recuerdo el resto de la historia!",
  ui_story_5086_50860201_59_dialog_content = "¡Pffft! Tos, tos...",
  ui_story_5086_50860201_60_dialog_content = "Lo sabía...",
  ui_story_5086_50860201_61_dialog_content = "Esto no es sorprendente para nada...",
  ui_story_5086_50860201_62_dialog_content = "Está bien, ya estamos acostumbrados.",
  ui_story_5086_50860201_63_dialog_content = "Todos sabemos lo mala que es la memoria de Maya, después de todo. A veces incluso olvida cosas que sucedieron hace cinco minutos.",
  ui_story_5086_50860201_64_dialog_content = "Realmente nos hace preocupar.",
  ui_story_5086_50860201_65_dialog_content = "Jajaja, realmente no estoy seguro de cómo proceder...",
  ui_story_5086_50860201_66_dialog_content = "¿Qué harían ustedes, niños, si estuvieran en el lugar del niñito?",
  ui_story_5086_50860201_67_dialog_content = "¡Oh, lo sé! ¡Iría directamente a una tienda de armas para comprar una nueva espada y escudo!",
  ui_story_5086_50860201_68_dialog_content = "No me gusta pelear, pero compraría una poción curativa solo para estar seguro.",
  ui_story_5086_50860201_69_dialog_content = "Ambos hacen buenos puntos. Estoy seguro de que el niñito también piensa de esa manera.",
  ui_story_5086_50860201_70_dialog_content = "(¡Para nada! ¿Y cuándo se convirtió esto en una historia de alta fantasía?)",
  ui_story_5086_50860201_71_dialog_content = "Después de comprar un conjunto completo de equipo, el niñito partió hacia la guarida del monstruo marino y lo desafió a una batalla final.",
  ui_story_5086_50860201_72_dialog_content = "Se sometió a años de entrenamiento y superó innumerables obstáculos—",
  ui_story_5086_50860201_73_dialog_content = "(¡La historia solo tiene lugar en un pequeño pueblo, aunque!)",
  ui_story_5086_50860201_74_dialog_content = "¡El enorme monstruo marino finalmente reconoció el poder y la valentía del chico, y por eso surgió de las profundidades para aceptar su desafío!",
  ui_story_5086_50860201_75_dialog_content = "¿Deseas reclamar mi tesoro? ¡Entonces primero debes derrotarme en batalla!",
  ui_story_5086_50860201_76_dialog_content = "El monstruo marino se rió arrogantemente del niñito.",
  ui_story_5086_50860201_77_dialog_content = "(¡Definitivamente he leído estas líneas en otro lugar antes! ¡Ella está empezando a contar una historia completamente diferente!)",
  ui_story_5086_50860201_78_dialog_content = "¡Wow!",
  ui_story_5086_50860201_79_dialog_content = "¡Y así el chico sacó su espada y se enfrentó a la enorme bestia en una batalla final!",
  ui_story_5086_50860302_1_dialog_content = "<color=#e8d9bb>Mientras los niños aplauden emocionados la historia de Maya, unas cuantas personas más entran a la zona de descanso.</color>",
  ui_story_5086_50860302_2_dialog_content = "Parece que podemos tomar un descanso rápido aquí, Sadie.",
  ui_story_5086_50860302_3_dialog_content = "¡Pero aún no hemos encontrado ninguna pista sobre la terrible cosa que está sucediendo aquí!",
  ui_story_5086_50860302_4_dialog_content = "Puede parecer tranquilo y pacífico por aquí, pero alguien podría necesitar desesperadamente nuestra ayuda en este momento. No podemos permitirnos holgazanear.",
  ui_story_5086_50860302_5_dialog_content = "Sé cómo te sientes, pero has estado corriendo desde que te despertaste esta mañana.",
  ui_story_5086_50860302_6_dialog_content = "Casi hemos buscado la mitad de la ciudad en busca de señales de peligro. A este ritmo, nos agotaremos antes de que logremos ayudar a alguien.",
  ui_story_5086_50860302_7_dialog_content = "Equilibrar el trabajo y el descanso, mantenerse en la mejor condición física—",
  ui_story_5086_50860302_8_dialog_content = "Así es como las ídolos se mantienen en la cima de sus juegos... y estoy segura de que lo mismo se aplica a los espadachines.",
  ui_story_5086_50860302_9_dialog_content = "Goldie...",
  ui_story_5086_50860302_10_dialog_content = "¿Qué es?",
  ui_story_5086_50860302_11_dialog_content = "Lo que acabas de decir... En realidad fue bastante genial.",
  ui_story_5086_50860302_12_dialog_content = "Entiendo. ¡Voy a descansar lo más duro que pueda ahora mismo!",
  ui_story_5086_50860302_13_dialog_content = "Uh, seguro. Pasemos las próximas horas recuperando nuestras fuerzas.",
  ui_story_5086_50860302_14_dialog_content = "Ya hemos explorado Harbor City durante el día, así que tal vez nuestro próximo movimiento sea vigilar la ciudad por la noche.",
  ui_story_5086_50860302_15_dialog_content = "Después de todo, muchas cosas solo se muestran bajo el amparo de la oscuridad.",
  ui_story_5086_50860302_16_dialog_content = "No podría haberlo dicho mejor yo misma, señorita Goldie.",
  ui_story_5086_50860302_17_dialog_content = "Sanae, harías bien en realizar también una observación nocturna.",
  ui_story_5086_50860302_18_dialog_content = "Ah... ¡Entendido! Tan pronto como volvamos... No, comenzaré a planificar mi nueva tarea de investigación ahora mismo!",
  ui_story_5086_50860302_19_dialog_content = "Quería preguntarte sobre eso antes.",
  ui_story_5086_50860302_20_dialog_content = "¿Qué es exactamente lo que están investigando ustedes dos? ¿En qué nueva industria está tratando de entrar Nina?",
  ui_story_5086_50860302_21_dialog_content = "Te pido que te abstengas de buscarme para obtener respuestas, Sanae. Después de todo, esta es tu tarea.",
  ui_story_5086_50860302_22_dialog_content = "Uh... E-Está bien entonces, permíteme explicar...",
  ui_story_5086_50860302_23_dialog_content = "Bueno, um, ves, la señorita Nina dice que una verdadera persona de negocios no se limita a una sola industria, y entonces...",
  ui_story_5086_50860302_24_dialog_content = "Y así, ella quiere crear una cadena de negocios expandiéndose más allá de la casa embrujada.",
  ui_story_5086_50860302_25_dialog_content = "Han ocurrido muchos cambios aquí en Harbor City, por lo que la señorita Nina nos pidió que viniéramos a buscar posibles oportunidades de negocio.",
  ui_story_5086_50860302_26_dialog_content = "Como comprar un acuario bien conocido y usarlo para capacitar a nuevos empleados, luego abrir uno similar en Umbraton... o algo así...",
  ui_story_5086_50860302_27_dialog_content = "La idea de abrir un acuario en Umbraton llena mi cabeza con algunas imágenes bastante aterradoras...",
  ui_story_5086_50860302_28_dialog_content = "¿No crees que deberíais reconsiderarlo? Hasta donde yo sé, Umbraton nunca ha tenido algo así antes.",
  ui_story_5086_50860302_29_dialog_content = "Eso es... Eso es lo que lo convierte en una oportunidad tan única! Umbraton también está cerca de un cuerpo de agua, así que tiene sentido.",
  ui_story_5086_50860302_30_dialog_content = "No son ustedes de quienes me preocupo, sino de sus futuros visitantes.",
  ui_story_5086_50860302_31_dialog_content = "Pero la señorita Nina está decidida a establecer esta cadena de negocios... por eso tengo que...",
  ui_story_5086_50860302_32_dialog_content = "D-De todos modos, todavía tengo que preguntar si quieren vender el acuario—",
  ui_story_5086_50860302_33_dialog_content = "¡Nunca haríamos eso!",
  ui_story_5086_50860302_34_dialog_content = "¿Maya? ¿No estabas contándoles una historia a esos niños? ... Oh, ya se fueron a casa.",
  ui_story_5086_50860302_35_dialog_content = "No sé qué buscan ustedes dos, pero—",
  ui_story_5086_50860302_36_dialog_content = "Este acuario existe para traer una sonrisa a cada invitado que pasa por sus puertas.",
  ui_story_5086_50860302_37_dialog_content = "Es un lugar lleno de recuerdos cariñosos y felices, y significa mucho para la gente de aquí.",
  ui_story_5086_50860302_38_dialog_content = "Ninguna cantidad de dinero podría comprarlo jamás.",
  ui_story_5086_50860302_39_dialog_content = "Ah... Lo-lo siento...",
  ui_story_5086_50860302_40_dialog_content = "¿Estás siendo grosera con nuestros invitados de nuevo, Maya?",
  ui_story_5086_50860302_41_dialog_content = "No creo que haya dicho algo malo.",
  ui_story_5086_50860302_42_dialog_content = "Tú también lo crees, ¿verdad señorita Stellandine? Después de todo, eres la que más ha renunciado por el bien de este acuario.",
  ui_story_5086_50860302_43_dialog_content = "Jejeje, me alegra que pienses tan bien de mí, Maya.",
  ui_story_5086_50860302_44_dialog_content = "Pero aún tenemos que ganar algo de dinero.",
  ui_story_5086_50860302_45_dialog_content = "¿Cómo más puedo cuidar de ti y del resto de nuestros amigos aquí en el acuario?",
  ui_story_5086_50860302_46_dialog_content = "Ya han sido obligados a abandonar sus hogares en el mar. Todo lo que puedo hacer es hacer sus vidas aquí lo más cómodas posible.",
  ui_story_5086_50860302_47_dialog_content = "¡He estado haciendo lo mejor que puedo para ganar dinero y cuidar de todos también! Eh... ¡Solo un segundo, por favor!",
  ui_story_5086_50860302_48_dialog_content = "¡Eche un vistazo a esto, señorita Stellandine! ¡Ya he hecho doscientos treinta y tres Nightium para nosotros!",
  ui_story_5086_50860302_49_dialog_content = "¡Eso es increíble, Maya! Estoy seguro de que la alcancía en tu habitación también ha sido bien alimentada.",
  ui_story_5086_50860302_50_dialog_content = "¡Jejeje!",
  ui_story_5086_50860302_51_dialog_content = "Si alguna vez tienes problemas de dinero, siempre puedes contar conmigo para ayudar, ¡Señorita Stellandine!",
  ui_story_5086_50860302_52_dialog_content = "No me importa darte hasta el último Nightium si es para el acuario.",
  ui_story_5086_50860302_53_dialog_content = "Gracias, Maya. Contaré contigo.",
  ui_story_5086_50860302_54_dialog_content = "¡Sólo déjamelo a mi!",
  ui_story_5086_50860302_55_dialog_content = "Mi... Qué muy sorprendente.",
  ui_story_5086_50860302_56_dialog_content = "¿Dijiste algo? ¿Minos?",
  ui_story_5086_50860302_57_dialog_content = "Nada en absoluto, mi querido amigo. No me prestes atención, simplemente estoy tomando algunas notas insignificantes.",
  ui_story_5086_50860302_58_dialog_content = "Después de todo, observar el entorno cultural local también es parte de nuestra investigación.",
  ui_story_5086_50860302_59_dialog_content = "Eres tan diligente como siempre, Minos.",
  ui_story_5086_50860302_60_dialog_content = "Pero por supuesto.",
  ui_story_5086_50860401_1_dialog_content = "Ya que todos ya se han reunido aquí, quizás sea hora de cumplir con mi palabra.",
  ui_story_5086_50860401_2_dialog_content = "¿Te importaría unirte a nosotros para almorzar?",
  ui_story_5086_50860401_3_dialog_content = "¡Claro! Justo empezaba a sentir hambre también.",
  ui_story_5086_50860401_4_dialog_content = "No tengo idea de cómo es la comida de Harbor City, pero realmente estoy deseando probarla.",
  ui_story_5086_50860401_5_dialog_content = "Maya, llevemos a nuestros invitados al restaurante.",
  ui_story_5086_50860401_6_dialog_content = "¡Bueno! ¡Por aquí, todos!",
  ui_story_5086_50860401_7_dialog_content = "¿Vamos también, Minos?",
  ui_story_5086_50860401_8_dialog_content = "Por favor, no se preocupen por nosotros.",
  ui_story_5086_50860401_9_dialog_content = "Sanae aún necesita compilar su informe sobre los hallazgos de esta mañana.",
  ui_story_5086_50860401_10_dialog_content = "Una vez que ella termine su trabajo, la acompañaré al restaurante.",
  ui_story_5086_50860401_11_dialog_content = "Por favor, disfrute de su comida.",
  ui_story_5086_50860401_12_dialog_content = "¿Eh? Q-Quiero decir... sí, estaremos allí en breve.",
  ui_story_5086_50860401_13_dialog_content = "Continúa con el buen trabajo, Sanae.",
  ui_story_5086_50860401_14_dialog_content = "Yo... haré lo mejor que pueda...",
  ui_story_5086_50860401_15_dialog_content = "Nos veremos en un rato entonces... Espera, ¿hacia dónde fueron Maya y Stellandine?",
  ui_story_5086_50860401_16_dialog_content = "Más allá de la exhibición de tiburones a la izquierda hay una escalera. Síguela hasta el segundo piso y gira a la izquierda, luego encontrarás el restaurante.",
  ui_story_5086_50860401_17_dialog_content = "Gracias Minos.",
  ui_story_5086_50860401_18_dialog_content = "Gira a la izquierda en el segundo piso... Huh, me pregunto por qué Minos sabe cómo llegar aquí...",
  ui_story_5086_50860401_19_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5086_50860401_20_dialog_content = "Ay...",
  ui_story_5086_50860401_21_dialog_content = "¡Maya! Lo siento, no te vi correr de esta manera.",
  ui_story_5086_50860401_22_dialog_content = "¿Estás bien?",
  ui_story_5086_50860401_23_dialog_content = "Jeje, ¡estoy bien! Además, debería ser yo quien se disculpara.",
  ui_story_5086_50860401_24_dialog_content = "Estaba tan ocupado liderando el camino que olvidé ver si todavía me estabas siguiendo... ¡Ah!",
  ui_story_5086_50860401_25_dialog_content = "<color=#e8d9bb>De repente, Maya saca su cuaderno y lo hojea frenéticamente.</color>",
  ui_story_5086_50860401_26_dialog_content = "Oh no. ¿Dónde lo escribí?",
  ui_story_5086_50860401_27_dialog_content = "¿Qué estás buscando?",
  ui_story_5086_50860401_28_dialog_content = "Lo siento mucho, señor.",
  ui_story_5086_50860401_29_dialog_content = "¡Pero parece que olvidé escribir tu nombre!",
  ui_story_5086_50860401_30_dialog_content = "No creo que lo encuentres en tus notas. Después de todo, aún no me he presentado correctamente.",
  ui_story_5086_50860401_31_dialog_content = "Mi nombre es PlayerName, y soy Caelestita. Es un placer conocerte, Maya.",
  ui_story_5086_50860401_32_dialog_content = "¡Soy Maya, una aprendiz que trabaja en el acuario!",
  ui_story_5086_50860401_X32_dialog_content = "¡Y ahora que nos hemos presentado, eso nos hace amigos!",
  ui_story_5086_50860401_33_dialog_content = "Por aquí, PlayerName! No fue fácil, pero guardé el mejor asiento de la casa solo para ti.",
  ui_story_5086_50860401_34_dialog_content = "¡Guau, puedo ver todo el tanque desde aquí!",
  ui_story_5086_50860401_35_dialog_content = "¡Qué vista increíble para acompañar nuestro almuerzo!",
  ui_story_5086_50860401_36_dialog_content = "El restaurante es tan grande y lujoso también. ¿Esto es realmente una parte del acuario?",
  ui_story_5086_50860401_37_dialog_content = "Eres muy perceptivo, PlayerName.",
  ui_story_5086_50860401_38_dialog_content = "Estrictamente hablando, este restaurante no pertenece únicamente a nuestro acuario, no.",
  ui_story_5086_50860401_39_dialog_content = "Debido al rápido desarrollo de los complejos turísticos en la zona, algunos de los negocios locales más pequeños han sufrido graves contratiempos financieros.",
  ui_story_5086_50860401_40_dialog_content = "Para aliviar parte de la tensión, varios dueños de negocios han decidido unirse para competir en la floreciente industria del turismo.",
  ui_story_5086_50860401_41_dialog_content = "Este restaurante es solo uno de esos emprendimientos.",
  ui_story_5086_50860401_42_dialog_content = "Todos trabajan muy duro para este restaurante, ¡y la comida aquí es increíble!",
  ui_story_5086_50860401_43_dialog_content = "En mi primer día aquí, estaba decidido a comer cada plato del menú.",
  ui_story_5086_50860401_44_dialog_content = "Pero hasta el día de hoy, solo he podido probar algunos de ellos.",
  ui_story_5086_50860401_45_dialog_content = "Todavía hay mucho tiempo, Maya. No hay necesidad de apresurarse.",
  ui_story_5086_50860401_46_dialog_content = "Ahora bien, ¿qué deberíamos comer hoy?",
  ui_story_5086_50860401_47_dialog_content = "Eso depende, ¿qué comimos ayer? Hmm...",
  ui_story_5086_50860401_48_dialog_content = "No lo escribí en mis notas. ¿También olvidé hacer eso?",
  ui_story_5086_50860401_49_dialog_content = "Bueno, ordena lo que quieras-",
  ui_story_5086_50860401_50_dialog_content = "Voy a preguntarle a uno de los meseros sobre lo que comiste ayer.",
  ui_story_5086_50860401_51_dialog_content = "Oh, no tienes que hacer eso. No es gran cosa ni nada.",
  ui_story_5086_50860401_52_dialog_content = "Pero te has fijado una meta, ¿no es así Maya?",
  ui_story_5086_50860401_53_dialog_content = "No es ningún problema en absoluto. Incluso si olvidas tus pedidos, el restaurante tiene un menú solo para ti, en realidad.",
  ui_story_5086_50860401_54_dialog_content = "Siempre estás tan dispuesto a ayudar a todos, por lo que ellos también quieren ayudarte a realizar tu objetivo.",
  ui_story_5086_50860401_55_dialog_content = "Vuelvo enseguida.",
  ui_story_5086_50860401_56_dialog_content = "La señorita Stellandine es una persona tan agradable.",
  ui_story_5086_50860401_57_dialog_content = "¿Verdad? ¡Ella es la persona más amable en todo el mundo!",
  ui_story_5086_50860401_58_dialog_content = "Es tan amable y gentil, y se encarga personalmente de cada uno de los animales en el acuario.",
  ui_story_5086_50860401_59_dialog_content = "No solo eso, sino que me dijo que el acuario podría ser mi hogar cuando no tenía a dónde ir.",
  ui_story_5086_50860401_60_dialog_content = "¿Eh? Entonces, ¿eso significa que eres nuevo aquí?",
  ui_story_5086_50860401_61_dialog_content = "En serio, PlayerName? Sé que soy olvidadizo y un poco torpe, ¡pero no soy completamente inútil, ya sabes!",
  ui_story_5086_50860401_62_dialog_content = "Si hubiera estado aquí por mucho tiempo, ¿realmente crees que seguiría siendo un aprendiz?",
  ui_story_5086_50860401_63_dialog_content = "Podría decir mucho más sobre esto... pero haces un buen punto, Maya.",
  ui_story_5086_50860401_64_dialog_content = "Parece que eres realmente popular por aquí.",
  ui_story_5086_50860401_65_dialog_content = "Aunque tu mala memoria te impidió recordar el final de tu historia, a los niños les encantó de todos modos.",
  ui_story_5086_50860401_66_dialog_content = "¿Eh? ¿Qué historia?",
  ui_story_5086_50860401_67_dialog_content = "El que le contaste a los niños en el área de descanso antes.",
  ui_story_5086_50860401_68_dialog_content = "Oh, ¿realmente les conté una historia?",
  ui_story_5086_50860401_69_dialog_content = "<size=50>¿Quieres decir que ya lo olvidaste?</size>",
  ui_story_5086_50860401_70_dialog_content = "Bueno, no parece que lo haya escrito en mis notas—",
  ui_story_5086_50860401_71_dialog_content = "Si tuvieras que anotar cada pequeño detalle así, no creo que un solo cuaderno sería suficiente para un día.",
  ui_story_5086_50860401_72_dialog_content = "¡Pero aún recuerdas la historia, así que puedes contármela! Por favor, PlayerName, ¡realmente quiero escucharla!",
  ui_story_5086_50860401_73_dialog_content = "¡D-Demasiado cerca! Te contaré la historia, pero solo dame algo de espacio—",
  ui_story_5086_50860401_74_dialog_content = "Veamos, era sobre un niñito...",
  ui_story_5086_50860402_1_dialog_content = "¡Qué historia tan emocionante. ¿La inventaste de nuevo, Maya?",
  ui_story_5086_50860402_2_dialog_content = "¡Señorita Stellandine! ¿Puedes leer mentes?",
  ui_story_5086_50860402_3_dialog_content = "No, Maya, es solo que tus historias son muy especiales.",
  ui_story_5086_50860402_4_dialog_content = "No importa lo que suceda en ellos, o si los personajes son buenos o malos—",
  ui_story_5086_50860402_5_dialog_content = "Tus historias siempre terminan con todos reuniéndose y viviendo felices para siempre.",
  ui_story_5086_50860402_6_dialog_content = "Bueno, así es como se supone que deben ir los cuentos de hadas, incluso los que invento.",
  ui_story_5086_50860402_7_dialog_content = "...",
  ui_story_5086_50860402_8_dialog_content = "Supongo que tienes razón. Además, incluso si lees una historia triste, la olvidarás al día siguiente.",
  ui_story_5086_50860402_9_dialog_content = "Aun así, el olvido de Maya es mucho más grave que cualquier cosa que haya visto. ¿No deberíamos preocuparnos más por ello?",
  ui_story_5086_50860402_10_dialog_content = "Quizás... Pero la llevé a ver a un doctor, y sus resultados de salud fueron perfectamente normales.",
  ui_story_5086_50860402_11_dialog_content = "El doctor tampoco pudo identificar la fuente de su olvido.",
  ui_story_5086_50860402_12_dialog_content = "No puede ser fácil, vivir así...",
  ui_story_5086_50860402_13_dialog_content = "No es broma. ¿Cómo se supone que debes seguir un manga si ni siquiera puedes recordar lo que sucedió en el último número?",
  ui_story_5086_50860402_14_dialog_content = "¿Y qué hay de todas las cosas geniales que has visto en la vida? Ninguna experiencia en el mundo vale mucho si ni siquiera puedes recordarlas.",
  ui_story_5086_50860402_15_dialog_content = "Sadie! No deberías hablar así de la señorita Maya, ni de nadie más en ese caso. Es grosero.",
  ui_story_5086_50860402_16_dialog_content = "Ah, estás bien. Lo siento por eso, Maya.",
  ui_story_5086_50860402_17_dialog_content = "Aww... Pobre señorita Maya.",
  ui_story_5086_50860402_18_dialog_content = "Hey, se supone que no debemos hablar de las personas de esa manera.",
  ui_story_5086_50860402_19_dialog_content = "Lo sé, pero... cuando pienso en lo difícil que debe ser su vida, yo...",
  ui_story_5086_50860402_20_dialog_content = "Señorita Maya, ¿por qué no te conviertes en una sirvienta como yo?",
  ui_story_5086_50860402_21_dialog_content = "El trabajo puede ser un poco duro a veces... pero siempre estarás rodeado de buena gente...",
  ui_story_5086_50860402_22_dialog_content = "?",
  ui_story_5086_50860402_23_dialog_content = "¡Gracias, todos! Aunque realmente no sé qué está pasando, todos parecen realmente preocupados por mí.",
  ui_story_5086_50860402_24_dialog_content = "Pero deberías saber, de hecho, estoy realmente feliz aquí.",
  ui_story_5086_50860402_25_dialog_content = "¿Ves? Si algo importante sucede en mi vida, siempre lo escribo en mis notas para no olvidarlo.",
  ui_story_5086_50860402_26_dialog_content = "Ayer, Maya se perdió en la calle. Una anciana con delantal ayudó a Maya a encontrar el camino y le regaló una naranja.",
  ui_story_5086_50860402_27_dialog_content = "Eso es porque salvaste a su nieto de ahogarse en el océano ese día. Ella te estaba agradeciendo, Maya.",
  ui_story_5086_50860402_28_dialog_content = "El día antes de eso, olvidé que nuestro refrigerador estaba roto, por lo que no pude hacer hielo para algunos de nuestros animales. Pero afortunadamente, un amable vendedor de bocadillos me dio un gran cubo de hielo.",
  ui_story_5086_50860402_29_dialog_content = "También recuerdo eso. Estabas ayudándole a atraer más clientes, ya que su negocio estaba yendo tan mal ese día. También se te ocurrieron algunas ideas realmente exageradas.",
  ui_story_5086_50860402_30_dialog_content = "La semana pasada, cuando perdí mi diagrama de flujo para nuestro evento interactivo, los niños se unieron para ayudarme a dirigir el espectáculo. ¡Fue increíble!",
  ui_story_5086_50860402_31_dialog_content = "Nadie estaba dispuesto a participar al principio, pero gracias a la habilidad de Maya para trabajar tan bien con los niños, el evento se convirtió en un gran éxito.",
  ui_story_5086_50860402_32_dialog_content = "Y la semana anterior a esa, y el mes pasado, e incluso el año pasado...",
  ui_story_5086_50860402_33_dialog_content = "<color=#e8d9bb>Cada página del cuaderno de Maya está llena de recuerdos brillantes y positivos.</color>",
  ui_story_5086_50860402_34_dialog_content = "<color=#e8d9bb>Ella describe estos momentos coloridos de su vida cotidiana con perfecta claridad.</color>",
  ui_story_5086_50860402_35_dialog_content = "<color=#e8d9bb>De repente, una tarjeta se cae de las páginas del cuaderno.</color>",
  ui_story_5086_50860402_36_dialog_content = "<color=#e8d9bb>Está garabateado con unas pocas líneas de escritura. Aunque la letra parece infantil, lleva cierta gravedad.</color>",
  ui_story_5086_50860402_37_dialog_content = "¿Qué grabaste en esa tarjeta, Maya?",
  ui_story_5086_50860402_38_dialog_content = "¡Oh, esto? ¡Soy yo!",
  ui_story_5086_50860402_39_dialog_content = "¿Tú?",
  ui_story_5086_50860402_40_dialog_content = "¡Así es! Siempre que algo súper-extra-importante sucede en mi vida, lo escribo en esta tarjeta y lo leo todos los días.",
  ui_story_5086_50860402_41_dialog_content = "Aunque no puedo recordar nada de lo que está escrito en él, estos recuerdos son una gran parte de mí.",
  ui_story_5086_50860402_42_dialog_content = "<color=#e8d9bb>Maya recoge suavemente la tarjeta y cierra los ojos.</color>",
  ui_story_5086_50860402_43_dialog_content = "<color=#e8d9bb>Claramente, ella no necesita mirar la tarjeta para saber qué dice.</color>",
  ui_story_5086_50860402_44_dialog_content = "Elvis me desea una vida larga y feliz.",
  ui_story_5086_50860402_45_dialog_content = "La señorita Stellandine me dio un hogar en su acuario.",
  ui_story_5086_50860402_46_dialog_content = "Amo a todos aquí en Harbor City.",
  ui_story_5086_50860402_47_dialog_content = "Oh, Señorita Maya...",
  ui_story_5086_50860402_48_dialog_content = "Si alguna vez quieres visitar Umbraton, me aseguraré de cuidarte bien. Es lo menos que un espadachín podría hacer.",
  ui_story_5086_50860402_49_dialog_content = "Creo que tienes el potencial para convertirte en un ídolo también, señorita Maya. ¿Quieres intentarlo?",
  ui_story_5086_50860402_50_dialog_content = "¿Eh? Espera, acabo de decir que realmente disfruto de mi vida aquí. No quiero ir a ningún otro lugar—",
  ui_story_5086_50860402_51_dialog_content = "Señorita Stellandine, ella mencionó a alguien llamado Elvis justo ahora...",
  ui_story_5086_50860402_52_dialog_content = "El señor de la ciudad, sí. Tuvo la amabilidad de cuidar de Maya en el pasado, ya que no tenía padres de los que hablar y su memoria aún era poco confiable. Todos en la ciudad sabían esto.",
  ui_story_5086_50860402_53_dialog_content = "También era conocida por correr por la ciudad y prestar ayuda a cualquiera que lo necesitara.",
  ui_story_5086_50860402_54_dialog_content = "Por esa razón, algunos de los residentes de nuestra ciudad comenzaron a llamarla la Princesa Mendiga de Harbor City.",
  ui_story_5086_50860402_55_dialog_content = "Cuando Harbor City fue atacada durante la crisis reciente, parece que Maya también desapareció.",
  ui_story_5086_50860402_56_dialog_content = "Nadie sabía si algo le había sucedido, o si el señor de la ciudad tenía algo que ver con ello...",
  ui_story_5086_50860402_57_dialog_content = "Dado que ella no puede recordar nada al respecto, discernir la verdad es prácticamente imposible ahora.",
  ui_story_5086_50860402_58_dialog_content = "Todo lo que sé es que unos días después del incidente, ella apareció de repente en la entrada del acuario, pidiendo un trabajo.",
  ui_story_5086_50860402_59_dialog_content = "Al ver que ya no tenía un guardián, le ofrecí vivir y trabajar aquí como aprendiz.",
  ui_story_5086_50860402_60_dialog_content = "Nunca hice nada particularmente especial, sin embargo, ella escribe sobre mí como si fuera algún tipo de santo.",
  ui_story_5086_50860402_61_dialog_content = "Honestamente.",
  ui_story_5086_50860402_62_dialog_content = "(Elvis solía cuidar de ella... ¿Podría ser que Jeno eligió a Maya para ser su mensajera?)",
  ui_story_5086_50860402_63_dialog_content = "Señorita Stellandine, podría tener una forma de ayudar a Maya a recuperar algunos de sus recuerdos.",
  ui_story_5086_50860402_64_dialog_content = "¿En serio?",
  ui_story_5086_50860402_65_dialog_content = "Sí, y creo que hay una buena posibilidad de que también funcione.",
  ui_story_5086_50860402_66_dialog_content = "Veo.",
  ui_story_5086_50860402_67_dialog_content = "Por mucho que me gustaría aceptar tu oferta, como guardián temporal de Maya, creo que ella debería ser la que decida.",
  ui_story_5086_50860500_1_dialog_content = "¿Dices que puedes ayudarme a recuperar mis recuerdos?",
  ui_story_5086_50860500_2_dialog_content = "No tenía idea de que pudieras hacer algo tan increíble, PlayerName!",
  ui_story_5086_50860500_3_dialog_content = "Como Caelestite, puedo usar mis habilidades psíquicas para conectarme con la mente de las personas. Aún no he dominado completamente mis poderes, pero definitivamente puedo usarlos para algo como esto.",
  ui_story_5086_50860500_4_dialog_content = "Al adentrarme en tus recuerdos, podría ser capaz de encontrar algo que tú no tienes forma de ver por ti mismo.",
  ui_story_5086_50860500_5_dialog_content = "¿El poder de conectar con las mentes de las personas... Es eso lo que es?",
  ui_story_5086_50860500_6_dialog_content = "Sí, más o menos.",
  ui_story_5086_50860500_7_dialog_content = "Hmm... Déjame mirar mis notas una vez más.",
  ui_story_5086_50860500_8_dialog_content = "?",
  ui_story_5086_50860500_9_dialog_content = "...",
  ui_story_5086_50860500_10_dialog_content = "Lo siento, pero no puedo hacer eso.",
  ui_story_5086_50860500_11_dialog_content = "¿Eh? ¿Es porque hay algo que no quieres que vea?",
  ui_story_5086_50860500_12_dialog_content = "¡No, eso no es!",
  ui_story_5086_50860500_13_dialog_content = "Es solo que no se supone que debo perturbar el sueño de mi antepasado.",
  ui_story_5086_50860500_14_dialog_content = "¿Tu antepasado?",
  ui_story_5086_50860500_15_dialog_content = "Así es. Mis recuerdos olvidados probablemente están con mi antepasado en este momento, junto con mis padres.",
  ui_story_5086_50860500_16_dialog_content = "Por eso no tengo prisa por recuperar las cosas ahora mismo.",
  ui_story_5086_50860500_17_dialog_content = "A veces me siento un poco solo, pero puedo soportarlo.",
  ui_story_5086_50860500_18_dialog_content = "Porque algún día, cuando mi sueño finalmente termine, podré recuperar todo lo que he perdido.",
  ui_story_5086_50860500_19_dialog_content = "Uh, Maya... ¿De qué estás hablando?",
  ui_story_5086_50860500_20_dialog_content = "¿Quieres decir que no lo sabes, PlayerName?",
  ui_story_5086_50860500_21_dialog_content = "Todo este mundo es solo un sueño.",
  ui_story_5086_50860500_22_dialog_content = "¿Qué quieres decir? Claramente estamos en el mundo real ahora mismo. Pellízcate las mejillas, si no me crees!",
  ui_story_5086_50860500_23_dialog_content = "Y aunque estuviéramos en un sueño, ¿de quién sería el sueño? ¿Tuyo?",
  ui_story_5086_50860500_24_dialog_content = "Un sueño es solo un sueño. El tuyo no es diferente al mío, o al de cualquier otra persona.",
  ui_story_5086_50860500_25_dialog_content = "Mis padres me vieron en sus sueños, que es la única razón por la que estoy aquí en primer lugar.",
  ui_story_5086_50860500_26_dialog_content = "Mi antepasado también me está vigilando desde dentro del sueño.",
  ui_story_5086_50860500_27_dialog_content = "¿Así que piensas que todos somos solo personajes dentro de algún sueño, Maya?",
  ui_story_5086_50860500_28_dialog_content = "¡Por supuesto que no! Todos simplemente viven en una burbuja, eso es todo. En cuanto a esas personas importantes que hemos perdido... están viviendo en el sueño más dulce de todos, cuidándonos.",
  ui_story_5086_50860500_29_dialog_content = "Entonces, ¿quién es exactamente tu antepasado?",
  ui_story_5086_50860500_30_dialog_content = "El progenitor de toda mi línea de sangre, un guardián submarino cuya mirada ve más allá del flujo del tiempo.",
  ui_story_5086_50860500_31_dialog_content = "O al menos eso es lo que acaba de decir mi antepasado.",
  ui_story_5086_50860500_32_dialog_content = "Por eso no debería perturbar el otro mundo por algo tan pequeño como recuperar mis recuerdos.",
  ui_story_5086_50860500_33_dialog_content = "Definitivamente no debería molestar a mi antepasado por eso tampoco.",
  ui_story_5086_50860500_34_dialog_content = "Todavía me siento bastante perdido ahora mismo...",
  ui_story_5086_50860500_35_dialog_content = "Lo siento...",
  ui_story_5086_50860500_36_dialog_content = "Pero lo que sí entiendo es que hay algo más importante para ti que recuperar tus recuerdos.",
  ui_story_5086_50860500_37_dialog_content = "!",
  ui_story_5086_50860500_38_dialog_content = "Aunque tengo mucha curiosidad por saber más al respecto... No te obligaré a hacer nada que no estés dispuesta a hacer, Maya.",
  ui_story_5086_50860500_39_dialog_content = "PlayerName...",
  ui_story_5086_50860500_40_dialog_content = "¡Realmente me gustas!",
  ui_story_5086_50860500_41_dialog_content = "¿Eh? No, espera... Uh... Todavía estoy...",
  ui_story_5086_50860500_42_dialog_content = "Ya hemos pasado por esto antes, Maya. No puedes decir cosas así a los chicos tan casualmente.",
  ui_story_5086_50860500_43_dialog_content = "¡Yo también te quiero mucho, señorita Stellandine!",
  ui_story_5086_50860500_44_dialog_content = "Oh, dulce niño... No importa. Todavía hay trabajo que hacer esta tarde, así que intenta descansar por ahora.",
  ui_story_5086_50860500_45_dialog_content = "Pero quiero escuchar un cuento de hadas.",
  ui_story_5086_50860500_46_dialog_content = "¡Como ya he olvidado la historia de esta mañana, escuchar una nueva es mi forma de descansar!",
  ui_story_5086_50860500_47_dialog_content = "Realmente pareces disfrutar de los cuentos de hadas, Maya.",
  ui_story_5086_50860500_48_dialog_content = "Eso es porque son registros de diferentes sueños.",
  ui_story_5086_50860500_49_dialog_content = "Y me encanta ver todo tipo de sueños diferentes.",
  ui_story_5086_50860500_50_dialog_content = "Registros de sueños, eh...",
  ui_story_5086_50860500_51_dialog_content = "Muy bien, entonces. Resulta que tengo una historia que vale la pena contar ahora mismo.",
  ui_story_5086_50860500_52_dialog_content = "Se trata de una pequeña niña y un sueño desesperado.",
  ui_story_5086_50860500_53_dialog_content = "¡Hurra! ¡Eres la mejor, Señorita Stellandine!",
  ui_story_5086_50860500_54_dialog_content = "Había una vez, una chica que vivía bajo el mar.",
  ui_story_5086_50860500_55_dialog_content = "El mar le proporcionó todo tipo de cosas: comida deliciosa, tesoros abundantes y todos los juguetes y diversiones que pudiera desear.",
  ui_story_5086_50860500_56_dialog_content = "Pero también faltaban muchas cosas en su mundo, como el fuego y el ruido... y el amor.",
  ui_story_5086_50860500_57_dialog_content = "Un día, durante una peligrosa tormenta, la joven rescató a un príncipe que había caído de su barco. Naturalmente, se enamoró perdidamente de él.",
  ui_story_5086_50860500_58_dialog_content = "¡Guau! ¡Un príncipe de la tierra y una princesa del mar!",
  ui_story_5086_50860500_59_dialog_content = "Poco después, la tripulación del príncipe lo subió de nuevo al barco y regresaron a su reino. Pasó mucho tiempo, pero el príncipe nunca volvió.",
  ui_story_5086_50860500_60_dialog_content = "¿Qué? Pero por qué...",
  ui_story_5086_50860500_61_dialog_content = "Así que la chica visitó a la bruja del mar y le ofreció su posesión más preciada a cambio del poder de caminar en tierra.",
  ui_story_5086_50860500_62_dialog_content = "Cuando finalmente llegó a la orilla, luchó por usar sus nuevas piernas. Pero estaba decidida a ver al príncipe de nuevo, así que se arrastró hasta que pudo caminar, y caminó hasta que pudo correr...",
  ui_story_5086_50860500_63_dialog_content = "¡Sí! ¡No te rindas, princesa! ¡Tú puedes hacerlo!",
  ui_story_5086_50860500_64_dialog_content = "Pero fue entonces cuando la chica descubrió que algo terrible había sucedido. A cambio de sus nuevas piernas, la bruja había quitado lo que más apreciaba: sus recuerdos de su amado príncipe.",
  ui_story_5086_50860500_65_dialog_content = "Ella estaba en una multitud de personas desconocidas, el rostro y la voz de su amante ahora eran un completo misterio para ella.",
  ui_story_5086_50860500_66_dialog_content = "De hecho, la chica comenzó a dudar si realmente había estado enamorada desde el principio.",
  ui_story_5086_50860500_67_dialog_content = "Ella no tenía manera de volver a encontrarse con el que amaba nunca más.",
  ui_story_5086_50860500_68_dialog_content = "¿Qué pasó después?",
  ui_story_5086_50860500_69_dialog_content = "Nada, querido. Así es como termina la historia.",
  ui_story_5086_50860500_70_dialog_content = "¿Eh? ¡P-Pero la chica aún no ha encontrado a su príncipe!",
  ui_story_5086_50860500_71_dialog_content = "¡Ella tampoco recuperó sus recuerdos! ¡Ni siquiera puede recordar cómo se ve él!",
  ui_story_5086_50860500_72_dialog_content = "Es una historia tan triste y desesperada...",
  ui_story_5086_50860500_73_dialog_content = "Lo contaste tan bien, señorita Stellandine... pero no puedo evitar sentirme triste ahora...",
  ui_story_5086_50860500_74_dialog_content = "Maya...",
  ui_story_5086_50860500_75_dialog_content = "¡Siento lo mismo! ¿Por qué... por qué la vida tiene que ser tan injusta con esa pobre niña?",
  ui_story_5086_50860500_76_dialog_content = "¿Sanae? ¿Y todos los demás... Cuánto tiempo han estado aquí?",
  ui_story_5086_50860500_77_dialog_content = "¡Desde que comenzó la historia, por supuesto! ¿Ves? Sadie se está bajando el sombrero porque no quiere que nadie vea sus lágrimas.",
  ui_story_5086_50860500_78_dialog_content = "No estoy llorando. Así es como los espadachines muestran su respeto y gratitud.",
  ui_story_5086_50860500_79_dialog_content = "¡Uh-huh, lo que tú digas!",
  ui_story_5086_50860500_80_dialog_content = "Aun así, me sorprende que tanta gente no haya oído hablar de este cuento de hadas antes. Siempre pensé que era una historia bastante conocida.",
  ui_story_5086_50860500_81_dialog_content = "Solo me interesan las historias de espadachines.",
  ui_story_5086_50860500_82_dialog_content = "Si hubiera algún espadachín en su mundo, estoy seguro de que la ayudarían a recuperar sus recuerdos en un instante.",
  ui_story_5086_50860500_83_dialog_content = "Tienes razón, pero incluso sin un héroe así, estoy seguro de que alguien estaría dispuesto a ayudarla.",
  ui_story_5086_50860500_84_dialog_content = "Los cuentos de hadas no se supone que tengan finales tristes.",
  ui_story_5086_50860500_85_dialog_content = "Pero... Es posible que el príncipe ya se haya olvidado de ella... De hecho, podría haberse casado ya con otra princesa...",
  ui_story_5086_50860500_86_dialog_content = "Mientras tanto, la pobre chica fue dejada sola en la orilla... Es tan trágico... *sollozando*",
  ui_story_5086_50860500_87_dialog_content = "Eh, Sanae? Es solo una historia, sabes.",
  ui_story_5086_50860500_88_dialog_content = "Waaaaaaah—",
  ui_story_5086_50860500_89_dialog_content = "Oh no, Sanae no deja de llorar... ¡Haz algo, Manae! ¡Por favor!",
  ui_story_5086_50860500_90_dialog_content = "...",
  ui_story_5086_50860500_91_dialog_content = "¡Waaaaaah! ¿Por qué la chica tuvo que pagar un precio tan terrible? ¡Esa bruja no es más que una gran malvada! ¿Y por qué el príncipe nunca la buscó? ¡Waaaaaaah!",
  ui_story_5086_50860500_92_dialog_content = "¿Por qué lo empeoras, Manae?",
  ui_story_5086_50860500_93_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860500_94_dialog_content = "<color=#e8d9bb>De repente, una suave canción comienza a sonar.</color>",
  ui_story_5086_50860500_95_dialog_content = "<color=#e8d9bb>Tan ligera y distante como la suave brisa marina, la melodía sube y baja como las olas que surgen del silencioso fondo del océano.</color>",
  ui_story_5086_50860500_96_dialog_content = "<color=#e8d9bb>Cada nota resuena claramente de la concha en las manos de Maya.</color>",
  ui_story_5086_50860500_97_dialog_content = "<color=#e8d9bb>Por un momento, la mente de cada persona se desvanece al ritmo de su canción...</color>",
  ui_story_5086_50860500_98_dialog_content = "<color=#e8d9bb>Con sus corazones aliviados por la melodía, comienzan a olvidar todos sus problemas.</color>",
  ui_story_5086_50860500_99_dialog_content = "¡Qué hermosa canción... Qué fue eso justo ahora, señorita Maya?",
  ui_story_5086_50860500_100_dialog_content = "No sé mucho sobre música, pero esa canción me hizo pensar en mi manga de espadachines favorito justo ahora.",
  ui_story_5086_50860500_101_dialog_content = "Me siento profundamente honrado de haber tenido el privilegio de escuchar una canción tan espléndida.",
  ui_story_5086_50860500_102_dialog_content = "Estás aquí también, Minos? ... ¿Eh?",
  ui_story_5086_50860500_103_dialog_content = "¿Cuándo se durmió Sanae?",
  ui_story_5086_50860500_104_dialog_content = "La música de Maya tiene el poder de calmar los corazones de las personas. Es especialmente útil en situaciones como esta.",
  ui_story_5086_50860500_105_dialog_content = "Estoy seguro de que este niño está teniendo un sueño maravilloso mientras hablamos.",
  ui_story_5086_50860500_106_dialog_content = "Sí. Ahora que ha olvidado toda su tristeza, finalmente puede relajarse.",
  ui_story_5086_50860500_107_dialog_content = "La joven Sanae ha estado esforzándose por completar la tarea que nuestra señora le ha dado. Esta es una oportunidad perfecta para que descanse.",
  ui_story_5086_50860500_108_dialog_content = "Detrás del acuario están los cuartos de vivienda para nuestros empleados. Hay muchas habitaciones disponibles.",
  ui_story_5086_50860500_109_dialog_content = "Si no te importa, ella es más que bienvenida a dormir allí.",
  ui_story_5086_50860500_110_dialog_content = "El resto de ustedes es libre de hacer uso de esas habitaciones también.",
  ui_story_5086_50860500_111_dialog_content = "Creo que haré justamente eso. Su hospitalidad es muy apreciada, señorita Stellandine.",
  ui_story_5086_50860500_112_dialog_content = "Sr. PlayerName, ¿podrías ayudarme a acompañar a Sanae a su habitación, por favor?",
  ui_story_5086_50860500_113_dialog_content = "¿Yo? Sí, claro.",
  ui_story_5086_50860500_114_dialog_content = "Tienes mi agradecimiento.",
  ui_story_5086_50860601_1_dialog_content = "Minos, ¿hubo alguna razón específica por la que me pediste ayuda?",
  ui_story_5086_50860601_2_dialog_content = "¿Te ruego me disculpes?",
  ui_story_5086_50860601_3_dialog_content = "Podría entender si cualquier otra persona pidiera mi ayuda, pero estamos hablando de ti.",
  ui_story_5086_50860601_4_dialog_content = "Para Minos, el mayordomo todopoderoso de la familia Andersen, pedir mi ayuda es tan improbable como que los Jardines de las Nubes sean el centro exacto del universo entero.",
  ui_story_5086_50860601_5_dialog_content = "Creo que me consideras con demasiada estima, amigo mío. Sin embargo, es exactamente como sospechas.",
  ui_story_5086_50860601_6_dialog_content = "¿Estás consciente del conflicto que recientemente afectó a Harbor City, sí?",
  ui_story_5086_50860601_7_dialog_content = "... Lo soy.",
  ui_story_5086_50860601_8_dialog_content = "Parece que sabes mucho más sobre la situación de lo que te importa admitir.",
  ui_story_5086_50860601_9_dialog_content = "¿E-Es tan obvio?",
  ui_story_5086_50860601_10_dialog_content = "Simplemente estoy haciendo otra pequeña observación, nada más.",
  ui_story_5086_50860601_11_dialog_content = "Pero me desvío. En los últimos diez años, el Señor de la Ciudad Elvis sacrificó tanto sangre como sudor en medidas igualmente grandes por el bien de Harbor City.",
  ui_story_5086_50860601_12_dialog_content = "Fue gracias a sus esfuerzos que este pueblo se convirtió en un lugar de tanta paz y prosperidad.",
  ui_story_5086_50860601_13_dialog_content = "Pero a raíz de ese reciente incidente y su desaparición, Harbor City cayó bajo la administración de Lumopolis.",
  ui_story_5086_50860601_14_dialog_content = "Es por esta razón exacta que la señorita Nina cree que Harbor City está llena de oportunidades de negocio.",
  ui_story_5086_50860601_15_dialog_content = "Pero también vale la pena señalar que cuando una organización está atrapada en medio de la agitación, los gusanos tienden a reproducirse incluso en los rincones más pequeños.",
  ui_story_5086_50860601_16_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_5086_50860601_17_dialog_content = "Estoy seguro de que ya lo has notado, Sr. PlayerName. Todo tipo de rumores extraños y perturbadores han estado circulando dentro y alrededor de Harbor City.",
  ui_story_5086_50860601_18_dialog_content = "Temo que los recientes conflictos de la ciudad sean los culpables de ellos, y estos rumores desagradables solo sirven para devaluar Harbor City a los ojos del mundo.",
  ui_story_5086_50860601_19_dialog_content = "Ahora que lo mencionas, Sadie y Goldie solo vinieron aquí desde Umbraton porque escucharon algo perturbador sobre Harbor City.",
  ui_story_5086_50860601_20_dialog_content = "Pero incluso ahora, todavía no han encontrado nada para corroborar los rumores.",
  ui_story_5086_50860601_21_dialog_content = "Todo es tan extraño. No me sorprende que Sadie viniera por este tipo de cosas, pero ¿por qué Goldie también se unió?",
  ui_story_5086_50860601_22_dialog_content = "¿También siente ella el peligro aquí?",
  ui_story_5086_50860601_23_dialog_content = "... Espera.",
  ui_story_5086_50860601_24_dialog_content = "Mis sospechas fueron correctas la última vez, ¿no es así? Esto es similar a lo que sucedió cuando te conocí por primera vez, Minos...",
  ui_story_5086_50860601_25_dialog_content = "¿Me estás diciendo que algo terrible como eso está a punto de suceder otra vez?",
  ui_story_5086_50860601_26_dialog_content = "Por supuesto que no. Solo soy un humilde mayordomo, no un profeta.",
  ui_story_5086_50860601_27_dialog_content = "Uf, eso es un alivio.",
  ui_story_5086_50860601_28_dialog_content = "Sin embargo, hice una serie de descubrimientos inquietantes mientras realizaba nuestra investigación de negocios.",
  ui_story_5086_50860601_29_dialog_content = "Por ejemplo, ha habido varios casos de viajeros que desaparecen en Harbor City.",
  ui_story_5086_50860601_30_dialog_content = "Además, cada uno de ellos expresó un cierto deseo poco antes de desaparecer—",
  ui_story_5086_50860601_31_dialog_content = "A saber, que querían ir al acuario.",
  ui_story_5086_50860601_32_dialog_content = "¡Este acuario realmente hace honor a su reputación!",
  ui_story_5086_50860601_33_dialog_content = "Todos los peces están tan vivos aquí. Es como si los hubieran sacado del mar hoy mismo.",
  ui_story_5086_50860601_34_dialog_content = "Jaja... Ja...",
  ui_story_5086_50860601_35_dialog_content = "¡Hola... ¿Dónde está todos?",
  ui_story_5086_50860601_36_dialog_content = "¿Hola? ¿Hay alguien ahí? ¡Podría usar algo de ayuda aquí!",
  ui_story_5086_50860601_37_dialog_content = "Está un poco demasiado oscuro aquí. ¿No se supone que deben tener un letrero de salida iluminado para que la gente lo vea?",
  ui_story_5086_50860601_38_dialog_content = "¡Oh, veo luz allí! Estoy bastante seguro de que conduce al vestíbulo, así que simplemente—",
  ui_story_5086_50860601_39_dialog_content = "... ¿Qué es ese olor?",
  ui_story_5086_50860601_40_dialog_content = "¿Está... alguien ahí?",
  ui_story_5086_50860601_41_dialog_content = "¿Eh? ¿Q-Qué eres tú...",
  ui_story_5086_50860601_42_dialog_content = "¡Ahhhhhhh!",
  ui_story_5086_50860602_1_dialog_content = "¡Gah!",
  ui_story_5086_50860602_2_dialog_content = "¡D-No me asustes así, Minos!",
  ui_story_5086_50860602_3_dialog_content = "Mis disculpas. Solo pretendía compartir la información que había adquirido contigo.",
  ui_story_5086_50860602_4_dialog_content = "La verdad sin adulterar es a menudo la más aterradora. ¿Has escuchado este dicho antes?",
  ui_story_5086_50860602_5_dialog_content = "En comparación con una paz mental superficial, me siento mucho más consolado cuando conozco toda la verdad detrás de cada detalle.",
  ui_story_5086_50860602_6_dialog_content = "Debes tener nervios de acero, Minos.",
  ui_story_5086_50860602_7_dialog_content = "Mientras mi señora lo requiera, se puede construir una ciudad entera sobre mis nervios inamovibles.",
  ui_story_5086_50860602_8_dialog_content = "... Ya no puedo decir si estás bromeando o no.",
  ui_story_5086_50860602_9_dialog_content = "Eso apenas importa ahora.",
  ui_story_5086_50860602_10_dialog_content = "Lo que realmente importa es, ¿has descansado durante este breve respiro?",
  ui_story_5086_50860602_11_dialog_content = "... Yo tengo.",
  ui_story_5086_50860602_12_dialog_content = "Maravilloso. Sería imperdonable de mi parte molestar a un querido amigo de la señorita Nina con mis palabras.",
  ui_story_5086_50860602_13_dialog_content = "Si me disculpas, ahora debo atender a la joven Sanae.",
  ui_story_5086_50860602_14_dialog_content = "¿Ah?",
  ui_story_5086_50860602_15_dialog_content = "Me pregunto por qué Minos sintió la necesidad de compartir todo esto conmigo...",
  ui_story_5086_50860602_16_dialog_content = "No sentí que estuviera tratando de asustarme o algo así.",
  ui_story_5086_50860602_17_dialog_content = "Aun así, es posible que todas las desapariciones estén de alguna manera conectadas con el acuario...",
  ui_story_5086_50860602_18_dialog_content = "Basándome en mis experiencias, siempre que sucede algo extraño como esto, el primer culpable que tengo que sospechar es—",
  ui_story_5086_50860602_19_option_content = "¡Escaneo psíquico!",
  ui_story_5086_50860602_20_dialog_content = "!",
  ui_story_5086_50860602_21_dialog_content = "De ninguna manera... No lo esperaba, pero sentí la presencia de un Eclipsite en el acuario!",
  ui_story_5086_50860602_22_dialog_content = "Es demasiado tenue para precisar su ubicación exacta... ¿Dónde podría estar?",
  ui_story_5086_50860602_23_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860602_24_dialog_content = "¿Desapareció? Espera... He escuchado esta canción antes...",
  ui_story_5086_50860602_25_dialog_content = "...",
  ui_story_5086_50860602_26_dialog_content = "¿Maya?",
  ui_story_5086_50860602_27_dialog_content = "Shhh.",
  ui_story_5086_50860602_28_dialog_content = "Está durmiendo.",
  ui_story_5086_50860602_29_dialog_content = "<color=#e8d9bb>Maya se aleja para revelar a un niñito durmiendo en el banco.</color>",
  ui_story_5086_50860602_30_dialog_content = "Es ese niño de antes... ¿Froude, verdad? ¿Por qué aún no se ha ido a casa?",
  ui_story_5086_50860602_31_dialog_content = "Las ballenas aquí son sus animales favoritos, por lo que le gusta escabullirse después de ir a casa para venir a visitarlas.",
  ui_story_5086_50860602_32_dialog_content = "Normalmente lo encuentro pasando el rato en la exhibición de ballenas alrededor de esta hora. Cuando lo hago, simplemente le cuento otro cuento de hadas, y él vuelve directamente a casa.",
  ui_story_5086_50860602_33_dialog_content = "Jejeje, sé todo esto porque lo escribí en mis notas.",
  ui_story_5086_50860602_34_dialog_content = "Entonces, ¿qué historia le contaste, Maya?",
  ui_story_5086_50860602_35_dialog_content = "Bueno, como solo podía recordar la mitad, tuve que completar el resto tocando mi concha.",
  ui_story_5086_50860602_36_dialog_content = "Ahora que estás aquí, PlayerName... ¡Puedes contarnos una historia!",
  ui_story_5086_50860602_37_dialog_content = "Pero Froude ya está dormido.",
  ui_story_5086_50860602_38_dialog_content = "¿No lo sabías, PlayerName? Dicen que aún puedes recordar cosas incluso cuando las escuchas mientras duermes.",
  ui_story_5086_50860602_39_dialog_content = "Solo quieres escuchar otra historia, ¿no?",
  ui_story_5086_50860602_40_dialog_content = "¡Jaja, culpable de los cargos!",
  ui_story_5086_50860602_41_dialog_content = "... Creo que estoy empezando a entender cómo se siente la señorita Stellandine.",
  ui_story_5086_50860602_42_dialog_content = "(Es casi imposible decir que no a Maya.)",
  ui_story_5086_50860602_43_dialog_content = "¿Aún recuerdas la historia que la señorita Stellandine nos contó antes?",
  ui_story_5086_50860602_44_dialog_content = "¿Qué? ¿La señorita Stellandine nos contó una historia?",
  ui_story_5086_50860602_45_dialog_content = "Debí saberlo... Está bien, solo te lo diré de nuevo.",
  ui_story_5086_50860602_46_dialog_content = "Érase una vez, había una niña que vivía en el mar. Ella rescató a un joven príncipe cuando cayó de su barco...",
  ui_story_5086_50860602_47_dialog_content = "¡Sí!",
  ui_story_5086_50860602_48_dialog_content = "... Y así la chica hizo un trato con una bruja del mar, quien le dio la habilidad de caminar en tierra.",
  ui_story_5086_50860602_49_dialog_content = "Pero cuando la chica llegó a la orilla, se dio cuenta de que el precio que pagó por sus nuevas piernas eran sus recuerdos del príncipe que tanto amaba.",
  ui_story_5086_50860602_50_dialog_content = "¿Cómo puede ser esto? Sin sus recuerdos, ¿no se sentirá sola?",
  ui_story_5086_50860602_51_dialog_content = "...",
  ui_story_5086_50860602_52_dialog_content = "¡No te preocupes! ¡La historia aún no ha terminado!",
  ui_story_5086_50860602_53_dialog_content = "¿Ahora cómo fue el resto de nuevo?",
  ui_story_5086_50860602_54_dialog_content = "¡Oh, cierto! Incluso después de que el príncipe regresó a su reino, no podía dejar de pensar en la hermosa mujer que había salvado su vida.",
  ui_story_5086_50860602_55_dialog_content = "Así que volvió al mar donde los dos se encontraron por primera vez, pero la chica no estaba por ninguna parte.",
  ui_story_5086_50860602_56_dialog_content = "Aun así, el príncipe se negó a rendirse. Llamó a las criaturas del mar y preguntó a cada una de ellas si sabían a dónde había ido.",
  ui_story_5086_50860602_57_dialog_content = "Primero, él preguntó a una ballena...",
  ui_story_5086_50860602_58_dialog_content = "<color=#e8d9bb>Chapoteo.</color>",
  ui_story_5086_50860602_59_dialog_content = "<color=#e8d9bb>La caracola de Maya comienza a hacer sonidos de nuevo.</color>",
  ui_story_5086_50860602_60_dialog_content = "<color=#e8d9bb>Como si estuviera atraída, una ballena aparece al otro lado del cristal y nada con gracia de un lado a otro.</color>",
  ui_story_5086_50860602_61_dialog_content = "Entonces, él preguntó a un lenguado...",
  ui_story_5086_50860602_62_dialog_content = "<color=#e8d9bb>En otro tanque, un banco de lenguados pasa rápidamente junto a ellos.</color>",
  ui_story_5086_50860602_63_dialog_content = "Después de eso, le preguntó a un cangrejo...",
  ui_story_5086_50860602_64_dialog_content = "<color=#e8d9bb>Desde una exhibición de playa cercana, varios cangrejos asoman sus cabezas fuera de la arena.</color>",
  ui_story_5086_50860602_65_dialog_content = "<color=#e8d9bb>Innumerables espíritus del agua se reúnen silenciosamente alrededor de Maya y bailan al ritmo de su concha.</color>",
  ui_story_5086_50860602_66_dialog_content = "Con su ayuda, el príncipe viaja al borde más lejano del mar.",
  ui_story_5086_50860602_67_dialog_content = "Y allí, en la playa, finalmente se reencuentra con la mujer que lo salvó.",
  ui_story_5086_50860602_68_dialog_content = "¿Quién eres tú? ella pregunta con una mirada de desconcierto.",
  ui_story_5086_50860602_69_dialog_content = "Finalmente soy tuyo, responde. \"Te amo\".",
  ui_story_5086_50860602_70_dialog_content = "Y los dos vivieron felices para siempre.",
  ui_story_5086_50860602_71_dialog_content = "En el momento en que sus manos se tocaron, los recuerdos de la chica volvieron a inundar su corazón.",
  ui_story_5086_50860602_72_dialog_content = "Cuando se trata de cuentos de hadas, el amor siempre es más fuerte que incluso la magia más poderosa. ¡Es la respuesta a cada problema!",
  ui_story_5086_50860701_1_dialog_content = "¡Qué gran historia! ¿Podrías contarme otra? ¿¡Por favor!?",
  ui_story_5086_50860701_2_dialog_content = "Bien, veamos...",
  ui_story_5086_50860701_3_dialog_content = "Atención, visitantes y personal. Debido a una emergencia imprevista, el acuario cerrará a una hora más temprana hoy.",
  ui_story_5086_50860701_4_dialog_content = "Por favor, siga a nuestros miembros del personal al vestíbulo lo antes posible.",
  ui_story_5086_50860701_5_dialog_content = "Esa era la voz de la señorita Stellandine. Me pregunto qué habrá pasado...",
  ui_story_5086_50860701_6_dialog_content = "Un visitante ha informado de la desaparición de un amigo. El acuario está cooperando con la guardia de la ciudad para investigar el asunto.",
  ui_story_5086_50860701_7_dialog_content = "Vamos a echar un vistazo.",
  ui_story_5086_50860701_8_dialog_content = "Espera—",
  ui_story_5086_50860701_9_dialog_content = "¡Esos Eclipsites mejor que se cuiden! ¡No toleraré ninguna traición en mi guardia!",
  ui_story_5086_50860701_10_dialog_content = "Sadie, ¡relájate! Pueden haberse separado simplemente; aún no sabemos nada con certeza.",
  ui_story_5086_50860701_11_dialog_content = "Si Super Swashbuckler Sadie no puede mantener la calma en esta situación, las personas normales entrarán en pánico aún más.",
  ui_story_5086_50860701_12_dialog_content = "¡Señorita Stellandine! ¿Están todos bien?!",
  ui_story_5086_50860701_13_dialog_content = "Huff... Aunque solo es un niño pequeño, llevarlo todo el camino hasta aquí fue una tortura para mis brazos y piernas...",
  ui_story_5086_50860701_14_dialog_content = "Bueno, Maya y PlayerName también están aquí... ¿Hmm? ¿De dónde vino este niño?",
  ui_story_5086_50860701_15_dialog_content = "Maya dice que se coló para ver las ballenas.",
  ui_story_5086_50860701_16_dialog_content = "Solo ponlo en esa silla por ahora.",
  ui_story_5086_50860701_17_dialog_content = "Creo que todos en el acuario están presentes y contabilizados ahora.",
  ui_story_5086_50860701_18_dialog_content = "¿Puede confirmar eso, señorita Stellandine?",
  ui_story_5086_50860701_19_dialog_content = "Recuerdo las caras de cada visitante. Pero si aún tienes dudas...",
  ui_story_5086_50860701_20_dialog_content = "¿Alguien más está buscando a un amigo o compañero desaparecido?",
  ui_story_5086_50860701_21_dialog_content = "<color=#e8d9bb>Todos los presentes miraron a su alrededor, negando con la cabeza.</color>",
  ui_story_5086_50860701_22_dialog_content = "Nadie...",
  ui_story_5086_50860701_23_dialog_content = "(Minos debe saber algo. Debería ir a preguntarle.)",
  ui_story_5086_50860701_24_dialog_content = "¡Hola, Minos... Eh? ¿Dónde se ha ido? Acaba de estar aquí hace un segundo.",
  ui_story_5086_50860701_25_dialog_content = "Lo vi escoltando a alguien por ese pasillo.",
  ui_story_5086_50860701_26_dialog_content = "Gracias, Goldie.",
  ui_story_5086_50860701_27_dialog_content = "Jeje, puedes dejarme este lugar, ¡ahora ve a hacer lo tuyo!",
  ui_story_5086_50860701_28_dialog_content = "¡De ninguna manera me habría dejado atrás sin decir nada!",
  ui_story_5086_50860701_29_dialog_content = "El acuario no es tan grande. ¡Un adulto no podría haberse perdido aquí durante tanto tiempo!",
  ui_story_5086_50860701_30_dialog_content = "¡No... Algo debe haberle pasado!",
  ui_story_5086_50860701_31_dialog_content = "*sollozos* Todo es mi culpa... Nunca debería haber insistido en venir aquí!",
  ui_story_5086_50860701_32_dialog_content = "Por favor, mantén la calma. Aún no sabemos nada con certeza.",
  ui_story_5086_50860701_33_dialog_content = "Deberíamos centrarnos en buscar pistas y encontrar a tu amigo.",
  ui_story_5086_50860701_34_dialog_content = "Afortunadamente, un Caelestite muy útil acaba de aparecer ante nosotros.",
  ui_story_5086_50860701_35_dialog_content = "¿Lo siento?",
  ui_story_5086_50860701_36_dialog_content = "<color=#e8d9bb>Minos pide al visitante angustiado que regrese al grupo y me hace señas para que me una a él más adelante en el pasillo.</color>",
  ui_story_5086_50860701_37_dialog_content = "Está tan oscuro aquí.",
  ui_story_5086_50860701_38_dialog_content = "Según la señorita Stellandine, el sistema de iluminación ha estado fallando últimamente.",
  ui_story_5086_50860701_39_dialog_content = "Afirma haber cerrado el acuario para mantenimiento en el pasado, por lo que los problemas eléctricos de hoy fueron completamente inesperados.",
  ui_story_5086_50860701_40_dialog_content = "Afortunadamente, solo las principales luminarias de este pasillo han perdido energía.",
  ui_story_5086_50860701_41_dialog_content = "Las luces ambientales son tenues, pero deberían ser suficientes para navegar por el pasillo.",
  ui_story_5086_50860701_42_dialog_content = "De todos modos, creo que la última ubicación conocida del visitante desaparecido estaba en este mismo lugar.",
  ui_story_5086_50860701_43_dialog_content = "¿Qué te hace decir eso?",
  ui_story_5086_50860701_44_dialog_content = "Por favor, echa un vistazo a este pilar.",
  ui_story_5086_50860701_45_dialog_content = "¿Qué es eso? Hay algo manchado en ello... Espera, ¿es esto sangre?!",
  ui_story_5086_50860701_46_dialog_content = "¿Hay más en la zona?",
  ui_story_5086_50860701_47_dialog_content = "<color=#e8d9bb>Chapoteo.</color>",
  ui_story_5086_50860701_48_dialog_content = "Vaya, eso estuvo cerca... Casi resbalo en este charco. Cuidado con tu paso, Minos.",
  ui_story_5086_50860701_49_dialog_content = "Podría decirte exactamente lo mismo, PlayerName. Hasta que se resuelva este incidente, por favor, ten la máxima precaución en la escena-",
  ui_story_5086_50860701_50_dialog_content = "Debemos evitar dañar cualquier pista o evidencia.",
  ui_story_5086_50860701_51_dialog_content = "Si hubieras dado un paso más, habrías arruinado esa huella en el piso.",
  ui_story_5086_50860701_52_dialog_content = "¡Oh, ahora me lo dices tú!",
  ui_story_5086_50860701_53_dialog_content = "Espera, hay más de una huella aquí... Me alegra que hayas podido verlas incluso con esta iluminación.",
  ui_story_5086_50860701_54_dialog_content = "Pero están todos mezclados...",
  ui_story_5086_50860701_55_dialog_content = "Basándome en la altura proporcionada por el amigo de la persona desaparecida, puedo estimar su talla de zapato aproximada.",
  ui_story_5086_50860701_56_dialog_content = "Y juzgando por la forma en que se superponen entre sí, también puedo discernir aproximadamente el orden en que se hicieron.",
  ui_story_5086_50860701_57_dialog_content = "Por último, dado el modo en que las huellas pasan junto a este pilar manchado de sangre, es muy posible que pertenezcan a nuestra persona desaparecida.",
  ui_story_5086_50860701_58_dialog_content = "¡Eso fue rápido!",
  ui_story_5086_50860701_59_dialog_content = "Aun así, hay algo raro en estas huellas.",
  ui_story_5086_50860701_60_dialog_content = "Parecen totalmente normales en su camino hacia el medio del pasillo, pero luego retroceden y se convierten en un completo desastre.",
  ui_story_5086_50860701_61_dialog_content = "Casi como si... la persona que los dejó se encontrara con algo aterrador.",
  ui_story_5086_50860701_62_dialog_content = "Creo que tienes las cualidades de un detective hábil, mi amigo.",
  ui_story_5086_50860701_63_dialog_content = "Yo también hice una observación similar.",
  ui_story_5086_50860701_64_dialog_content = "Una persona normal naturalmente gritaría pidiendo ayuda cuando se enfrenta a algo aterrador.",
  ui_story_5086_50860701_65_dialog_content = "Por el aspecto de estas huellas, asumiría que tuvo suficiente tiempo para gritar.",
  ui_story_5086_50860701_66_dialog_content = "Desafortunadamente, mis consultas con el resto de los visitantes del acuario revelaron que ninguno de ellos estuvo siquiera cerca de este pasillo esta tarde.",
  ui_story_5086_50860701_67_dialog_content = "Aquellos que habían pasado por aquí tampoco informaron nada fuera de lo común, lo que significa que no se puede determinar el momento de la desaparición de la persona desaparecida en base a nuestro conocimiento actual.",
  ui_story_5086_50860701_68_dialog_content = "De hecho, Maya y yo estábamos cerca cuando sucedió...",
  ui_story_5086_50860701_69_dialog_content = "Pero Maya estuvo tocando su concha todo el tiempo, lo que May explica por qué no escuchamos nada.",
  ui_story_5086_50860701_70_dialog_content = "Ya veo. Qué desafortunado.",
  ui_story_5086_50860701_71_dialog_content = "Parece que la actual cadena de pistas solo puede llevarnos hasta aquí.",
  ui_story_5086_50860701_72_dialog_content = "Las huellas se detienen justo antes de llegar al final del pasillo... Entonces, ¿a dónde podría haber ido esta persona?",
  ui_story_5086_50860701_73_dialog_content = "... ¡Espera, acabo de recordar algo!",
  ui_story_5086_50860701_74_dialog_content = "¡Después de terminar nuestra conversación anterior, sentí la presencia de un Eclipsite en algún lugar dentro del acuario! Era débil, ¡pero no había duda!",
  ui_story_5086_50860701_75_dialog_content = "¿Es posible que haya habitaciones y pasajes ocultos en este lugar, al igual que la casa embrujada?",
  ui_story_5086_50860701_76_dialog_content = "Para que puedan acechar en la oscuridad y salir cuando se apagan las luces.",
  ui_story_5086_50860701_77_dialog_content = "El visitante desaparecido se encontró con un Eclipsite y fue atacado mientras intentaba escapar...",
  ui_story_5086_50860702_1_dialog_content = "Hasta que buscamos cada rincón de este acuario, no pude negar la posibilidad de que existan habitaciones ocultas dentro de este lugar.",
  ui_story_5086_50860702_2_dialog_content = "Sin embargo, debemos enfrentar otro problema urgente...",
  ui_story_5086_50860702_3_dialog_content = "¿Ya hemos terminado? ¿Cuánto más debemos desperdiciar nuestro tiempo aquí?",
  ui_story_5086_50860702_4_dialog_content = "Simplemente deja que la guardia de la ciudad se ocupe de esto. Manejar casos de personas desaparecidas es su trabajo, ¿no es así?",
  ui_story_5086_50860702_5_dialog_content = "Entiendo sus preocupaciones, todos. La guardia de la ciudad ya ha sido notificada, pero sería mejor si todos permanecen aquí hasta que lleguen.",
  ui_story_5086_50860702_6_dialog_content = "Honestamente, hay algo seriamente malo con este lugar, ¡y no me quedaré para descubrir qué es! ¡Me aseguraré de decirles a mis amigos que eviten este lugar también!",
  ui_story_5086_50860702_7_dialog_content = "¡Por favor no digas eso! Estamos...",
  ui_story_5086_50860702_8_dialog_content = "Dadas las circunstancias actuales, simplemente no tenemos tiempo para realizar una inspección tan minuciosa.",
  ui_story_5086_50860702_9_dialog_content = "Los invitados están empezando a ponerse inquietos...",
  ui_story_5086_50860702_10_dialog_content = "Por favor perdóname.",
  ui_story_5086_50860702_11_dialog_content = "¡¿Qué-¡Oye!",
  ui_story_5086_50860702_12_dialog_content = "¿Qué pasa, Minos? ¿Por qué me empujaste así...",
  ui_story_5086_50860702_13_dialog_content = "Hay algo mal, PlayerName?",
  ui_story_5086_50860702_14_dialog_content = "(¡Oh no, todos están dirigiendo su atención hacia mí porque salté tan de repente!)",
  ui_story_5086_50860702_15_dialog_content = "Jajaja... S-Siento interrumpir...",
  ui_story_5086_50860702_16_dialog_content = "¡Pero creo que conozco una forma de descubrir la verdad!",
  ui_story_5086_50860702_17_dialog_content = "?!",
  ui_story_5086_50860702_18_dialog_content = "(¿E-Esa era mi voz?!)",
  ui_story_5086_50860702_19_dialog_content = "Eso es increíble, PlayerName!",
  ui_story_5086_50860702_20_dialog_content = "Mientras todos los demás estaban entrando en pánico, tú ya estabas trabajando duro tratando de resolver el misterio, ¿eh?",
  ui_story_5086_50860702_21_dialog_content = "¡Tu habilidad para tomar control de la situación es tan impresionante!",
  ui_story_5086_50860702_22_dialog_content = "¡Vaya, PlayerName! No tenía idea de que querías ser un detective en lugar de un espadachín como yo!",
  ui_story_5086_50860702_23_dialog_content = "¡N-Ahora espera un minuto! Eso no fui yo—",
  ui_story_5086_50860702_24_dialog_content = "¡Ese no era yo solo hablando sin sentido!",
  ui_story_5086_50860702_25_dialog_content = "¡Ey! No me interrumpas—",
  ui_story_5086_50860702_26_dialog_content = "¡Porque estoy a punto de señalar al verdadero culpable!",
  ui_story_5086_50860702_27_dialog_content = "... ¡¿Qué?!?",
  ui_story_5086_50860702_28_dialog_content = "¿Eh? ¿Estás realmente tan sorprendido por este otro lado de ti, PlayerName?",
  ui_story_5086_50860702_29_dialog_content = "¿Quién te crees que eres, fingiendo ser un detective ahora mismo? ¡Lee la sala, punk!",
  ui_story_5086_50860702_30_dialog_content = "Ah, déjalo en paz. Solo es un niño.",
  ui_story_5086_50860702_31_dialog_content = "(¡Todos piensan que estoy loco ahora!)",
  ui_story_5086_50860702_32_dialog_content = "Pero realmente—",
  ui_story_5086_50860702_33_dialog_content = "Ejem.",
  ui_story_5086_50860702_34_dialog_content = "(¿Minos?!)",
  ui_story_5086_50860702_35_option_content = "¡Escaneo psíquico!",
  ui_story_5086_50860702_36_dialog_content = "(¿Qué está pasando aquí, Minos?)",
  ui_story_5086_50860702_37_dialog_content = "(Me disculparé adecuadamente contigo en un momento posterior, mi amigo. Pero como mayordomo, no estoy bien adaptado para estar en el centro de atención.)",
  ui_story_5086_50860702_38_dialog_content = "(Por esta razón, debo pedirte que cooperes conmigo, de la misma manera que Manae lo hace con Sanae.)",
  ui_story_5086_50860702_39_dialog_content = "(¿Entonces necesitas que actúe como tu marioneta?)",
  ui_story_5086_50860702_40_dialog_content = "(Si lo desea, sí.)",
  ui_story_5086_50860702_41_dialog_content = "¡Por favor escuchen, todos! Descubrí algunas cosas en ese pasillo de allí...",
  ui_story_5086_50860702_42_dialog_content = "... Entonces, cuando juntas todo, especialmente las manchas de sangre en la columna, es probable que la persona desaparecida haya sido atacada.",
  ui_story_5086_50860702_43_dialog_content = "A partir de esta tarde, nadie ha dejado el acuario todavía. Eso también significa—",
  ui_story_5086_50860702_44_dialog_content = "Que el culpable no se ha ido. En otras palabras... El asesino está en algún lugar entre nosotros.",
  ui_story_5086_50860702_45_dialog_content = "¡Despierta, niño! ¡¿Nos estás acusando seriamente de algo?!",
  ui_story_5086_50860702_46_dialog_content = "¡Tu búsqueda de atención se ha salido de control! Además, ¿honestamente crees que puedes construir un caso con pruebas tan endebles?!",
  ui_story_5086_50860702_47_dialog_content = "¡Lo sabía! Sabía que algo iba mal con este acuario!",
  ui_story_5086_50860702_48_dialog_content = "¡Cuando los Eclipsites atacaron Harbor City, deben haber convertido a algunos de los empleados aquí en su propia especie!",
  ui_story_5086_50860702_49_dialog_content = "¡¿Qué?! ¡No soy un Eclipsite en absoluto! ¡Y no te atrevas a señalar a la señorita Stellandine o al resto de nuestro personal!",
  ui_story_5086_50860702_50_dialog_content = "¡Así es! No puedes simplemente acusar a Maya o Stellandine así, especialmente cuando no sabes nada sobre ellas!",
  ui_story_5086_50860702_51_dialog_content = "PlayerName, aunque estoy agradecido por tu ayuda en esta investigación, debo pedirte que te abstengas de acusar sin fundamento a nuestros invitados de actos indebidos...",
  ui_story_5086_50860702_52_dialog_content = "(Ella tiene razón, Minos! Te dije que sentí a un Eclipsite antes, ¿eso no significa que el culpable no es uno de ellos?)",
  ui_story_5086_50860702_53_dialog_content = "(¡Todos están empezando a sospechar unos de otros por lo que dijiste!)",
  ui_story_5086_50860702_54_dialog_content = "(Esto también es parte de la razón por la que pedí tu cooperación.)",
  ui_story_5086_50860702_55_dialog_content = "(Eres un hombre joven inteligente, pero tu falta de escepticismo puede ser preocupante a veces.)",
  ui_story_5086_50860702_56_dialog_content = "(¿Eh?)",
  ui_story_5086_50860702_57_dialog_content = "¡Por supuesto que puedo hacer estas acusaciones! ¡Después de todo, soy un Caelestite!",
  ui_story_5086_50860702_58_dialog_content = "También soy un amigo cercano de Lady Carleen. Los caballeros de Lumopolis estarán más que felices de verificar todo esto cuando lleguen aquí.",
  ui_story_5086_50860702_59_dialog_content = "Como Celestita y aliado de confianza de Lady Carleen, es natural que quiera detener a este delincuente, ¿no crees?",
  ui_story_5086_50860702_60_dialog_content = "Todo lo que necesito hacer es tomar de la mano a todos los presentes, y mis habilidades psíquicas me permitirán encontrar al verdadero culpable.",
  ui_story_5086_50860702_61_dialog_content = "¿Y qué pasa si no encuentras al culpable entre nosotros?",
  ui_story_5086_50860702_62_dialog_content = "Entonces, ese sería el mejor resultado posible, ¿no estás de acuerdo?",
  ui_story_5086_50860702_63_dialog_content = "¿Eh...?",
  ui_story_5086_50860702_64_dialog_content = "Por supuesto, sería genial si pudiéramos descubrir al culpable aquí y ahora.",
  ui_story_5086_50860702_65_dialog_content = "Pero si no lo encuentro entre ustedes, eso simplemente significa que ninguno de ustedes es un asesino, ¿verdad?",
  ui_story_5086_50860702_66_dialog_content = "Entonces, o encontraré al delincuente o probaré la inocencia de todos. Es una situación en la que todos ganan, ¿no crees?",
  ui_story_5086_50860702_67_dialog_content = "¡Eso realmente tiene mucho sentido! Aquí, déjame ir primero!",
  ui_story_5086_50860702_68_dialog_content = "Supongo que tienes razón... Está bien, cooperaré.",
  ui_story_5086_50860702_69_dialog_content = "(Wow... Todos estos personas no cooperativas de repente están haciendo fila para ayudar.)",
  ui_story_5086_50860702_70_dialog_content = "(Sé que se supone que debo ser el títere aquí, pero Minos está guiando a toda la sala por sus narices.)",
  ui_story_5086_50860702_71_dialog_content = "(También, parece que ninguno de ellos ha considerado la posibilidad de que en realidad no sé nada, o que no tengo forma de probar la inocencia de nadie...)",
  ui_story_5086_50860702_72_dialog_content = "(Una respuesta natural. Después de todo, las personas se vuelven miopes con bastante facilidad durante situaciones estresantes como esta. Cuando eso sucede, solo ven las cosas en blanco y negro.)",
  ui_story_5086_50860702_73_dialog_content = "(Pero por el momento, por favor no les alertes sobre esa posibilidad.)",
  ui_story_5086_50860702_74_dialog_content = "(Dadas nuestras circunstancias actuales, creo que unir a todos bajo un objetivo común es de vital importancia.)",
  ui_story_5086_50860702_75_dialog_content = "(Yo sé... Pero...)",
  ui_story_5086_50860702_76_dialog_content = "(¡Todos quieren que les estreche la mano ahora! ¿Realmente tengo que usar mis poderes en cada uno de ellos?)",
  ui_story_5086_50860702_77_dialog_content = "(De nada, mi amigo.)",
  ui_story_5086_50860702_78_dialog_content = "(Después de todo, simplemente deseo observar...)",
  ui_story_5086_50860702_79_dialog_content = "(¿Cuál de estas personas se comportará de manera anormal en un momento tan crítico.)",
  ui_story_5086_50860702_80_dialog_content = "<color=#e8d9bb>De repente, la fila de personas esperando para estrechar la mano se detiene abruptamente.</color>",
  ui_story_5086_50860702_81_dialog_content = "¿Qué te pasa, Maya? Es tu turno, ya sabes.",
  ui_story_5086_50860702_82_dialog_content = "(Yo...)",
  ui_story_5086_50860702_83_dialog_content = "(Eso es correcto; Maya piensa que mis poderes de alguna manera perturbarán al Ancestro.)",
  ui_story_5086_50860702_84_dialog_content = "No te preocupes, Maya, yo...",
  ui_story_5086_50860702_85_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5086_50860702_86_dialog_content = "¿¡Qué está pasando?! ¿¡Quién apagó las luces?!",
  ui_story_5086_50860702_87_dialog_content = "Permanece en fila y mantén la calma, todos-",
  ui_story_5086_50860702_88_dialog_content = "¡Alguien cerró la entrada! ¡Ahora todos estamos atrapados aquí!",
  ui_story_5086_50860702_89_dialog_content = "¡Fuera de mi camino! Ninguna puerta puede resistir—",
  ui_story_5086_50860702_90_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5086_50860702_91_dialog_content = "<color=#e8d9bb>En medio de la confusión, el sonido del vidrio rompiéndose atraviesa el aire.</color>",
  ui_story_5086_50860702_92_dialog_content = "<color=#e8d9bb>Antes de que alguien pueda reaccionar, el tanque que rodea el vestíbulo del acuario explota.</color>",
  ui_story_5086_50860702_93_dialog_content = "<color=#e8d9bb>El vestíbulo se inunda rápidamente con agua fría e innumerables peces.</color>",
  ui_story_5086_50860801_1_dialog_content = "¡PlayerName—!",
  ui_story_5086_50860801_2_dialog_content = "Urgh... Tos, tos, tos—",
  ui_story_5086_50860801_3_dialog_content = "¿Estás bien?",
  ui_story_5086_50860801_4_dialog_content = "Sí, solo tragué un poco de agua, eso es todo... Gracias por el rescate.",
  ui_story_5086_50860801_5_dialog_content = "No me agradezcas, agradece a Goldie.",
  ui_story_5086_50860801_6_dialog_content = "Todos fueron arrastrados cuando los tanques estallaron, pero ella logró sacarnos a los dos del agua.",
  ui_story_5086_50860801_7_dialog_content = "Fue pura suerte, eso es todo.",
  ui_story_5086_50860801_8_dialog_content = "Yo estaba más lejos de los tanques cuando explotaron, así que tuve un poco más de tiempo para reaccionar.",
  ui_story_5086_50860801_9_dialog_content = "Pero no podía ver nada en la oscuridad justo ahora, así que me aferré a las dos personas más cercanas a mí.",
  ui_story_5086_50860801_10_dialog_content = "Afortunadamente, mientras la corriente nos arrastraba, también logré abrir la puerta de esta área de descanso y sacarnos del agua.",
  ui_story_5086_50860801_11_dialog_content = "(Eso no suena para nada como pura suerte, Goldie...)",
  ui_story_5086_50860801_12_dialog_content = "De todos modos... ¿Cómo sucedió todo esto...?",
  ui_story_5086_50860801_13_dialog_content = "<color=#e8d9bb>El agua sigue fluyendo a través de las grietas en la puerta, elevando gradualmente el nivel de agua en la habitación.</color>",
  ui_story_5086_50860801_14_dialog_content = "Sé que es un acuario, pero ¿por qué siento que hay una cantidad infinita de agua aquí?",
  ui_story_5086_50860801_15_dialog_content = "Parece que esta habitación tampoco durará mucho más tiempo.",
  ui_story_5086_50860801_16_dialog_content = "¿Entonces que debemos hacer ahora?",
  ui_story_5086_50860801_17_dialog_content = "Creo que necesitamos encontrar una forma de reunirnos con todos primero.",
  ui_story_5086_50860801_18_dialog_content = "¡Ayuda—!",
  ui_story_5086_50860801_19_dialog_content = "¡Alguien está en problemas!",
  ui_story_5086_50860801_20_dialog_content = "¡No te preocupes, Super Sadie Swashbuckler 666 está en camino!",
  ui_story_5086_50860801_21_dialog_content = "Espera—",
  ui_story_5086_50860801_22_dialog_content = "Iremos contigo.",
  ui_story_5086_50860801_23_dialog_content = "¡Allá! ¡Mira!",
  ui_story_5086_50860801_24_dialog_content = "<color=#e8d9bb>El agua en el pasillo ya está a la altura de la cintura. Un grupo de visitantes pide ayuda desde lo alto de un trozo de madera flotante.</color>",
  ui_story_5086_50860801_25_dialog_content = "<color=#e8d9bb>Nadando hacia ellos está un tiburón masivo—</color>",
  ui_story_5086_50860801_26_dialog_content = "¡Piérdete, gran fanfarrón!",
  ui_story_5086_50860801_27_dialog_content = "<color=#e8d9bb>Sorprendentemente, el ataque de Sadie obliga al tiburón a retroceder unos pocos pies.</color>",
  ui_story_5086_50860801_28_dialog_content = "¡No te preocupes, un espadachín siempre protege a quien lo necesita!",
  ui_story_5086_50860801_29_dialog_content = "¡Aquí, PlayerName! ¡Agárrate a esto!",
  ui_story_5086_50860801_30_dialog_content = "¿Una red de pesca? ¿Dónde conseguiste esto?",
  ui_story_5086_50860801_31_dialog_content = "Casi me enredo con ello en el camino aquí. Pensé que podría ser útil más tarde, así que lo traje conmigo.",
  ui_story_5086_50860801_32_dialog_content = "¡Usemoslo!",
  ui_story_5086_50860801_33_dialog_content = "¿Crees que podemos lograr esto juntos, Sadie?",
  ui_story_5086_50860801_34_dialog_content = "¡Por supuesto! ¡Un espadachín nunca se rinde!",
  ui_story_5086_50860801_35_dialog_content = "Entonces a mi cuenta—",
  ui_story_5086_50860801_36_dialog_content = "Tres.",
  ui_story_5086_50860801_37_dialog_content = "<color=#e8d9bb>Sadie levanta su bate de béisbol.</color>",
  ui_story_5086_50860801_38_dialog_content = "Dos.",
  ui_story_5086_50860801_39_dialog_content = "<color=#e8d9bb>Goldie y yo avanzamos silenciosamente.</color>",
  ui_story_5086_50860801_40_dialog_content = "¡Uno!",
  ui_story_5086_50860801_41_dialog_content = "<size=50>¡Tú estás fuera de aquí—!</size>",
  ui_story_5086_50860801_42_dialog_content = "<color=#e8d9bb>El tiburón aterriza perfectamente dentro de la red en espera.</color>",
  ui_story_5086_50860801_43_dialog_content = "Bien hecho, todos.",
  ui_story_5086_50860801_44_dialog_content = "Apenas sudaste ahora, Goldie... ¿Estoy realmente tan fuera de forma?",
  ui_story_5086_50860801_45_dialog_content = "¡Jejeje!",
  ui_story_5086_50860801_46_dialog_content = "¡Vamos Sadie, vamos—!",
  ui_story_5086_50860801_47_dialog_content = "<color=#e8d9bb>De repente, una enorme sombra aparece en el agua detrás de Sadie.</color>",
  ui_story_5086_50860801_48_dialog_content = "¡Sal de ahí, Sadie!",
  ui_story_5086_50860801_49_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5086_50860801_50_dialog_content = "!",
  ui_story_5086_50860801_51_dialog_content = "(Y-Ya es muy tarde...)",
  ui_story_5086_50860801_52_dialog_content = "<size=50>Veredicto rápido.</size>",
  ui_story_5086_50860801_53_dialog_content = "<size=50>¡Maná incomparable!</size>",
  ui_story_5086_50860801_54_dialog_content = "Nuestras disculpas por tardar tanto, todos.",
  ui_story_5086_50860801_55_dialog_content = "Solo me alejé para buscar Sanae, pero parece que un número de criaturas viles han aparecido en nuestra ausencia.",
  ui_story_5086_50860801_56_dialog_content = "<color=#e8d9bb>Minos se mantiene perfectamente equilibrado en la cima de una cinta en el aire y hace una reverencia cortés.</color>",
  ui_story_5086_50860801_57_dialog_content = "<color=#e8d9bb>Bajo su brazo izquierdo hay un Sanae de aspecto muy angustiado.</color>",
  ui_story_5086_50860801_58_dialog_content = "Um... ¡P-Por favor perdóname! ¡No tenía la intención de dormirme durante todo!",
  ui_story_5086_50860801_59_dialog_content = "B-Pero ahora que estoy aquí, ¡haré todo lo que pueda para arreglar las cosas!",
  ui_story_5086_50860801_60_dialog_content = "Eso es mucho mejor, Sanae. Ahora comienza, si te parece bien.",
  ui_story_5086_50860801_61_dialog_content = "¿Ah?",
  ui_story_5086_50860801_62_dialog_content = "¡Cuidado, todos! ¡Vienen más Eclipsites!",
  ui_story_5086_50860802_1_dialog_content = "Graaah...",
  ui_story_5086_50860802_2_dialog_content = "Finalmente terminó... ¿Cuántos Eclipsites se esconden bajo el agua?",
  ui_story_5086_50860802_3_dialog_content = "Puede que no pruebe tu teoría de las habitaciones ocultas en el acuario, pero esto sigue siendo una pieza de evidencia convincente.",
  ui_story_5086_50860802_4_dialog_content = "¿Realmente es el momento para eso, Minos?",
  ui_story_5086_50860802_5_dialog_content = "Absolutamente. Hasta que la verdad se haga clara, no debemos perder de vista nuestra investigación.",
  ui_story_5086_50860802_6_dialog_content = "¡Oye!",
  ui_story_5086_50860802_7_dialog_content = "No sé de qué están hablando ustedes, ¡pero ese tiburón se dirige directamente hacia nosotros!",
  ui_story_5086_50860802_8_dialog_content = "<color=#e8d9bb>¡El sonido de la red de pesca rompiéndose llena el pasillo mientras el tiburón se libera de sus restricciones!</color>",
  ui_story_5086_50860802_9_dialog_content = "<color=#e8d9bb>Más lejos, aparecen más y más sombras peligrosas bajo la superficie del agua.</color>",
  ui_story_5086_50860802_10_dialog_content = "¡Detrás de nosotros! ¡Y hay muchos más de ellos!",
  ui_story_5086_50860802_11_dialog_content = "¡¡¡Vamos a ser comidos vivos!!!",
  ui_story_5086_50860802_12_dialog_content = "... ¿Todos todavía tienen suficiente fuerza para luchar?",
  ui_story_5086_50860802_13_dialog_content = "Estoy bastante cansado, pero luchar hasta el amargo final es la única forma de salir.",
  ui_story_5086_50860802_14_dialog_content = "¡Mientras haya un solo fan presente, un ídolo nunca puede mostrar ni un atisbo de agotamiento!",
  ui_story_5086_50860802_15_dialog_content = "Las sirvientas y los mayordomos no son diferentes. Sin embargo...",
  ui_story_5086_50860802_16_dialog_content = "<color=#e8d9bb>Resuena el sonido familiar de una concha.</color>",
  ui_story_5086_50860802_17_dialog_content = "<color=#e8d9bb>El tiburón desenfrenado gira abruptamente y nada en la dirección de la música.</color>",
  ui_story_5086_50860802_18_dialog_content = "Parece que podemos bajar nuestras armas ahora.",
  ui_story_5086_50860802_19_dialog_content = "Sigámoslo.",
  ui_story_5086_50860802_20_dialog_content = "<color=#e8d9bb>Reflejada por innumerables pedazos de vidrio roto, una luz brumosa y brillante llena la totalidad del acuario.</color>",
  ui_story_5086_50860802_21_dialog_content = "<color=#e8d9bb>Se puede ver la figura borrosa de Maya de pie al otro extremo del pasillo oscurecido.</color>",
  ui_story_5086_50860802_22_dialog_content = "<color=#e8d9bb>Embelesados por la hermosa melodía de la concha, innumerables criaturas acuáticas de diversas formas y tamaños nadan hacia ella.</color>",
  ui_story_5086_50860802_23_dialog_content = "Maya—",
  ui_story_5086_50860802_24_dialog_content = "¡Quédate donde estás!",
  ui_story_5086_50860802_25_dialog_content = "¿Señorita Stellandine? ¿Y Froude, y el resto de los visitantes...? ¡Gracias a Dios que todos están bien!",
  ui_story_5086_50860802_26_dialog_content = "¿Llamas a esto \"bien\"?! ¿No viste a esa mujer ordenar a todos esos peces que nos atacaran?!",
  ui_story_5086_50860802_27_dialog_content = "¡Seríamos carnada para peces ahora mismo si el dueño del acuario no estuviera aquí para protegernos!",
  ui_story_5086_50860802_28_dialog_content = "¡La persona desaparecida de antes probablemente también fue víctima de esa chica! Si ustedes chicos se creen tan duros, ¡vayan a lidiar con ella ahora mismo!",
  ui_story_5086_50860802_29_dialog_content = "¿Ah?",
  ui_story_5086_50860802_30_dialog_content = "Por supuesto que no...",
  ui_story_5086_50860802_31_dialog_content = "¡Está tratando de escapar!",
  ui_story_5086_50860802_32_dialog_content = "...",
  ui_story_5086_50860802_33_dialog_content = "¡Espera, Maya!",
  ui_story_5086_50860802_34_dialog_content = "¡Argh, no puedo moverme lo suficientemente rápido en el agua! No puedo alcanzar—",
  ui_story_5086_50860802_35_dialog_content = "Déjame esto a mí, Sr. PlayerName. Por favor, vigila a los demás por mi parte.",
  ui_story_5086_50860802_36_dialog_content = "<color=#e8d9bb>Minos salta hábilmente a través de los escombros flotantes y va tras Maya.</color>",
  ui_story_5086_50860802_37_dialog_content = "... No podemos seguir quedándonos aquí. Necesitamos encontrar un lugar seguro para que todos puedan refugiarse.",
  ui_story_5086_50860802_38_dialog_content = "El agua aún no ha llegado al segundo piso. Deberíamos intentar subir allí.",
  ui_story_5086_50860802_39_dialog_content = "¡No voy a ir con ustedes! ¡Tengo que ir a buscar a la señorita Maya!",
  ui_story_5086_50860802_40_dialog_content = "Lo siento, pequeña, pero realmente deberíamos discutir esto una vez que todos estén a salvo.",
  ui_story_5086_50860802_41_dialog_content = "¡De ninguna manera! Eres una mala lady, ¡así que mantén tus manos lejos de mí!",
  ui_story_5086_50860802_42_dialog_content = "Permítame, señorita Stellandine.",
  ui_story_5086_50860802_43_dialog_content = "Sé que estás molesto, pequeño, pero tienes que mantenerte positivo en momentos como este! Si no sonríes cuando las cosas se ponen difíciles, no te mantendrás feliz por mucho tiempo!",
  ui_story_5086_50860802_44_dialog_content = "¡P-Pero dijeron todas esas cosas malas sobre la señorita Maya!",
  ui_story_5086_50860802_45_dialog_content = "Lo sé, y esa no es forma de hablar de nadie. Pero tú no estás de acuerdo con ellos en absoluto, ¿verdad?",
  ui_story_5086_50860802_46_dialog_content = "¿E-Eh? ¿Tú... Me crees?",
  ui_story_5086_50860802_47_dialog_content = "Hmm... No estoy seguro, ya que la conocí por primera vez hoy.",
  ui_story_5086_50860802_48_dialog_content = "Entonces, Froude, por favor dime a mí y a todos los demás por qué Maya nunca haría nada malo.",
  ui_story_5086_50860802_49_dialog_content = "¡Okey! ¡Okey!",
  ui_story_5086_50860802_50_dialog_content = "Parece que todo está bien ahora. Vamos, señorita Stellandine.",
  ui_story_5086_50860802_51_dialog_content = "Intentaré mantener mi distancia.",
  ui_story_5086_50860802_52_dialog_content = "Parece que al niño no le caigo bien.",
  ui_story_5086_50860802_53_dialog_content = "Eh... Tal vez solo esté ansioso porque está cerca de Maya.",
  ui_story_5086_50860802_54_dialog_content = "En realidad, para mí es lo mismo.",
  ui_story_5086_50860802_55_dialog_content = "Realmente no puedo creer que Maya sea una mala persona.",
  ui_story_5086_50860802_56_dialog_content = "Ella es solo... Un poco torpe.",
  ui_story_5086_50860802_57_dialog_content = "Pero ella es una buena niña, sin duda alguna.",
  ui_story_5086_50860802_58_dialog_content = "Debe haber algún malentendido, ¡pero esperemos que Minos pueda aclarar las cosas!",
  ui_story_5086_50860802_59_dialog_content = "Eh... señorita Stellandine...",
  ui_story_5086_50860802_60_dialog_content = "¿Es esta la única manera de llegar al segundo piso?",
  ui_story_5086_50860802_61_dialog_content = "Sí. ¿Por qué preguntas?",
  ui_story_5086_50860802_62_dialog_content = "Pero... Goldie y los demás han desaparecido.",
  ui_story_5086_50860802_63_dialog_content = "Y nuestro entorno... Parece que todo se ha distorsionado de alguna manera.",
  ui_story_5086_50860802_64_dialog_content = "Eso es muy preocupante, sí...",
  ui_story_5086_50860802_65_dialog_content = "¿Estás bien? Te ves muy pálido.",
  ui_story_5086_50860802_66_dialog_content = "Para decir la verdad... No me siento tan bien...",
  ui_story_5086_50860802_67_dialog_content = "Pero estaré bien. Por favor continúa sin mí...",
  ui_story_5086_50860802_68_dialog_content = "¿Cómo podría hacer eso?! ¡Vamos! Puede que no sea el más fuerte, pero definitivamente puedo ayudarte a caminar.",
  ui_story_5086_50860802_69_dialog_content = "!",
  ui_story_5086_50860802_70_dialog_content = "... ¿Qué es?",
  ui_story_5086_50860802_71_dialog_content = "Creo... siento un Eclipsite...",
  ui_story_5086_50860901_1_dialog_content = "¡La-la-la♪",
  ui_story_5086_50860901_2_dialog_content = "Um... ¿Señorita Goldie?",
  ui_story_5086_50860901_3_dialog_content = "¿Has descubierto algo?",
  ui_story_5086_50860901_4_dialog_content = "¡Lo he hecho! El segundo piso no está inundado, y tampoco hay nadie peleando.",
  ui_story_5086_50860901_5_dialog_content = "¡Solo necesitamos localizar la salida para salir de aquí!",
  ui_story_5086_50860901_6_dialog_content = "No, no estoy hablando de eso...",
  ui_story_5086_50860901_7_dialog_content = "Supongo que está tratando de decir que todas las personas que nos seguían han desaparecido.",
  ui_story_5086_50860901_8_dialog_content = "¿Ah?",
  ui_story_5086_50860901_9_dialog_content = "¡Realmente se han ido! ¿Hola? ¿PlayerName? ¿Froude? ¿Señorita Stellandine?!",
  ui_story_5086_50860901_10_dialog_content = "La única respuesta es un eco.",
  ui_story_5086_50860901_11_dialog_content = "Este lugar... Algo sobre él se siente diferente ahora...",
  ui_story_5086_50860901_12_dialog_content = "La atmósfera... Es tan intensa ahora.",
  ui_story_5086_50860901_13_dialog_content = "Lo sé, ¿verdad? Es como el cambio repentino en el estilo de arte.",
  ui_story_5086_50860901_14_dialog_content = "Hay imágenes super espeluznantes en el vidrio, y se siente como si un monstruo pudiera saltar sobre nosotros en cualquier segundo.",
  ui_story_5086_50860901_15_dialog_content = "<size=50>¡Eeeek!</size>",
  ui_story_5086_50860901_16_dialog_content = "¡Dejen de asustarse así! No importa cuán aterrador pueda parecer, sigue siendo solo un acuario.",
  ui_story_5086_50860901_17_dialog_content = "¿No recuerdas lo que dijo la señorita Maya? Aquí es donde experimentamos sueños, y una vez que te das cuenta de eso, no hay nada que temer.",
  ui_story_5086_50860901_18_dialog_content = "Este lugar es más como una pesadilla ahora.",
  ui_story_5086_50860901_19_dialog_content = "Entonces, vamos a cantar.",
  ui_story_5086_50860901_20_dialog_content = "¡Cantar desde el corazón tiene el poder de atravesar la oscuridad y las pesadillas!",
  ui_story_5086_50860901_21_dialog_content = "¡Me llenó de alegría leer eso en los periódicos después del último concierto!",
  ui_story_5086_50860901_22_dialog_content = "De todos modos, comencemos a reunir a nuestros compañeros perdidos.",
  ui_story_5086_50860901_23_dialog_content = "P-Por favor espera...",
  ui_story_5086_50860901_24_dialog_content = "Allá... ¡Eclipsites!",
  ui_story_5086_50860901_25_dialog_content = "¡Solo aguanta un poco más! ¡Ese Eclipsite definitivamente está en algún lugar cercano!",
  ui_story_5086_50860901_26_dialog_content = "Bien... Gracias...",
  ui_story_5086_50860901_27_dialog_content = "Este lugar es diferente al de antes. Ahora se siente como un laberinto... ¡Ah!",
  ui_story_5086_50860901_28_dialog_content = "¡Mira! Es Sanae y los demás!",
  ui_story_5086_50860901_29_dialog_content = "Nosotros...",
  ui_story_5086_50860901_30_dialog_content = "<size=50>¡Maná incomparable!</size>",
  ui_story_5086_50860901_31_dialog_content = "?!",
  ui_story_5086_50860901_32_dialog_content = "Ah—",
  ui_story_5086_50860901_33_dialog_content = "¡Srta. Stellandine!",
  ui_story_5086_50860901_34_dialog_content = "¡Espera, Sanae! ¡Somos nosotros!",
  ui_story_5086_50860901_35_dialog_content = "¿Eh? C-Cómo puede ser esto...",
  ui_story_5086_50860901_36_dialog_content = "Duele...",
  ui_story_5086_50860901_37_dialog_content = "¡¿C-C-Cómo pude atacarte así?! ¡Lo siento mucho! Yo-yo pensé que tú...",
  ui_story_5086_50860901_38_dialog_content = "A-¿Estás bien?",
  ui_story_5086_50860901_39_dialog_content = "... Por favor, no me toques.",
  ui_story_5086_50860901_40_dialog_content = "Boo-hoo... ¡Realmente, realmente lo siento! Te confundí con un Eclipsite justo ahora...",
  ui_story_5086_50860901_41_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_42_dialog_content = "¡Ese es el sonido de la concha de Maya! ¡Está cerca!",
  ui_story_5086_50860901_43_dialog_content = "yo... eh...",
  ui_story_5086_50860901_44_dialog_content = "P-Por favor, quédate quieto por un rato. Yo-Yo...",
  ui_story_5086_50860901_45_dialog_content = "¡AH! Sadie y la señorita Goldie se han ido... Deben haber sido atraídos por el sonido.",
  ui_story_5086_50860901_46_dialog_content = "Me quedaré aquí y protegeré a la señorita Stellandine. Por favor, ve a ayudarles, PlayerName!",
  ui_story_5086_50860901_47_dialog_content = "Nngh... Debes ir tú también, y cuida de Maya.",
  ui_story_5086_50860901_48_dialog_content = "¡Entonces me dirijo allí!",
  ui_story_5086_50860901_49_dialog_content = "(El sonido de la concha se siente completamente diferente.)",
  ui_story_5086_50860901_50_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_51_dialog_content = "(Urgh... Solo escuchar ese sonido hace que mi mente se vuelva borrosa.)",
  ui_story_5086_50860901_52_dialog_content = "(Maya, ¿qué eres tú...)",
  ui_story_5086_50860901_53_dialog_content = "!",
  ui_story_5086_50860901_54_dialog_content = "Realmente no eres diferente a los héroes de los dramas clásicos, mi amigo.",
  ui_story_5086_50860901_55_dialog_content = "Cuando lo pones de esa manera, me hace pensar que realmente necesitas mi ayuda de nuevo.",
  ui_story_5086_50860901_56_dialog_content = "Es como sospechas, sí.",
  ui_story_5086_50860901_57_dialog_content = "Me avergüenza admitirlo, pero apenas podía luchar mientras resistía los efectos de la ilusión de su concha.",
  ui_story_5086_50860901_58_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_59_dialog_content = "¡Maya!",
  ui_story_5086_50860901_60_dialog_content = "...",
  ui_story_5086_50860901_61_dialog_content = "¡No te preocupes, Minos! Protegeré tu mente mientras luchas!",
  ui_story_5086_50860901_62_dialog_content = "Confío en tu habilidad y juicio, así que solo concéntrate en acercarte a Maya!",
  ui_story_5086_50860901_63_option_content = "¡Escaneo psíquico!",
  ui_story_5086_50860901_64_dialog_content = "<color=#e8d9bb>¡Graw!</color>",
  ui_story_5086_50860901_65_dialog_content = "Apenas puedo permitirme decepcionar a mi camarada ahora que ha depositado tanta fe en mí. Perdóname, señorita Maya, pero debo pedir tu cooperación ahora.",
  ui_story_5086_50860901_66_dialog_content = "!",
  ui_story_5086_50860901_67_dialog_content = "¡Quedarse atrás!",
  ui_story_5086_50860901_68_dialog_content = "Por favor, baja la caracola y te aseguro que no te hará daño.",
  ui_story_5086_50860901_69_dialog_content = "Yo... No entiendo lo que está pasando ahora... ¡Pero no puedo!",
  ui_story_5086_50860901_70_dialog_content = "Urgh...",
  ui_story_5086_50860901_71_dialog_content = "Los ataques psíquicos de repente se volvieron más fuertes— ¡Argh, mi cabeza!",
  ui_story_5086_50860901_72_dialog_content = "Parece que debo pelear seriamente ahora.",
  ui_story_5086_50860901_73_dialog_content = "Perdóname, señorita Maya. Te ofreceré una disculpa adecuada una vez que esto termine.",
  ui_story_5086_50860901_74_dialog_content = "<size=50>¡Veredicto rápido!</size>",
  ui_story_5086_50860901_75_dialog_content = "Espera... ¡No!",
  ui_story_5086_50860901_76_dialog_content = "¡No puedo sangrar! ¡No se supone que deba!",
  ui_story_5086_50860901_77_dialog_content = "Por favor, ayúdame—",
  ui_story_5086_50860901_78_dialog_content = "<color=#FFB400>¡Antepasado!</color>",
  ui_story_5086_50860901_79_dialog_content = "<color=#e8d9bb>¡Uf!</color>",
  ui_story_5086_50860901_80_dialog_content = "<color=#e8d9bb>De repente, escuchamos un canto largo y claro.</color>",
  ui_story_5086_50860901_81_dialog_content = "<color=#e8d9bb>Ilimitado y sustancial pero fugaz y etéreo. Todas las contradicciones se validan simultáneamente en este único momento.</color>",
  ui_story_5086_50860901_82_dialog_content = "<color=#e8d9bb>Innumerables colores parpadean y convergen detrás de Maya.</color>",
  ui_story_5086_50860901_83_dialog_content = "Qué magnífico...",
  ui_story_5086_50860901_84_dialog_content = "<color=#e8d9bb>Nunca había puesto los ojos en una criatura tan fantástica, pero tan pronto como lo hice, de alguna manera la entendí.</color>",
  ui_story_5086_50860901_85_dialog_content = "<color=#e8d9bb>Es algo nacido de fantasías, sueños y la proyección infinita de pensamientos...</color>",
  ui_story_5086_50860901_86_dialog_content = "<color=#e8d9bb>Un antiguo fantasma que podría romper la realidad con facilidad.</color>",
  ui_story_5086_50860901_87_dialog_content = "<color=#e8d9bb>Con un solo aliento, este efímero dragón...</color>",
  ui_story_5086_50860901_88_dialog_content = "<color=#e8d9bb>... podría remodelar toda la existencia.</color>",
  ui_story_5086_50860901_89_dialog_content = "¿Es esto una ilusión? ¿O realmente hemos llegado a otro lugar?",
  ui_story_5086_50860901_90_dialog_content = "Este mundo debe ser la creación de la señorita Maya, un lugar donde las <color=#FFB400>ilusiones</color> y la <color=#FFB400>realidad</color> son una y la misma.",
  ui_story_5086_50860901_91_dialog_content = "Por favor, ten cuidado.",
  ui_story_5086_50860901_92_dialog_content = "Dudo que ella haya creado este espacio simplemente para que disfrutemos de las vistas.",
  ui_story_5086_50860901_93_dialog_content = "Dudo que ella haya creado este espacio para que nosotros disfrutemos de las vistas.",
  ui_story_5086_50860902_1_dialog_content = "Buen trabajo, Minos.",
  ui_story_5086_50860902_2_dialog_content = "... ¿Minos?",
  ui_story_5086_50860902_3_dialog_content = "Se fue de nuevo...",
  ui_story_5086_50860902_4_dialog_content = "¡Miau!",
  ui_story_5086_50860902_5_dialog_content = "¿Eh? ¿Un gato?",
  ui_story_5086_50860902_6_dialog_content = "¡Miau! ¡Miau!",
  ui_story_5086_50860902_7_dialog_content = "¿Estás intentando que te siga?",
  ui_story_5086_50860902_8_dialog_content = "¡Miau!",
  ui_story_5086_50860902_9_dialog_content = "Está bien, de todos modos no sé a dónde ir.",
  ui_story_5086_50860902_10_dialog_content = "<color=#e8d9bb>Chapoteo—</color>",
  ui_story_5086_50860902_11_dialog_content = "¡Uh!",
  ui_story_5086_50860902_12_dialog_content = "Ack... Glub, glub, glub...",
  ui_story_5086_50860902_13_dialog_content = "Él... Glub, glub, glub... Ayuda...",
  ui_story_5086_50860902_14_dialog_content = "Eres tú...",
  ui_story_5086_50860902_15_dialog_content = "<color=#e8d9bb>Chapoteo.</color>",
  ui_story_5086_50860902_16_dialog_content = "¡Pffft! ¡Tos, tos, tos...",
  ui_story_5086_50860902_17_dialog_content = "¡Yo... estoy salvado! Gracias...",
  ui_story_5086_50860902_18_dialog_content = "El suelo simplemente desapareció bajo mí, y me sumergí en el mar. Pensé que estaba perdido.",
  ui_story_5086_50860902_19_dialog_content = "¿Qu-Qué estás haciendo aquí, señorita Stellandine?",
  ui_story_5086_50860902_20_dialog_content = "Escuché el sonido de una concha poco después de que te fuiste, y lo siguiente que supe, estaba aquí.",
  ui_story_5086_50860902_21_dialog_content = "Con nada más que el océano a mi alrededor, todo lo que podía hacer era esperar en esta playa. Fue entonces cuando te vi caer al agua.",
  ui_story_5086_50860902_22_dialog_content = "Fui llevado a un lugar extraño por un gato, luego rescatado después de caer al océano.",
  ui_story_5086_50860902_23_dialog_content = "Es casi como un cuento de hadas.",
  ui_story_5086_50860902_24_dialog_content = "Quizás... esto es un cuento de hadas.",
  ui_story_5086_50860902_25_dialog_content = "Parece que el poder de la línea de sangre de Maya se extiende mucho más allá de calmar los corazones de los demás. También puede crear poderosas ilusiones.",
  ui_story_5086_50860902_26_dialog_content = "Este bien podría ser el escenario de otro cuento de hadas.",
  ui_story_5086_50860902_27_dialog_content = "Aun así, nunca imaginé que usaría sus poderes contra otros de esta manera...",
  ui_story_5086_50860902_28_dialog_content = "Puede que haya más de lo que se ve a simple vista.",
  ui_story_5086_50860902_29_dialog_content = "Cuando vi a Maya antes, parecía estar preocupada por algo.",
  ui_story_5086_50860902_30_dialog_content = "¡Ay! ¡Ah-ah-aaaaaah!",
  ui_story_5086_50860902_31_dialog_content = "Creo que escucho a alguien cantando.",
  ui_story_5086_50860902_32_dialog_content = "¡Mira allá, señorita Stellandine! ¡Junto al agua!",
  ui_story_5086_50860902_33_dialog_content = "Eso es... La hija del océano...",
  ui_story_5086_50860902_34_dialog_content = "¿Te refieres a la sirena de esa historia? Ella es hermosa...",
  ui_story_5086_50860902_35_dialog_content = "¡Oye, viene un barco! ¿Podría ser esta la parte donde el príncipe y la sirena se encuentran por primera vez?",
  ui_story_5086_50860902_36_dialog_content = "Me pregunto si ese barco puede sacarnos de aquí? Oye—",
  ui_story_5086_50860902_37_dialog_content = "... Esto no está funcionando. Es como si la gente en el barco no pudiera vernos en absoluto.",
  ui_story_5086_50860902_38_dialog_content = "...",
  ui_story_5086_50860902_39_dialog_content = "Supongo que simplemente no podemos vencer a la princesa sirena en un concurso de encanto.",
  ui_story_5086_50860902_40_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_5086_50860902_41_dialog_content = "¿Trueno? Y el cielo también se ha oscurecido... ¿Es la tormenta de la historia, eh?",
  ui_story_5086_50860902_42_dialog_content = "Pero el barco está bien, e incluso han navegado hasta ella y le han lanzado una escalera de cuerda...",
  ui_story_5086_50860902_43_dialog_content = "<color=#e8d9bb>En medio del estruendo del trueno, presencio algo inconcebible.</color>",
  ui_story_5086_50860902_44_dialog_content = "<color=#e8d9bb>La sirena extiende su mano blanca como la nieve y arrastra a sus rescatadores al agua.</color>",
  ui_story_5086_50860902_45_dialog_content = "<color=#e8d9bb>Mientras los gritos llenan el aire, un hedor fétido surge del agua, que lentamente se está volviendo de un tono carmesí profundo.</color>",
  ui_story_5086_50860902_46_dialog_content = "<color=#e8d9bb>Cuando la sangre finalmente llega a la orilla, la espantosa escena desaparece de repente.</color>",
  ui_story_5086_50860902_47_dialog_content = "<color=#e8d9bb>Después, nos encontramos de vuelta en el acuario.</color>",
  ui_story_5086_50860902_48_dialog_content = "<color=#e8d9bb>Pero el hedor desagradable parece persistir en el aire a nuestro alrededor.</color>",
  ui_story_5086_50860902_49_dialog_content = "¿Qué fue eso... Ahora mismo...",
  ui_story_5086_50860902_50_dialog_content = "Eso... Eso no fue... ¡Así no cuenta la historia!",
  ui_story_5086_50860902_51_dialog_content = "... Moya es un niño de corazón puro.",
  ui_story_5086_50860902_52_dialog_content = "Tan pura que ve, acepta y ama todo en el mundo exactamente igual.",
  ui_story_5086_50860902_53_dialog_content = "Es posible que lo que acabamos de ver no sea ni bueno ni malo en sus ojos.",
  ui_story_5086_50860902_54_dialog_content = "Entonces, incluso los Eclipsites pueden de alguna manera convertirse en sus compañeros.",
  ui_story_5086_50861001_1_dialog_content = "... No podemos parar ahora.",
  ui_story_5086_50861001_2_dialog_content = "Señorita Stellandine, ¿puedes pararte?",
  ui_story_5086_50861001_3_dialog_content = "Urgh...",
  ui_story_5086_50861001_4_dialog_content = "No puedo.",
  ui_story_5086_50861001_5_dialog_content = "Entonces te llevaré.",
  ui_story_5086_50861001_6_dialog_content = "¿Qué? Pero tú mismo no lo estás haciendo tan bien, ¿verdad?",
  ui_story_5086_50861001_7_dialog_content = "Sí... algo así...",
  ui_story_5086_50861001_8_dialog_content = "Pero no tengo idea de cuántos Eclipsites todavía están acechando a nuestro alrededor, y siento una presencia extraña en algún lugar cercano.",
  ui_story_5086_50861001_9_dialog_content = "Tampoco puedo dejarte aquí.",
  ui_story_5086_50861001_10_dialog_content = "Solo aférrate a mí, y déjame saber si duele demasiado para seguir adelante.",
  ui_story_5086_50861001_11_dialog_content = "Eres un alma tan amable, PlayerName.",
  ui_story_5086_50861001_12_dialog_content = "Lamento haberte involucrado en este lío.",
  ui_story_5086_50861001_13_dialog_content = "Está bien, estoy acostumbrado a este tipo de cosas. Además, estoy seguro de que quieres preservar el acuario más que nadie, ¿verdad?",
  ui_story_5086_50861001_14_dialog_content = "Sí. Preferiría no...",
  ui_story_5086_50861001_15_dialog_content = "¡Rugido!",
  ui_story_5086_50861001_16_dialog_content = "!",
  ui_story_5086_50861001_17_dialog_content = "¡Eclipsites! Tendremos que ir por otro camino.",
  ui_story_5086_50861001_18_dialog_content = "¿Sabes dónde estamos ahora mismo, señorita Stellandine?",
  ui_story_5086_50861001_19_dialog_content = "Lo siento, pero parece que el acuario ha sido completamente deformado.",
  ui_story_5086_50861001_20_dialog_content = "El orden de las habitaciones se ha mezclado, por lo que ni siquiera puedo discernir la dirección en la que nos dirigimos.",
  ui_story_5086_50861001_21_dialog_content = "Supongo que tendremos que arriesgarnos.",
  ui_story_5086_50861001_22_dialog_content = "Mira allá... ¿Quién es ese?",
  ui_story_5086_50861001_23_dialog_content = "Hola, yo soy—",
  ui_story_5086_50861001_24_dialog_content = "H-Ayúdame!",
  ui_story_5086_50861001_25_dialog_content = "¿Eh? Espera, ¿por qué estás huyendo?",
  ui_story_5086_50861001_26_dialog_content = "No me mates—",
  ui_story_5086_50861001_27_dialog_content = "¿Qué está pasando? ¿Está siendo perseguido? Urgh...",
  ui_story_5086_50861001_28_dialog_content = "Señorita Stellandine, ¿hueles algo extraño?",
  ui_story_5086_50861001_29_dialog_content = "¿Algo extraño, dices...?",
  ui_story_5086_50861001_30_dialog_content = "Pensé que era solo un efecto secundario de esa ilusión de sirena de antes, pero aún puedo olerlo ahora.",
  ui_story_5086_50861001_31_dialog_content = "Es un olor a podrido, y parece que se está acercando...",
  ui_story_5086_50861001_32_dialog_content = "Huff... Huff...",
  ui_story_5086_50861001_33_dialog_content = "¿Eh? ¿Quién está ahí?",
  ui_story_5086_50861001_34_dialog_content = "... ¿Sanae? ¡E-Estás cubierto de sangre! ¿Te has lastimado?!",
  ui_story_5086_50861001_35_dialog_content = "¡Por favor dime que estás bien!!",
  ui_story_5086_50861001_36_dialog_content = "¡Eeeek!",
  ui_story_5086_50861001_37_dialog_content = "¿Qué pasa, Sanae?! ¡Solo somos nosotros!",
  ui_story_5086_50861001_38_dialog_content = "¡Rugido!",
  ui_story_5086_50861001_39_dialog_content = "¡Whoa!",
  ui_story_5086_50861001_40_dialog_content = "¿Esta cosa nos ha estado siguiendo todo este tiempo?!",
  ui_story_5086_50861001_41_dialog_content = "Lo siento, señorita Stellandine, pero tengo que dejarte. Por favor, pásame ese palo en la esquina y quédate con Sanae.",
  ui_story_5086_50861001_42_dialog_content = "Olvídate de mí... Solo huye.",
  ui_story_5086_50861001_43_dialog_content = "¡De ninguna manera! ¡Me quedo aquí para luchar!",
  ui_story_5086_50861001_44_dialog_content = "Solo porque normalmente estoy detrás de todos no significa que no sepa cómo proteger a mis amigos!",
  ui_story_5086_50861001_45_dialog_content = "¡Rugido!",
  ui_story_5086_50861001_46_dialog_content = "Jaj—",
  ui_story_5086_50861001_47_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5086_50861001_48_dialog_content = "Graaah—",
  ui_story_5086_50861001_49_dialog_content = "¿Eh? No puede ser... ¿Acabo de derrotar a un Eclipsite de un solo golpe? ¿Yo?!",
  ui_story_5086_50861001_50_dialog_content = "De nada.",
  ui_story_5086_50861001_51_dialog_content = "Sadie! Así que tú eres el que lo sacó.",
  ui_story_5086_50861001_52_dialog_content = "No pierdas la concentración. Hay muchos más de donde vino ese.",
  ui_story_5086_50861001_53_dialog_content = "<size=50>¡Tú estás fuera de aquí!</size>",
  ui_story_5086_50861001_54_dialog_content = "¡Yo también ayudaré! Hya—",
  ui_story_5086_50861001_55_dialog_content = "¡Solo porque normalmente estoy detrás de todos no significa que no sepa cómo proteger a mis amigos! ¡Esa fue una línea muy guay!",
  ui_story_5086_50861001_56_dialog_content = "¡Goldie! ¡Sadie! ¡Aparecisteis justo a tiempo!",
  ui_story_5086_50861001_57_dialog_content = "¡Los ídolos y los espadachines nunca deben llegar tarde, ya sabes!",
  ui_story_5086_50861001_58_dialog_content = "¡Ahora es nuestro momento de brillar!",
  ui_story_5086_50861002_1_dialog_content = "Graaah—",
  ui_story_5086_50861002_2_dialog_content = "¡Gracias por escuchar!",
  ui_story_5086_50861002_3_dialog_content = "Ahora estamos a salvo. Gracias a Dios que llegaste a tiempo.",
  ui_story_5086_50861002_4_dialog_content = "No podría haberlo hecho sin esos visitantes.",
  ui_story_5086_50861002_5_dialog_content = "Nos dijeron que había Eclipsites aterradores acechando en esta dirección, así que vinimos a echar un vistazo.",
  ui_story_5086_50861002_6_dialog_content = "Debe haber sido ese tipo que se escapó justo ahora. Se fue tan pronto como nos vio...",
  ui_story_5086_50861002_7_dialog_content = "¿Has estado solo todo este tiempo, PlayerName?",
  ui_story_5086_50861002_8_dialog_content = "He estado con Sanae y la señorita Stellandine. Los hice esconderse allí... ¿Eh?",
  ui_story_5086_50861002_9_dialog_content = "¿Dónde están? Todo lo que veo es...",
  ui_story_5086_50861002_10_dialog_content = "¿Un charco de sangre?",
  ui_story_5086_50861002_11_dialog_content = "<color=#828282>Clic.</color>",
  ui_story_5086_50861002_12_dialog_content = "Eh... señorita Stellandine?",
  ui_story_5086_50861002_13_dialog_content = "No te preocupes, iré a cerrar la puerta con llave.",
  ui_story_5086_50861002_14_dialog_content = "Ahora somos los únicos aquí.",
  ui_story_5086_50861002_15_dialog_content = "Así que estamos a salvo.",
  ui_story_5086_50861002_16_dialog_content = "¿Está segura, señorita Stellandine?",
  ui_story_5086_50861002_17_dialog_content = "Por supuesto.",
  ui_story_5086_50861002_18_dialog_content = "Entonces por qué...",
  ui_story_5086_50861002_19_dialog_content = "... te ves como...",
  ui_story_5086_50861002_20_dialog_content = "... ¿un Eclipsito?",
  ui_story_5086_50861002_21_dialog_content = "...",
  ui_story_5086_50861002_22_dialog_content = "¿Podría ser que Sanae y la Señorita Stellandine...",
  ui_story_5086_50861002_23_dialog_content = "¡No podemos sacar conclusiones precipitadas hasta que los encontremos!",
  ui_story_5086_50861002_24_dialog_content = "Revisa cada rincón de la habitación. Las personas no desaparecen sin dejar rastro, por lo que debe haber algunas pistas.",
  ui_story_5086_50861002_25_dialog_content = "¡Goldie tiene razón! Buscaré en el pasillo de allí.",
  ui_story_5086_50861002_26_dialog_content = "PlayerName! ¡Esperar!",
  ui_story_5086_50861002_27_dialog_content = "Espera, tu espalda... Hay algo pegajoso en ella. ¿Qué son estos... fragmentos?",
  ui_story_5086_50861002_28_dialog_content = "Se ve un poco asqueroso... Estos fragmentos casi se sienten como carne...",
  ui_story_5086_50861002_29_dialog_content = "Entonces, cuando el sonido alejó a todos, solo tú y yo nos quedamos atrás...",
  ui_story_5086_50861002_30_dialog_content = "¿Fuiste tú quien me atacó por detrás?",
  ui_story_5086_50861002_31_dialog_content = "Así es.",
  ui_story_5086_50861002_32_dialog_content = "... ¿Tú también estabas controlando a todos esos Eclipsites, señorita Stellandine?",
  ui_story_5086_50861002_33_dialog_content = "Así que lo descubriste, ¿eh?",
  ui_story_5086_50861002_34_dialog_content = "Por supuesto. Porque soy bastante hábil en la manipulación.",
  ui_story_5086_50861002_35_dialog_content = "Esos Eclipsites ocasionalmente actúan como... marionetas.",
  ui_story_5086_50861002_36_dialog_content = "Eso es bastante sorprendente. Pero... ya es demasiado tarde.",
  ui_story_5086_50861002_37_dialog_content = "Estoy... realmente hambriento.",
  ui_story_5086_50861002_38_dialog_content = "Lo siento, ha pasado tanto tiempo desde que tuve una comida normal.",
  ui_story_5086_50861002_39_dialog_content = "Tampoco quiero esto...",
  ui_story_5086_50861002_40_dialog_content = "Pero simplemente ya no lo soporto más...",
  ui_story_5086_50861002_41_dialog_content = "Tengo un favor que pedirte. Por favor... ¡sé mi comida!",
  ui_story_5086_50861002_42_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5086_50861002_43_dialog_content = "¿Por qué debes resistirte? ¿¡Por qué nada va a mi manera!?",
  ui_story_5086_50861002_44_dialog_content = "Perdóname, pero soy una sirvienta de la familia Andersen.",
  ui_story_5086_50861002_45_dialog_content = "No he completado la tarea que el Sr. Minos me confió. Sin mencionar que la señorita Nina está esperando mi regreso.",
  ui_story_5086_50861002_46_dialog_content = "T-Todavía tengo amigos que quiero volver a ver, así que por favor...",
  ui_story_5086_50861002_47_dialog_content = "No puedo permitirme ser comido por ti.",
  ui_story_5086_50861002_48_dialog_content = "Si tienes tanta hambre, intenta comerte a ti mismo, maldito monstruo!",
  ui_story_5086_50861002_49_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5086_50861002_50_dialog_content = "¿Qué es esta loca fuerza?! ¡Es como si estuviera enfrentando a una persona completamente diferente!",
  ui_story_5086_50861002_51_dialog_content = "Pero no importa cuán poderoso seas, aún estás herido.",
  ui_story_5086_50861002_52_dialog_content = "¡Ataque!",
  ui_story_5086_50861002_53_dialog_content = "¡Rugido!",
  ui_story_5086_50861002_54_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5086_50861002_55_dialog_content = "<color=#e8d9bb>Los Eclipsites irrumpen en la habitación pero son expulsados solo un momento después—Por supuesto, ninguno de ellos respira ahora.</color>",
  ui_story_5086_50861002_56_dialog_content = "¡¿Qué?!",
  ui_story_5086_50861002_57_dialog_content = "Bajo circunstancias ordinarias, los invitados deben tratar a su anfitrión con el máximo respeto.",
  ui_story_5086_50861002_58_dialog_content = "Dado que atacaste a la sirvienta de mi familia, no me dejaste otra opción.",
  ui_story_5086_50861002_59_dialog_content = "Por el honor de la familia Andersen y para aplacar mi propia ira...",
  ui_story_5086_50861002_60_dialog_content = "Debo apartarme de mi habitual cortesía.",
  ui_story_5086_50861002_61_dialog_content = "Qué entrometido...",
  ui_story_5086_50861002_62_dialog_content = "¡Rugido!",
  ui_story_5086_50861002_63_dialog_content = "Hazte a un lado, bestia sucia.",
  ui_story_5086_50861002_64_dialog_content = "Humph, criaturas tan cobardes.",
  ui_story_5086_50861100_1_dialog_content = "Sanae—¿dónde estás—",
  ui_story_5086_50861100_2_dialog_content = "¡Si puedes oírnos, di algo!",
  ui_story_5086_50861100_3_dialog_content = "Sanae—",
  ui_story_5086_50861100_4_dialog_content = "¡Señorita Moya! ¡No te vayas!",
  ui_story_5086_50861100_5_dialog_content = "¡Esa voz...!",
  ui_story_5086_50861100_6_dialog_content = "¡Froude! ¡Maya!",
  ui_story_5086_50861100_7_dialog_content = "Oh, PlayerName...",
  ui_story_5086_50861100_8_dialog_content = "Estarás seguro aquí, Froude. Lo siento, pero tengo que irme ahora.",
  ui_story_5086_50861100_9_dialog_content = "¡No lo haré! ¡No te dejaré ir!",
  ui_story_5086_50861100_10_dialog_content = "¿La encontraste? ¿La chica que estaba controlando esos tiburones...?",
  ui_story_5086_50861100_11_dialog_content = "¡No dejes que ella se escape!",
  ui_story_5086_50861100_12_dialog_content = "...",
  ui_story_5086_50861100_13_dialog_content = "¡Por favor cálmense todos! Maya es—",
  ui_story_5086_50861100_14_dialog_content = "¡Ustedes no saben nada sobre ella! ¡Son todos un montón de idiotas!",
  ui_story_5086_50861100_15_dialog_content = "Froude...",
  ui_story_5086_50861100_16_dialog_content = "¡La señorita Maya es la más tonta de todas! ¡Ni siquiera sabe cuidar de sí misma!",
  ui_story_5086_50861100_17_dialog_content = "¡Ella nunca hizo nada malo! ¡Estoy seguro de que ella también quiere atrapar al malo!",
  ui_story_5086_50861100_18_dialog_content = "Disculpa, pero ¿no fue Maya la que devolvió todos esos peces a sus tanques antes de que mordieran a alguien?",
  ui_story_5086_50861100_19_dialog_content = "¡Yo... Yo soy de por aquí, y puedo responder por Maya! Durante los últimos años, todo lo que ha hecho es ayudar a la gente por toda la ciudad!",
  ui_story_5086_50861100_20_dialog_content = "No creo que ella pudiera haber lastimado a nadie.",
  ui_story_5086_50861100_21_dialog_content = "¡Oye! ¿¡Qué les pasa a ustedes?!",
  ui_story_5086_50861100_22_dialog_content = "¿¡Realmente estás defendiéndola en un momento como este?!",
  ui_story_5086_50861100_23_dialog_content = "Existe una forma de averiguarlo de una vez por todas.",
  ui_story_5086_50861100_24_dialog_content = "(Minos... Gracias por la ayuda.)",
  ui_story_5086_50861100_25_dialog_content = "No tú otra vez, niño... ¡Espera, ahora recuerdo! ¡Eres el Celestita!",
  ui_story_5086_50861100_26_dialog_content = "Así es, lo que significa que poseo habilidades psíquicas.",
  ui_story_5086_50861100_27_dialog_content = "Recuerdo que fuiste el primero que me estrechó la mano antes. Ya confirmé que eres completamente inocente en este caso.",
  ui_story_5086_50861100_28_dialog_content = "E-Eso es verdad.",
  ui_story_5086_50861100_29_dialog_content = "No se puede negar el talento del niño.",
  ui_story_5086_50861100_30_dialog_content = "Eso también significa que puedo probar si Maya es inocente o no en este momento.",
  ui_story_5086_50861100_31_dialog_content = "Lo siento, Maya. Sé que dije que no usaría mis poderes en ti si no estabas de acuerdo con ello.",
  ui_story_5086_50861100_32_dialog_content = "Pero estoy convencido de que eres una buena persona, y muchas personas sienten lo mismo también.",
  ui_story_5086_50861100_33_dialog_content = "¿Me permitirás hacer eso, Maya?",
  ui_story_5086_50861100_34_dialog_content = "Pero.",
  ui_story_5086_50861100_35_dialog_content = "Escucha con atención, Maya.",
  ui_story_5086_50861100_36_dialog_content = "Lo que dije justo ahora fue solo para hacer que esas personas retrocedieran.",
  ui_story_5086_50861100_37_dialog_content = "¿Así que no vas a leer mi mente?",
  ui_story_5086_50861100_38_dialog_content = "Y creo que es porque creí en ti desde el principio mismo.",
  ui_story_5086_50861100_39_dialog_content = "Mis poderes psíquicos funcionan en ambos sentidos. Incluso yo tendría dificultades para decir una mentira cuando nuestras mentes están conectadas.",
  ui_story_5086_50861100_40_dialog_content = "Es por eso que quiero que mires dentro de mi mente primero, Maya.",
  ui_story_5086_50861100_41_dialog_content = "Si crees que soy digno de tu confianza, entonces por favor dime tus razones para hacer todo esto.",
  ui_story_5086_50861100_42_dialog_content = "¿Eso... está realmente bien?",
  ui_story_5086_50861100_43_dialog_content = "Depende de ti decidir.",
  ui_story_5086_50861100_44_dialog_content = "<color=#e8d9bb>Con un pequeño asentimiento, Maya está de acuerdo en silencio.</color>",
  ui_story_5086_50861100_45_dialog_content = "<color=#e8d9bb>Después de eso, ella extendió nerviosamente una mano y dejó que nuestras yemas de los dedos se tocaran.</color>",
  ui_story_5086_50861100_46_option_content = "Enlace mental!",
  ui_story_5086_50861100_47_dialog_content = "<color=#e8d9bb>Bajo un sol deslumbrante, las flores se convierten en mariposas y revolotean hacia el cielo para merendar nubes de malvaviscos.</color>",
  ui_story_5086_50861100_48_dialog_content = "<color=#e8d9bb>Innumerables burbujas iridiscentes flotan a través del cielo, bañando el sueño en su caprichosa luminiscencia.</color>",
  ui_story_5086_50861100_49_dialog_content = "(Entonces este es el mundo de sueños de Maya... Es hermoso.)",
  ui_story_5086_50861100_50_dialog_content = "(Pero...)",
  ui_story_5086_50861100_51_dialog_content = "(¡Oh, hombre! ¿Por qué soy una rana de nuevo?!)",
  ui_story_5086_50861100_52_dialog_content = "¡Croac, croac!",
  ui_story_5086_50861100_53_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5086_50861100_54_dialog_content = "(¡Ay... ¿Esta bola está hecha de oro sólido?!)",
  ui_story_5086_50861100_55_dialog_content = "Lo siento por eso, Sr. Froggy! ¿Podría <color=#FFB400>yo</color> tener mi pelota de vuelta?",
  ui_story_5086_50861100_56_dialog_content = "Croac.",
  ui_story_5086_50861100_57_dialog_content = "¡Gracias! ¡Muah!",
  ui_story_5086_50861100_58_dialog_content = "!!!",
  ui_story_5086_50861100_59_dialog_content = "¡¿Q-Qué estás haciendo, Maya?! No puedes simplemente ir por ahí besando a la gente—Oye, ¡he vuelto a la normalidad!",
  ui_story_5086_50861100_60_dialog_content = "¡Podemos jugar juntos si quieres! ¡Vamos!",
  ui_story_5086_50861100_61_dialog_content = "<color=#e8d9bb>De repente, nos encontramos sentados en un carruaje dorado tirado por seis hermosos caballos mientras se lanzan hacia una enorme burbuja en el cielo.</color>",
  ui_story_5086_50861100_62_dialog_content = "¡Este es el bosque de dulces! El suelo y los árboles están hechos de pasteles y galletas, así que come lo que quieras.",
  ui_story_5086_50861100_63_dialog_content = "¡Recuerda no comer la casa de pan de jengibre aquí, o la bruja se enfadará!",
  ui_story_5086_50861100_64_dialog_content = "<color=#e8d9bb>Después de comer hasta saciarnos de dulces, saltamos a la espalda de un cisne blanco como la nieve y volamos hacia otra burbuja.</color>",
  ui_story_5086_50861100_65_dialog_content = "El palacio está organizando un baile, ¡y todos están invitados!",
  ui_story_5086_50861100_66_dialog_content = "Si recogemos algunas enredaderas al costado del camino, podemos tejer algunos atuendos que brillen más que la luna y las estrellas!",
  ui_story_5086_50861100_67_dialog_content = "<color=#e8d9bb>Después de cambiarnos a nuestra hermosa nueva ropa, trepamos por un tallo de frijol y entramos en otra burbuja.</color>",
  ui_story_5086_50861100_68_dialog_content = "<color=#e8d9bb>Juntos, atravesamos innumerables burbujas de sueño.</color>",
  ui_story_5086_50861100_69_dialog_content = "<color=#e8d9bb>Había montañas de oro y plata, e incluso una hecha de vidrio...</color>",
  ui_story_5086_50861100_70_dialog_content = "<color=#e8d9bb>También escuchamos un concierto interpretado por un burro, un gallo, un gato y un perro...</color>",
  ui_story_5086_50861100_71_dialog_content = "... Y al otro lado de la ciudad se encuentra un doctor omnisciente.",
  ui_story_5086_50861100_72_dialog_content = "¡Él sabe todo sobre el mundo y puede responder cualquier pregunta!",
  ui_story_5086_50861100_73_dialog_content = "¿En serio? Si tenemos la oportunidad de verlo, quiero preguntarle algo-",
  ui_story_5086_50861100_74_dialog_content = "¿Puedes decirme dónde encontrar a la verdadera Maya?",
  ui_story_5086_50861100_75_dialog_content = "...",
  ui_story_5086_50861100_76_dialog_content = "Que extraño.",
  ui_story_5086_50861100_77_dialog_content = "<color=#e8d9bb>Una luz peculiar destella a través de los ojos de Maya.</color>",
  ui_story_5086_50861100_78_dialog_content = "¿Cuándo te diste cuenta?",
  ui_story_5086_50861100_79_dialog_content = "Desde el principio.",
  ui_story_5086_50861100_80_dialog_content = "Cuando Maya nos contó su historia, pensé que estaría bien si alguien recordaba su existencia.",
  ui_story_5086_50861100_81_dialog_content = "Maya dijo que nos hicimos amigos tan pronto como nos presentamos.",
  ui_story_5086_50861100_82_dialog_content = "Entonces, recordarla es lo menos que podría hacer, ¿verdad?",
  ui_story_5086_50861100_83_dialog_content = "Un cuaderno no debería ser lo único que prueba su existencia en el mundo.",
  ui_story_5086_50861100_84_dialog_content = "Pero entonces... ¿Quién la cuidaba antes de que conociera a otras personas?",
  ui_story_5086_50861100_85_dialog_content = "...",
  ui_story_5086_50861100_86_dialog_content = "Además de mi sangre, mis descendientes también heredan el poder de manipular su entorno, e incluso la realidad misma.",
  ui_story_5086_50861100_87_dialog_content = "Con el paso del tiempo, mi linaje se ha debilitado y mis descendientes ya no pueden controlar este poder.",
  ui_story_5086_50861100_88_dialog_content = "No solo es incapaz de manejar mi poder, sino que nuestra conexión de sangre también se ha vuelto tenue. Esto hace que pierda sus recuerdos y se sumerja en mundos de fantasía.",
  ui_story_5086_50861100_89_dialog_content = "Si el portador no puede comandar mi poder, también influirá en las personas a su alrededor. Simplemente ver o oler mi sangre o escuchar mi voz los atrapará en una ilusión.",
  ui_story_5086_50861100_90_dialog_content = "Entonces, cuando Maya dijo que no podía sangrar...",
  ui_story_5086_50861100_91_dialog_content = "Sin embargo, la situación en el acuario debe tener algo que ver con el poder de Maya.",
  ui_story_5086_50861100_92_dialog_content = "Si eres el Ancestro que ella mencionó antes... ¿Podrías decirme qué sucedió aquí?",
  ui_story_5086_50861100_93_dialog_content = "Como dije antes, mis descendientes carecen de la capacidad para controlar los sueños.",
  ui_story_5086_50861100_94_dialog_content = "Sin embargo, ella ha logrado todo esto.",
  ui_story_5086_50861100_95_dialog_content = "Si realmente eres su amigo, entonces deberías conocer la causa de estos eventos.",
  ui_story_5086_50861100_96_dialog_content = "Tienes razón...",
  ui_story_5086_50861100_97_dialog_content = "May ¿Te hago una última pregunta?",
  ui_story_5086_50861100_98_dialog_content = "El mundo de Maya es como un cuento de hadas. Es un lugar perfecto que tiene todo lo que una persona podría desear.",
  ui_story_5086_50861100_99_dialog_content = "Pero noté algo extraño mientras volábamos a través de todos esos sueños... ¿Por qué no vi el océano en ninguno de ellos?",
  ui_story_5086_50861100_100_dialog_content = "Debes haber posado tus ojos en el mar para ahora.",
  ui_story_5086_50861100_101_dialog_content = "Dentro de la pesadilla que mis descendientes no se atreven a ver.",
  ui_story_5086_50861100_102_dialog_content = "Ya veo... Ahora lo entiendo.",
  ui_story_5086_50861100_103_dialog_content = "¿Responderás a una pregunta mía?",
  ui_story_5086_50861100_104_dialog_content = "Por supuesto. Pregúntame lo que sea.",
  ui_story_5086_50861100_105_dialog_content = "Si...",
  ui_story_5086_50861100_106_dialog_content = "¿Eh? Tú...",
  ui_story_5086_50861100_107_dialog_content = "Si te diera todos mis vestidos, gemas y perlas...",
  ui_story_5086_50861100_108_dialog_content = "¿Te quedarías aquí conmigo para siempre?",
  ui_story_5086_50861100_109_dialog_content = "...",
  ui_story_5086_50861100_110_dialog_content = "No quiero tus tesoros en absoluto, Maya.",
  ui_story_5086_50861100_111_dialog_content = "Solo quiero que sonrías.",
  ui_story_5086_50861100_112_dialog_content = "Y esa es la verdad, tanto aquí como en el mundo real.",
  ui_story_5086_50861100_113_dialog_content = "!",
  ui_story_5086_50861100_114_dialog_content = "<color=#e8d9bb>El largo y distante canto comienza de nuevo.</color>",
  ui_story_5086_50861100_115_dialog_content = "<color=#e8d9bb>La escena onírica que los rodea se convierte en niebla y se desvanece gradualmente, revelando nuevamente el acuario tenue iluminado.</color>",
  ui_story_5086_50861100_116_dialog_content = "Estamos de vuelta... ¿Eh? ¿Por qué todos están durmiendo?",
  ui_story_5086_50861100_117_dialog_content = "¡Ahhh—Qué siesta tan maravillosa! ¡Jejeje!",
  ui_story_5086_50861100_118_dialog_content = "Bienvenida de nuevo, Maya.",
  ui_story_5086_50861100_119_dialog_content = "Sé que dije todo eso justo ahora, pero no tienes que obligarte a sonreír si no te apetece.",
  ui_story_5086_50861100_120_dialog_content = "No sería correcto si lo hicieras.",
  ui_story_5086_50861100_121_dialog_content = "...",
  ui_story_5086_50861100_122_dialog_content = "Desde que ese invitado desapareció, no has sonreído ni una sola vez. Al menos, no una sonrisa real.",
  ui_story_5086_50861100_123_dialog_content = "... Simplemente ya no sé qué hacer.",
  ui_story_5086_50861100_124_dialog_content = "Entonces sabías exactamente quién hizo desaparecer a esa persona todo el tiempo.",
  ui_story_5086_50861100_125_dialog_content = "Quiero que las personas sientan remordimiento cuando hacen cosas malas...",
  ui_story_5086_50861100_126_dialog_content = "La envié a ese sueño para arrepentirse hasta que esté lista para compensarlo con todos.",
  ui_story_5086_50861100_127_dialog_content = "¡Yo... solo tengo que esforzarme un poco más para preservar su sueño!",
  ui_story_5086_50861100_128_dialog_content = "¡Estoy seguro de que ella sabe que lo que hizo estuvo mal!",
  ui_story_5086_50861100_129_dialog_content = "Así que por favor, solo dame un poco más de tiempo...",
  ui_story_5086_50861100_130_dialog_content = "No puedes borrar los errores de otras personas, Maya.",
  ui_story_5086_50861100_131_dialog_content = "Y tampoco podemos vivir en un sueño para siempre.",
  ui_story_5086_50861100_132_dialog_content = "Y en tu corazón, ya lo sabes. Es por eso que el acuario volvió a este estado otra vez.",
  ui_story_5086_50861100_133_dialog_content = "Todavía no has dominado la habilidad de controlar los sueños, por eso se vuelven aterradores cada vez que te obligas a hacerlo.",
  ui_story_5086_50861100_134_dialog_content = "No entiendo... ¿Por qué no se arrepiente de sus acciones? ¿Por qué insiste en hacernos lastimar el uno al otro?",
  ui_story_5086_50861100_135_dialog_content = "Tal vez es porque no todos son tan fuertes como tú, Maya.",
  ui_story_5086_50861100_136_dialog_content = "¿Es esto yo... siendo fuerte?",
  ui_story_5086_50861100_137_dialog_content = "¿Aunque estoy llorando?",
  ui_story_5086_50861100_138_dialog_content = "Eso no es todo.",
  ui_story_5086_50861100_139_dialog_content = "Está bien llorar y enfadarse cuando sentimos dolor o desesperación. Es una reacción perfectamente normal.",
  ui_story_5086_50861100_140_dialog_content = "Las personas fuertes no se vuelven débiles solo porque lloran.",
  ui_story_5086_50861100_141_dialog_content = "No entiendo.",
  ui_story_5086_50861100_142_dialog_content = "Hmm, entonces déjame decirlo de otra manera.",
  ui_story_5086_50861100_143_dialog_content = "Si alguna vez te encuentras en serios problemas...",
  ui_story_5086_50861100_144_dialog_content = "Por ejemplo, imagina si el acuario comenzara a recibir menos visitantes y estuviera en peligro de cerrar.",
  ui_story_5086_50861100_145_dialog_content = "¿Cuál es la primera cosa que harás?",
  ui_story_5086_50861100_146_dialog_content = "¿Cerrando...? ¡De ninguna manera! Saldría a buscar más invitados si eso alguna vez sucediera!",
  ui_story_5086_50861100_147_dialog_content = "Entonces, ¿qué harías si nadie en Harbor City estuviera dispuesto a visitar el acuario?",
  ui_story_5086_50861100_148_dialog_content = "¡Ve a un lugar muy, muy lejano! Saldré de Harbor City, o al otro lado del mar, ¡o incluso al otro lado del cielo!",
  ui_story_5086_50861100_149_dialog_content = "¡Solo seguiré buscando! ¡Estoy seguro de que encontraré a alguien que quiera visitarnos eventualmente!",
  ui_story_5086_50861100_150_dialog_content = "¿Y si fallas?",
  ui_story_5086_50861100_151_dialog_content = "¡Si al principio no tienes éxito, intenta e intenta de nuevo!",
  ui_story_5086_50861100_152_dialog_content = "¿Y no te sentirías desanimado por eso?",
  ui_story_5086_50861100_153_dialog_content = "Me sentiré mal, ¡pero siempre habrá mañana! Además, ¡no es como si fuera a recordar algo!",
  ui_story_5086_50861100_154_dialog_content = "¡Pero sé que mientras siga esforzándome al máximo, eventualmente tendré éxito!",
  ui_story_5086_50861100_155_dialog_content = "¡Porque así es como funciona el mundo!",
  ui_story_5086_50861100_156_dialog_content = "Y eso es lo que me hace fuerte.",
  ui_story_5086_50861100_157_dialog_content = "La mayoría de las personas en el mundo no se atreven a tener esperanzas de la manera que tú lo haces, Maya.",
  ui_story_5086_50861100_158_dialog_content = "Eso es porque viven en una burbuja conocida como realidad.",
  ui_story_5086_50861100_159_dialog_content = "En esa burbuja, no se garantiza que el trabajo duro dé frutos, y los milagros no suceden simplemente porque las personas creen en ellos.",
  ui_story_5086_50861100_160_dialog_content = "Algunas personas nunca llegan a ver un final feliz en sus historias. Solo sufren dificultades tras dificultades dolorosas.",
  ui_story_5086_50861100_161_dialog_content = "Sería una carga tan pesada y difícil de llevar, y no se sabe cuánto tiempo tendrías que cargarla.",
  ui_story_5086_50861100_162_dialog_content = "A veces, ni siquiera saben si estas historias amargas alguna vez llegarán a su fin.",
  ui_story_5086_50861100_163_dialog_content = "La mayoría de las personas eventualmente cederían bajo el peso, sin forma de levantarse y moverse de nuevo.",
  ui_story_5086_50861100_164_dialog_content = "Pero eso no me gusta...",
  ui_story_5086_50861100_165_dialog_content = "Nadie lo hace, Maya.",
  ui_story_5086_50861100_166_dialog_content = "Entonces, aquellos que encuentran imposible soportarlo más tiempo lo imponen a los demás.",
  ui_story_5086_50861100_167_dialog_content = "¿Eh...?",
  ui_story_5086_50861100_168_dialog_content = "Mientras alguien más luche por él, puede sufrir un poco más. Mientras alguien más se lastime en su lugar, seguirá avanzando.",
  ui_story_5086_50861100_169_dialog_content = "Mientras haya personas dispuestas a compartir su carga, él podría vivir para ver un final feliz en su historia algún día.",
  ui_story_5086_50861100_170_dialog_content = "...",
  ui_story_5086_50861100_171_dialog_content = "Esa persona... Él también era así.",
  ui_story_5086_50861100_172_dialog_content = "Empujó su dolor a otras personas solo para seguir adelante.",
  ui_story_5086_50861100_173_dialog_content = "Hizo algo malo, algo que nunca debería haber hecho.",
  ui_story_5086_50861100_174_dialog_content = "Bueno, entiendo tu deseo de hacer que los malhechores se arrepientan.",
  ui_story_5086_50861100_175_dialog_content = "Pero aquellos que cometen maldades son débiles de corazón, por lo que no pueden soportar el peso de sus errores por sí mismos.",
  ui_story_5086_50861100_176_dialog_content = "Aunque sea triste, solo podemos enfrentarlos y buscar justicia.",
  ui_story_5086_50861100_177_dialog_content = "Lo siento, Maya... Pero es inalcanzable solo con sueños.",
  ui_story_5086_50861100_178_dialog_content = "Las buenas personas merecen ser recompensadas, y las malas personas merecen ser castigadas. Incluso yo sé eso...",
  ui_story_5086_50861100_179_dialog_content = "Y esa es la única forma en que una historia puede llegar a su fin.",
  ui_story_5086_50861100_180_dialog_content = "He presenciado numerosos sueños tristes. Gracias por permitirme presenciar tales sueños preciosos.",
  ui_story_5086_50861100_181_dialog_content = "No te preocupes, Maya... Me quedaré a tu lado, aunque no pueda hacer mucho para ayudar.",
  ui_story_5086_50861100_182_dialog_content = "No, esto ya es más que suficiente.",
  ui_story_5086_50861100_183_dialog_content = "No me rendiré. Resolveré las cosas en la realidad para que todos vuelvan a sonreír!",
  ui_story_5086_50861100_184_dialog_content = "Lo siento, Ancestro. ¡Por favor, ayúdame a enviar a todos de vuelta!",
  ui_story_5086_50861100_185_dialog_content = "<color=#e8d9bb>En el siguiente momento, el acuario oscurecido desaparece como una burbuja reventada.</color>",
  ui_story_5086_50861100_186_dialog_content = "<color=#e8d9bb>Vagamente, escucho una voz en algún lugar cercano...</color>",
  ui_story_5086_50861100_187_dialog_content = "Descendiente de los Celestitas, te imploro que protejas mi sangre.",
  ui_story_5086_50861100_188_dialog_content = "Ella es una rareza, una persona de pura y sincera autenticidad.",
  ui_story_5086_50861100_189_dialog_content = "<color=#e8d9bb>Y así la ilusión distorsionada finalmente llegó a su fin.</color>",
  ui_story_5086_50861201_1_dialog_content = "Urgh... ¿Cuándo me quedé dormido...? ¿Eh? ¿Todo volvió a la normalidad?",
  ui_story_5086_50861201_2_dialog_content = "La energía está encendida y el acuario está totalmente bien.",
  ui_story_5086_50861201_3_dialog_content = "Incluso la puerta está intacta, y nada está inundado.",
  ui_story_5086_50861201_4_dialog_content = "¿Fue todo eso solo un sueño?",
  ui_story_5086_50861201_5_dialog_content = "¡Ah! ¡Oye! ¡¿Estás bien?!",
  ui_story_5086_50861201_6_dialog_content = "Ngh... ¿Q-Qué está pasando...?",
  ui_story_5086_50861201_7_dialog_content = "¡Pensé que habías desaparecido! Gracias a Dios que solo tienes algunas lesiones leves...",
  ui_story_5086_50861201_8_dialog_content = "¿Qué diablos acabamos de experimentar...?",
  ui_story_5086_50861201_9_dialog_content = "Todo fue una ilusión, pero gracias a Maya, nadie más resultó herido.",
  ui_story_5086_50861201_10_dialog_content = "Yo... ya no puedo recordar.",
  ui_story_5086_50861201_11_dialog_content = "Estoy seguro de que Maya estaba desconcertada por esos casos y trabajó duro para resolverlos.",
  ui_story_5086_50861201_12_dialog_content = "Entonces, cuando finalmente capturó la malicia del culpable, lanzó imprudentemente esa ilusión.",
  ui_story_5086_50861201_13_dialog_content = "Maya tenía miedo de que alguien más resultara herido, por lo que usó desesperadamente una habilidad que May incluso podría dañarla a ella misma, y es por eso que la pesadilla solo permaneció como una pesadilla.",
  ui_story_5086_50861201_14_dialog_content = "¿Logré compensar algunos de los errores de esa persona?",
  ui_story_5086_50861201_15_dialog_content = "...Sí.",
  ui_story_5086_50861201_16_dialog_content = "¿Dónde está la señorita Stellandine?",
  ui_story_5086_50861201_17_dialog_content = "¿Cómo es que ella es la única que no está aquí?",
  ui_story_5086_50861201_18_dialog_content = "¿Pasó algo? Había un enjambre de Eclipsites allí atrás...",
  ui_story_5086_50861201_19_dialog_content = "Eso no es necesario.",
  ui_story_5086_50861201_20_dialog_content = "Temo que ella sea la única entre nosotros que no tiene que preocuparse en absoluto por los Eclipsites.",
  ui_story_5086_50861201_21_dialog_content = "Minos, ¿lo sabías desde el principio?",
  ui_story_5086_50861201_22_dialog_content = "Piensas demasiado bien de mí. Yo también confirmé gradualmente mis sospechas a través de ciertas características.",
  ui_story_5086_50861201_23_dialog_content = "¿De qué estás hablando?",
  ui_story_5086_50861201_24_dialog_content = "Estoy seguro de que todos ustedes han oído el cuento de hadas sobre la princesa sirena.",
  ui_story_5086_50861201_25_dialog_content = "Los cuentos de hadas pueden ser una fantasía, aún tienen un lado que está arraigado en la realidad: metáforas o lecciones.",
  ui_story_5086_50861201_26_dialog_content = "Una de las formas de interpretar ese cuento de hadas es que muestra la forma y los hábitos de un tipo de forma de vida marina.",
  ui_story_5086_50861201_27_dialog_content = "Una criatura que toma la forma de una hermosa Aurorian utiliza su voz y apariencia para atraer a los marineros o visitantes.",
  ui_story_5086_50861201_28_dialog_content = "Una vez que su objetivo ha sido atraído...",
  ui_story_5086_50861201_29_dialog_content = "Arrastra a su objetivo a las profundidades del océano, convirtiéndolos en su alimento.",
  ui_story_5086_50861201_30_dialog_content = "Entonces, la princesa sirena no es más que un monstruo que caza con el \"deseo\" como su cebo.",
  ui_story_5086_50861201_31_dialog_content = "No me digas...",
  ui_story_5086_50861201_32_dialog_content = "Entonces, ¿todas las desapariciones fueron causadas por la criatura que se infiltró en nuestro grupo?",
  ui_story_5086_50861201_33_dialog_content = "No importa cómo se cambie a sí mismo, un monstruo siempre...",
  ui_story_5086_50861201_34_dialog_content = "¡Cállate!",
  ui_story_5086_50861201_35_dialog_content = "¡Eclipsites!",
  ui_story_5086_50861201_36_dialog_content = "¡Cállate! ¡Cállate! ¡Cállate!!!",
  ui_story_5086_50861201_37_dialog_content = "No, esa voz... ¿Señorita Stellandine?!",
  ui_story_5086_50861201_38_dialog_content = "?!",
  ui_story_5086_50861201_39_dialog_content = "¿Monstruo? ¿Criatura?!",
  ui_story_5086_50861201_40_dialog_content = "¡Si tienes hambre, comes! ¡Es lo mismo para todos!",
  ui_story_5086_50861201_41_dialog_content = "¡Ninguna excusa en el mundo cambiará el hecho de que tú también dependes de la carne y la sangre de otros seres vivos para sobrevivir!",
  ui_story_5086_50861201_42_dialog_content = "Es solo que nuestra comida difiere...",
  ui_story_5086_50861201_43_dialog_content = "Entonces, ¿por qué te has contenido hasta ahora?",
  ui_story_5086_50861201_44_dialog_content = "!",
  ui_story_5086_50861201_45_dialog_content = "Aunque estabas peleando en una ilusión, aún valía la pena estudiar.",
  ui_story_5086_50861201_46_dialog_content = "Eres anormalmente débil en comparación con otros de tu tipo.",
  ui_story_5086_50861201_47_dialog_content = "Es casi como si... No te hubieras alimentado en mucho tiempo.",
  ui_story_5086_50861201_48_dialog_content = "¿Qué? ¿De verdad pensaste que comiendo suficientes aurorianos te permitiría vivir como uno?",
  ui_story_5086_50861201_49_dialog_content = "¡Te dije que te callaras!",
  ui_story_5086_50861201_50_dialog_content = "Según entiendo, criaturas como tú pueden leer y aprender de los recuerdos de los Aurorianos que has devorado.",
  ui_story_5086_50861201_51_dialog_content = "Aún así, careces de un sistema de procesamiento integral. Por lo tanto, cuanto más devoras, más caóticos se vuelven los recuerdos.",
  ui_story_5086_50861201_52_dialog_content = "Nunca deberías haber vivido en tierra, pero Stellandine ha existido durante mucho tiempo.",
  ui_story_5086_50861201_53_dialog_content = "No, debería decir que has estado \"atascado\" durante demasiado tiempo.",
  ui_story_5086_50861201_54_dialog_content = "No solo dejaste el océano y viviste como un Aurorian, sino que has estado rechazando alimentarte durante mucho tiempo.",
  ui_story_5086_50861201_55_dialog_content = "Realmente quiero saber. ¿Por qué lo hiciste?",
  ui_story_5086_50861201_56_dialog_content = "Yo... quiero...",
  ui_story_5086_50861201_57_dialog_content = "Veo.",
  ui_story_5086_50861201_58_dialog_content = "Te has olvidado.",
  ui_story_5086_50861201_59_dialog_content = "No tengo más preguntas. Al final, sigues siendo un Eclipsite lamentable.",
  ui_story_5086_50861201_60_dialog_content = "¡Por qué tú...!",
  ui_story_5086_50861201_61_dialog_content = "Señorita Stellandine...",
  ui_story_5086_50861201_62_dialog_content = "¡Has hecho muchas cosas malas e imperdonables!",
  ui_story_5086_50861201_63_dialog_content = "Pero... Sé que sinceramente deseabas convertirte en un Auroriano... Por eso nunca sentí ninguna malicia.",
  ui_story_5086_50861201_64_dialog_content = "Si aún estás dispuesto a cambiar, entonces estoy dispuesto a buscar la expiación contigo...",
  ui_story_5086_50861201_65_dialog_content = "Señorita Maya, ella es una Eclipsite.",
  ui_story_5086_50861201_66_dialog_content = "Mientras eso siga siendo un hecho, siempre seremos enemigos.",
  ui_story_5086_50861201_67_dialog_content = "No intento defenderla ni nada... ¿Pero la señorita Stellandine realmente se ha ido para siempre?",
  ui_story_5086_50861201_68_dialog_content = "... Eso es suficiente.",
  ui_story_5086_50861201_69_dialog_content = "¿Señorita Stellandine?",
  ui_story_5086_50861201_70_dialog_content = "Oh, Maya...",
  ui_story_5086_50861201_71_dialog_content = "¡Qué gran tonto!!",
  ui_story_5086_50861201_72_dialog_content = "... ¿Ah?",
  ui_story_5086_50861201_73_dialog_content = "¡Eso es! Esa es la expresión que atrae el cariño de todos.",
  ui_story_5086_50861201_74_dialog_content = "¡Es tan triste que no pueda recordar nada, pero sé que a todos les gustará si doy lo mejor de mí en la vida!",
  ui_story_5086_50861201_75_dialog_content = "Estoy seguro de que lo disfrutas tremendamente, ¿verdad? ¡Debes estar tan satisfecho contigo mismo ahora mismo!",
  ui_story_5086_50861201_76_dialog_content = "Mi pequeña Maya, lamentable pero adorable... Pero, ¿de qué servía? En toda tu vida, no has hecho nada significativo una sola vez—",
  ui_story_5086_50861201_77_dialog_content = "¡¿Pero por qué eres el único que disfruta del amor de todos?!",
  ui_story_5086_50861201_78_dialog_content = "No, señorita Stellandine... Por favor... No digas cosas así...",
  ui_story_5086_50861201_79_dialog_content = "¡Esa fue la única razón por la que fui tan amable contigo! ¡Para que el aguijón de la traición doliera aún más!",
  ui_story_5086_50861201_80_dialog_content = "¡Tonta chica! ¿Realmente creías que un monstruo tendría emociones aurorianas?! ¡Jajaja! Realmente caíste en ello, ¿eh?",
  ui_story_5086_50861201_81_dialog_content = "Pero señorita Stellandine, puedo decir que todavía estás llorando por dentro...",
  ui_story_5086_50861201_82_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5086_50861201_83_dialog_content = "<color=#e8d9bb>Un muñeco de ballena golpea repentinamente a Stellandine.</color>",
  ui_story_5086_50861201_84_dialog_content = "¡La señorita Moya es una persona mucho mejor de lo que tú jamás serás!",
  ui_story_5086_50861201_85_dialog_content = "Nos cuenta historias y trabaja duro para el acuario...",
  ui_story_5086_50861201_86_dialog_content = "Aunque apenas recuerda algo, ¡siempre me encuentra cerca de las ballenas cada vez que me escabullo!",
  ui_story_5086_50861201_87_dialog_content = "¿Pero tú? ¡Nunca te molestaste en recordar ninguno de nuestros nombres!",
  ui_story_5086_50861201_88_dialog_content = "Así es, Maya trata a todos con sinceridad. No deberías haberla decepcionado, señorita Stellandine.",
  ui_story_5086_50861201_89_dialog_content = "¡Recibe tu retribución! ¡Monstruo!",
  ui_story_5086_50861201_90_dialog_content = "<color=#e8d9bb>¡Golpe! ¡Golpe! ¡Golpe!</color>",
  ui_story_5086_50861201_91_dialog_content = "<color=#e8d9bb>Muñecas, llaves e incluso piedras del interior de las piscinas del acuario... Los visitantes comienzan a lanzar a Stellandine cualquier objeto que pueden encontrar.</color>",
  ui_story_5086_50861201_92_dialog_content = "Vaya, qué escena tan conmovedora...",
  ui_story_5086_50861201_93_dialog_content = "¡Entonces todos pueden morir juntos!!",
  ui_story_5086_50861202_1_dialog_content = "Se acabó, señorita Stellandine. Tanto tu vida como tus deseos.",
  ui_story_5086_50861202_2_dialog_content = "¿Puedo... ir a verla?",
  ui_story_5086_50861202_3_dialog_content = "Eso no es aconsejable, señorita Maya.",
  ui_story_5086_50861202_4_dialog_content = "Adelante, Maya.",
  ui_story_5086_50861202_5_dialog_content = "¡Gracias!",
  ui_story_5086_50861202_6_dialog_content = "Esto es imprudente.",
  ui_story_5086_50861202_7_dialog_content = "Sin embargo, a veces las emociones chocan con la razón, Minos.",
  ui_story_5086_50861202_8_dialog_content = "...",
  ui_story_5086_50861202_9_dialog_content = "Eso es cierto. ¡Continúa, Maya!",
  ui_story_5086_50861202_10_dialog_content = "He estado enfatizando constantemente nuestra postura contra los Eclipsites...",
  ui_story_5086_50861202_11_dialog_content = "Estoy consciente, Minos.",
  ui_story_5086_50861202_12_dialog_content = "Los crímenes de la señorita Stellandine son imperdonables, y por eso la castigamos.",
  ui_story_5086_50861202_13_dialog_content = "Pero para Maya, ella sigue siendo alguien importante que una vez cuidó de ella.",
  ui_story_5086_50861202_14_dialog_content = "Incluso si ella derrotó a la señorita Stellandine ella misma... Todavía no puede desprenderse de esas emociones.",
  ui_story_5086_50861202_15_dialog_content = "Cuando se trata de nosotros y los Eclipsites, no tenemos más opción que ver las cosas en blanco y negro.",
  ui_story_5086_50861202_16_dialog_content = "Si la señorita Maya desea permanecer en Harbor City, estas experiencias solo mancharán su vida aquí.",
  ui_story_5086_50861202_17_dialog_content = "... A menos que la \"mancha\" se convierta en \"dolor.\"",
  ui_story_5086_50861202_18_dialog_content = "Lo que la haría parecer una víctima inocente que había sido engañada todo el tiempo.",
  ui_story_5086_50861202_19_dialog_content = "Espera... ¿Es por eso que tú y la señorita Stellandine simplemente—",
  ui_story_5086_50861202_20_dialog_content = "Shhh.",
  ui_story_5086_50861202_21_dialog_content = "No importa cuán metafóricos sean, los cuentos de hadas siempre serán populares entre los niños.",
  ui_story_5086_50861202_22_dialog_content = "Mientras los justos triunfen y los malvados sufran la derrota, debería ser más que suficiente como un final feliz.",
  ui_story_5086_50861202_23_dialog_content = "Pensar demasiado solo te robará esa alegría pura.",
  ui_story_5086_50861202_24_dialog_content = "...",
  ui_story_5086_50861202_25_dialog_content = "Señorita Stellandine...",
  ui_story_5086_50861202_26_dialog_content = "Lo siento mucho. No tenía ni idea.",
  ui_story_5086_50861202_27_dialog_content = "No importa si fue tu deseo, dolor, o algo que has estado soportando constantemente...",
  ui_story_5086_50861202_28_dialog_content = "Si tan solo lo hubiera notado antes, tal vez podría haber ayudado...",
  ui_story_5086_50861202_29_dialog_content = "Eres un tonto...",
  ui_story_5086_50861202_30_dialog_content = "¿No me odias después de escuchar todo eso?",
  ui_story_5086_50861202_31_dialog_content = "La señorita Stellandine me dio un hogar en su acuario.",
  ui_story_5086_50861202_32_dialog_content = "¡Nunca, jamás olvidaré!",
  ui_story_5086_50861202_33_dialog_content = "Soy muy olvidadizo, ¡así que me niego a soltar a cualquiera!",
  ui_story_5086_50861202_34_dialog_content = "No puedo recordar cuántos Aurorianos he comido.",
  ui_story_5086_50861202_35_dialog_content = "Te ayudaré a expiar.",
  ui_story_5086_50861202_36_dialog_content = "¡Los maté! No es asunto tuyo... ¿Cómo vas a compensar las vidas perdidas?",
  ui_story_5086_50861202_37_dialog_content = "No puedo traer de vuelta a los inocentes que han fallecido, pero tengo la intención de ayudar a todos a superar su dolor!",
  ui_story_5086_50861202_38_dialog_content = "May ya sea postrándome ante ellos o haciendo enmiendas por el dolor que sufren, ¡trabajaré duro para ese fin!",
  ui_story_5086_50861202_39_dialog_content = "¡Si estás muriendo de hambre ahora, puedes tener algo de mi carne, señorita Stellandine!",
  ui_story_5086_50861202_40_dialog_content = "¡Olvidaré el dolor, y también sanaré rápido!",
  ui_story_5086_50861202_41_dialog_content = "Solo deseo llorar con todo mi corazón por ti, quien una vez cuidó de mí, y lo compensaré con todos en el futuro.",
  ui_story_5086_50861202_42_dialog_content = "Entonces... No me alejes...",
  ui_story_5086_50861202_43_dialog_content = "Shhh... No digas cosas así, ya estoy...",
  ui_story_5086_50861202_44_dialog_content = "No tienes nada que pagar, mi niño... Soy yo quien tiene una deuda que pagar...",
  ui_story_5086_50861202_45_dialog_content = "Entonces, ¿la gente realmente habla con sinceridad cuando es su último, eh?",
  ui_story_5086_50861202_46_dialog_content = "Eres... muy parecido a él.",
  ui_story_5086_50861202_47_dialog_content = "Imponente... Admirable...",
  ui_story_5086_50861202_48_dialog_content = "...",
  ui_story_5086_50861202_49_dialog_content = "Ignoró mi canto y se centró únicamente en luchar contra la tormenta.",
  ui_story_5086_50861202_50_dialog_content = "Se veía absolutamente guapo mientras estabilizaba desesperadamente el barco en medio de la tormenta furiosa.",
  ui_story_5086_50861202_51_dialog_content = "Quería esperar su regreso, pero él nunca lo hizo... Desembarqué en busca de él, pero no pude encontrarlo...",
  ui_story_5086_50861202_52_dialog_content = "Comí muchos Aurorianos, y muchas caras nuevas aparecieron en mis recuerdos.",
  ui_story_5086_50861202_53_dialog_content = "Y a medida que pasaba el tiempo... ya no podía decir a qué cara le pertenecía a él.",
  ui_story_5086_50861202_54_dialog_content = "Parecía seguir esperando, sin embargo toda mi espera...",
  ui_story_5086_50861202_55_dialog_content = "No fue más que un ensueño.",
  ui_story_5086_50861202_56_dialog_content = "Yo-Yo lo encontraré por ti.",
  ui_story_5086_50861202_57_dialog_content = "No... No tienes que.",
  ui_story_5086_50861202_58_dialog_content = "Porque recogí a una niña pequeña justo fuera del acuario, una niña tonta e ingenua que nunca dudó de nadie...",
  ui_story_5086_50861202_59_dialog_content = "Una niña ruidosa que nunca podía mantenerse en silencio. Y no pude evitar preocuparme...",
  ui_story_5086_50861202_60_dialog_content = "¿Qué haría ella sin mí?",
  ui_story_5086_50861202_61_dialog_content = "Lo pensé... Pensé en ser Stellandine y quedarme con mi Maya...",
  ui_story_5086_50861202_62_dialog_content = "Pero tenía tanta hambre... Realmente... me moría de hambre...",
  ui_story_5086_50861202_63_dialog_content = "...",
  ui_story_5086_50861202_64_dialog_content = "Sabía que rompería el corazón de mi Maya... Pero... Solo soy un monstruo que no pudo superar su naturaleza...",
  ui_story_5086_50861202_65_dialog_content = "La única forma de sobrevivir para mí era comer Aurorianos... ¿Y qué salió de eso? ¡Jah!",
  ui_story_5086_50861202_66_dialog_content = "Al final... lo perdí todo...",
  ui_story_5086_50861202_67_dialog_content = "Realmente soy un monstruo lamentable...",
  ui_story_5086_50861202_68_dialog_content = "Si solo... tuviera el corazón de un auroriano... Entonces podría haber...",
  ui_story_5086_50861202_69_dialog_content = "<color=#e8d9bb>Chapoteo—</color>",
  ui_story_5086_50861202_70_dialog_content = "?",
  ui_story_5086_50861202_71_dialog_content = "Este lugar... ¿Por qué? ¿No era yo...",
  ui_story_5086_50861202_72_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5086_50861202_73_dialog_content = "¡¿Una tormenta?! ¡No puede ser!",
  ui_story_5086_50861202_74_dialog_content = "¡Ni siquiera pienses en volcar nuestro barco, tormenta!",
  ui_story_5086_50861202_75_dialog_content = "¡Hermanos! ¡Mostremos a Poseidón cuán valientes somos!",
  ui_story_5086_50861202_76_dialog_content = "¡Crucemos esta tormenta! ¡Avanza! ¡Ho!",
  ui_story_5086_50861202_77_dialog_content = "¡Oye! ¡Baja ahí y asegura ese barco!",
  ui_story_5086_50861202_78_dialog_content = "Y no hagas nada más a menos que yo dé la orden.",
  ui_story_5086_50861202_79_dialog_content = "¡Rugido!",
  ui_story_5086_50861202_80_dialog_content = "¿Eh? El barco de repente se estabilizó... ¡Perfecto! ¡Salgamos corriendo ahora!",
  ui_story_5086_50861202_81_dialog_content = "<color=#e8d9bb>El barco desaparece gradualmente en el horizonte en medio de la tormenta que se reduce.</color>",
  ui_story_5086_50861202_82_dialog_content = "...",
  ui_story_5086_50861202_83_dialog_content = "¿No vas a ir tras ellos?",
  ui_story_5086_50861202_84_dialog_content = "No.",
  ui_story_5086_50861202_85_dialog_content = "De esta manera, no cometeré los mismos errores de nuevo, y no volveré a lastimar a esa pequeña niña.",
  ui_story_5086_50861202_86_dialog_content = "Puedo extraer la apariencia de ese marinero de tus recuerdos.",
  ui_story_5086_50861202_87_dialog_content = "Al menos al final, tú puedes...",
  ui_story_5086_50861202_88_dialog_content = "Este es un sueño que el niño creó para mí, ¿verdad?",
  ui_story_5086_50861202_89_dialog_content = "...Sí.",
  ui_story_5086_50861202_90_dialog_content = "¿Estoy muriendo?",
  ui_story_5086_50861202_91_dialog_content = "Si.",
  ui_story_5086_50861202_92_dialog_content = "Bien.",
  ui_story_5086_50861202_93_dialog_content = "Un monstruo como yo debería morir con arrepentimientos.",
  ui_story_5086_50861202_94_dialog_content = "Debería expiar mis pecados sufriendo un dolor eterno.",
  ui_story_5086_50861202_95_dialog_content = "¿Puede ella verme?",
  ui_story_5086_50861202_96_dialog_content = "... No.",
  ui_story_5086_50861202_97_dialog_content = "Entonces dile que fue un dulce sueño.",
  ui_story_5086_50861202_98_dialog_content = "Entonces...",
  ui_story_5086_50861202_99_dialog_content = "<color=#e8d9bb>Chapoteo.</color>",
  ui_story_5086_50861202_100_dialog_content = "<color=#e8d9bb>Mis palabras son recibidas con una fuerza repentina que me aleja y una ligera salpicadura en el océano.</color>",
  ui_story_5086_50861202_101_dialog_content = "<color=#e8d9bb>Stellandine se hunde en el agua y su figura se desdibuja gradualmente a medida que se corta el enlace.</color>",
  ui_story_5086_50861202_102_dialog_content = "<color=#e8d9bb>Nació del océano, y ahora, parece haber regresado a su abrazo. Inmóvil... simplemente hundiéndose, y hundiéndose hasta el fondo.</color>",
  ui_story_5086_50861202_103_dialog_content = "¡Stellandina!",
  ui_story_5086_50861202_104_dialog_content = "Mmm-mmm.",
  ui_story_5086_50861202_105_dialog_content = "<color=#e8d9bb>Ignorando mis llamadas y obstrucción, el monstruo comienza a cantar mientras se sumerge en el abismo.</color>",
  ui_story_5086_50861202_106_dialog_content = "<color=#e8d9bb>La canción de una sirena podría engañar la mente y convertir en presa a todos los que la escuchan.</color>",
  ui_story_5086_50861202_107_dialog_content = "<color=#e8d9bb>Pero esta melodía no dañó a nadie.</color>",
  ui_story_5086_50861202_108_dialog_content = "<color=#e8d9bb>Es solo... Una triste y tierna bendición de las profundidades heladas del océano.</color>",
  ui_story_5086_50861202_109_dialog_content = "Mi... pobre... adorable... pequeña Maya...",
  ui_story_5086_50861202_110_dialog_content = "May tú... vive felizmente... con aquellos que amas.",
  ui_story_5086_50861202_111_dialog_content = "<color=#e8d9bb>El cuerpo de Stellandine comienza a desvanecerse en el vestíbulo del acuario.</color>",
  ui_story_5086_50861202_112_dialog_content = "Es cierto que puedo sentir el bien y el mal en una persona.",
  ui_story_5086_50861202_113_dialog_content = "Así que incluso si soy olvidadizo, no puedo ser engañado tan fácilmente.",
  ui_story_5086_50861202_114_dialog_content = "La señorita Stellandine era una Eclipsite, pero desde el día que nos conocimos, e incluso justo ahora...",
  ui_story_5086_50861202_115_dialog_content = "Ella nunca tuvo ni la más mínima malicia hacia mí.",
  ui_story_5086_50861202_116_dialog_content = "Entonces, lo menos que puedo hacer es darle un dulce sueño, ¿verdad?",
  ui_story_5086_50861202_117_dialog_content = "Si.",
  ui_story_5086_50861202_118_dialog_content = "En el pasado, ella no podía dejar ir su deseo de sobrevivir, ni podía renunciar a sus pensamientos deseosos.",
  ui_story_5086_50861202_119_dialog_content = "Pero cuando lo soltó todo y perdió todo, todavía estaba dispuesta a dar sus bendiciones sinceras...",
  ui_story_5086_50861202_120_dialog_content = "En mi opinión, ella se arrepintió, y por lo tanto ya no era solo un monstruo.",
  ui_story_5086_50861202_121_dialog_content = "Deseaba el corazón de un Aurorian, y ahora, en el momento de su muerte, puede devolverlo todo gradualmente.",
  ui_story_5086_50861202_122_dialog_content = "<color=#e8d9bb>En las silenciosas profundidades del sueño oceánico.</color>",
  ui_story_5086_50861202_123_dialog_content = "<color=#e8d9bb>De repente, un rayo de luz deslumbrante aparece ante la figura hundida de Stellandine.</color>",
  ui_story_5086_50861202_124_dialog_content = "<color=#e8d9bb>Un marinero se acerca a ella desde dentro de la luz, su guapo rostro claramente reflejado en sus ojos.</color>",
  ui_story_5086_50861202_125_dialog_content = "Ven conmigo.",
  ui_story_5086_50861202_126_dialog_content = "... Está bien...",
  ui_story_5086_50861202_127_dialog_content = "<color=#e8d9bb>Stellandine sonríe antes de desvanecerse por completo.</color>",
  ui_story_5086_50861202_128_dialog_content = "Gracias, PlayerName.",
  ui_story_5086_50861202_129_dialog_content = "Um... No sé cómo decir esto, pero gracias por todo.",
  ui_story_5086_50861202_130_dialog_content = "En absoluto. Solo ayudé a la señorita Stellandine a recordar el rostro del marinero.",
  ui_story_5086_50861202_131_dialog_content = "De hecho, eres tú quien le dio la salvación a la señorita Stellandine, Maya.",
  ui_story_5086_50861202_132_dialog_content = "Porque el amor es eterno...",
  ui_story_5086_50861202_133_dialog_content = "¡Oh, correcto! ¡Mis notas!",
  ui_story_5086_50861202_134_dialog_content = "Debo escribirlo... ¡Ah!",
  ui_story_5086_50861202_135_dialog_content = "<color=#e8d9bb>Mientras Maya busca sus notas, una tarjeta se cae detrás de su cubierta.</color>",
  ui_story_5086_50861202_136_dialog_content = "¿Esa es... la Baraja de Origen de Jeno?!",
  ui_story_5086_50861300_1_dialog_content = "<color=#e8d9bb>Después del incidente del circo—</color>",
  ui_story_5086_50861300_2_dialog_content = "Jeno...",
  ui_story_5086_50861300_3_dialog_content = "No habrá más actuaciones.",
  ui_story_5086_50861300_4_dialog_content = "¡Sabía que podrías leer mentes, Jeno!",
  ui_story_5086_50861300_5_dialog_content = "No, es porque preguntarías si alguien buscara tu ayuda.",
  ui_story_5086_50861300_6_dialog_content = "Vamos a dejar Harbor City una vez que se arregle el Emerald.",
  ui_story_5086_50861300_7_dialog_content = "¿Eh? Pero muchos esperan con ansias la actuación, y... Elvis...",
  ui_story_5086_50861300_8_dialog_content = "Elvis es la razón por la que debemos irnos.",
  ui_story_5086_50861300_9_dialog_content = "Ven conmigo, Maya.",
  ui_story_5086_50861300_10_dialog_content = "Mi partida está decidida, pero tú eres nuevo, así que no voy a obligarte.",
  ui_story_5086_50861300_11_dialog_content = "¿Entonces vienes con nosotros? ¿O te quedarás aquí en su lugar?",
  ui_story_5086_50861300_12_dialog_content = "Si voy contigo, ¿puedo ayudarte a ti y a Elvis?",
  ui_story_5086_50861300_13_dialog_content = "Me parece difícil porque no puedes controlar tu poder.",
  ui_story_5086_50861300_14_dialog_content = "Veo...",
  ui_story_5086_50861300_15_dialog_content = "¡Entiendo! ¡Entonces me quedaré aquí!",
  ui_story_5086_50861300_16_dialog_content = "Elvis siempre ha cuidado de mí, y es hora de que le ayude a cuidar de Harbor City.",
  ui_story_5086_50861300_17_dialog_content = "Puede que no sea el más confiable... ¡Pero prometo hacer todo lo posible para ayudar a todos!",
  ui_story_5086_50861300_18_dialog_content = "Ahora que Elvis ya no es el Señor de la Ciudad, ya no puede enviar a nadie para protegerte.",
  ui_story_5086_50861300_19_dialog_content = "Tendrás que vivir independientemente como solías hacerlo.",
  ui_story_5086_50861300_20_dialog_content = "Soy un trabajador duro, ¡así que no pasaré hambre! ¡No te preocupes por mí! ¡Tengo montones de experiencia laboral! Aunque parece que lo he olvidado todo...",
  ui_story_5086_50861300_21_dialog_content = "Pero.",
  ui_story_5086_50861300_22_dialog_content = "La señorita Stellandine del acuario fue realmente amable. ¡Gané mucho dinero allí!",
  ui_story_5086_50861300_23_dialog_content = "Deberías centrarte en asuntos más importantes, Jeno!",
  ui_story_5086_50861300_24_dialog_content = "Entonces tengo un favor que pedirte.",
  ui_story_5086_50861300_25_dialog_content = "¡No me importa incluso cien favores!",
  ui_story_5086_50861300_26_dialog_content = "No es nada grandioso. Solo necesito que pases un mensaje.",
  ui_story_5086_50861300_27_dialog_content = "Bueno... Me temo que lo olvidaré...",
  ui_story_5086_50861300_28_dialog_content = "Eso es exactamente lo que te hace tan confiable.",
  ui_story_5086_50861300_29_dialog_content = "Vive bien en el acuario. Vendremos a verte algún día.",
  ui_story_5086_50861300_30_dialog_content = "Entonces... ¿eso significa que Maya fue el mensajero de Jeno, después de todo?",
  ui_story_5086_50861300_31_dialog_content = "¿Un mensaje?",
  ui_story_5086_50861300_32_dialog_content = "No recuerdo nada parecido a eso...",
  ui_story_5086_50861300_33_dialog_content = "Pero recuerdo vagamente algo sobre cuidar bien esta tarjeta.",
  ui_story_5086_50861300_34_dialog_content = "¿He olvidado algo importante otra vez?",
  ui_story_5086_50861300_35_dialog_content = "No, creo que es parte del truco de Jeno.",
  ui_story_5086_50861300_36_dialog_content = "La mayoría solo nota el agua desapareciendo misteriosamente de la taza.",
  ui_story_5086_50861300_37_dialog_content = "Pero en los ojos de un mago, es tan simple como sacar un vaso vacío de debajo de la mesa.",
  ui_story_5086_50861300_38_dialog_content = "¡Ya veo! ¡El acertijo siempre ha estado justo frente a nosotros! Aunque nadie más que yo podría descubrirlo nunca!",
  ui_story_5086_50861300_39_dialog_content = "PlayerName, ¿vas a sacar algo?",
  ui_story_5086_50861300_40_dialog_content = "Son tus recuerdos.",
  ui_story_5086_50861300_41_dialog_content = "Oh, pero no te preocupes. Jeno no dejaría simplemente la Baraja de Origen atrás.",
  ui_story_5086_50861300_42_dialog_content = "Si lo uso como mi guía, debería poder localizar el mensaje sin tocar ninguno de tus otros recuerdos.",
  ui_story_5086_50861300_43_dialog_content = "Está bien.",
  ui_story_5086_50861300_44_dialog_content = "¿Ah?",
  ui_story_5086_50861300_45_dialog_content = "PlayerName, aunque rechazaste ropa bonita, gemas e incluso perlas...",
  ui_story_5086_50861300_46_dialog_content = "¡Pero siempre eres bienvenido a disfrutar en mis sueños, los Ancestros lo han permitido!",
  ui_story_5086_50861300_47_dialog_content = "Sería mi honor.",
  ui_story_5086_50861300_48_dialog_content = "Entonces-",
  ui_story_5086_50861300_49_option_content = "Enlace mental!",
  ui_story_5086_50861300_50_dialog_content = "(¡Enfócate! Concéntrate en la onda que se sincroniza con el Origin Deck...)",
  ui_story_5086_50861300_51_dialog_content = "(¡Lo encontré!)",
  ui_story_5086_50861300_52_dialog_content = "Eres el único que podría llegar aquí, así que iré directo al grano.",
  ui_story_5086_50861300_53_dialog_content = "Elvis está despierto.",
  ui_story_5086_50861300_54_dialog_content = "(!)",
  ui_story_5086_50861300_55_dialog_content = "Aunque fue solo por un momento, y se durmió justo después, es suficiente para demostrar que el método de tratamiento de <color=#FFB400>la mujer</color> va en la dirección correcta.",
  ui_story_5086_50861300_56_dialog_content = "Elvis... nunca considera el panorama general. Simplemente se lanza ciegamente ante la vista de incluso un destello de esperanza y deja a todos atrás.",
  ui_story_5086_50861300_57_dialog_content = "Es un hombre absolutamente egoísta pero justo.",
  ui_story_5086_50861300_58_dialog_content = "Pero no tengo derecho a hablar mal de él. Porque no importa lo que haga, me resulta imposible odiarlo.",
  ui_story_5086_50861300_59_dialog_content = "Entonces, mi única opción es ser su cómplice.",
  ui_story_5086_50861300_60_dialog_content = "Lo llevaré al siguiente paso en su tratamiento.",
  ui_story_5086_50861300_61_dialog_content = "Caelestite, puede que necesite tu ayuda para asegurar que la conciencia de Elvis permanezca intacta.",
  ui_story_5086_50861300_62_dialog_content = "Por eso hice que Maya te transmitiera esta información.",
  ui_story_5086_50861300_63_dialog_content = "Por favor, manténgalo en secreto de cualquier persona conectada con Lumopolis, incluyendo a sus compañeros.",
  ui_story_5086_50861300_64_dialog_content = "Encontraré una forma de contactarte cuando sea el momento adecuado.",
  ui_story_5086_50861300_65_dialog_content = "¿Eso es todo?",
  ui_story_5086_50861300_66_dialog_content = "Hmm... No, hay una cosa más.",
  ui_story_5086_50861300_67_dialog_content = "No soy un gran líder, así que pensé en dejar el circo atrás. Es una lástima que el Emerald esté tan lleno de gente terca e inflexible.",
  ui_story_5086_50861300_68_dialog_content = "Insisten en seguirme, y si agrego Elvis a la ecuación... Bueno, la conclusión es que dejamos a Maya sola en Harbor City.",
  ui_story_5086_50861300_69_dialog_content = "Escuché que Elvis le prometió a su papá que siempre estaría allí para ella.",
  ui_story_5086_50861300_70_dialog_content = "Entonces, no tengo más remedio que pedirte que nos ayudes con eso.",
  ui_story_5086_50861300_71_dialog_content = "¡No te preocupes, estaré bien!",
  ui_story_5086_50861300_72_dialog_content = "Maya... ¿Realmente no vienes con nosotros?",
  ui_story_5086_50861300_73_dialog_content = "Boo-hoo... Te voy a extrañar...",
  ui_story_5086_50861300_74_dialog_content = "(Parémonos aquí.)",
  ui_story_5086_50861300_75_dialog_content = "¿Bien?",
  ui_story_5086_50861300_76_dialog_content = "¿Encontraste lo que estabas buscando?",
  ui_story_5086_50861300_77_dialog_content = "¡Lo hice! Gracias, Maya. Realmente me hiciste un gran favor allí.",
  ui_story_5086_50861300_78_dialog_content = "¡Impresionante!",
  ui_story_5086_50861300_79_dialog_content = "De todos modos... Ahora que la señorita Stellandine se ha ido...",
  ui_story_5086_50861300_80_dialog_content = "¿Te gustaría venir conmigo?",
  ui_story_5086_50861300_81_dialog_content = "Aunque no puedo darte lo mejor, hay muchas habitaciones vacías en el Coloso...",
  ui_story_5086_50861300_82_dialog_content = "¡Realmente me gustas, PlayerName!",
  ui_story_5086_50861300_83_dialog_content = "¡¿Eh?! ¿De dónde vino eso...",
  ui_story_5086_50861300_84_dialog_content = "¡Jeje! Pero también me gusta Elvis, el mar y Harbor City.",
  ui_story_5086_50861300_85_dialog_content = "Y aunque deba mantenerlo en secreto...",
  ui_story_5086_50861300_86_dialog_content = "¡A mí también me gusta mucho la señorita Stellandine!",
  ui_story_5086_50861300_87_dialog_content = "Por esa razón, quiero quedarme y mantener este acuario vivo.",
  ui_story_5086_50861300_88_dialog_content = "El acuario siempre será mi hogar.",
  ui_story_5086_50861300_89_dialog_content = "Y haré todo lo posible para compensar todo y curar las heridas de todos, para que todos podamos sonreír de nuevo.",
  ui_story_5086_50861300_90_dialog_content = "Bien... Si alguna vez encuentro un médico capaz de tratar tu pérdida de memoria, puedes estar seguro de que te lo traeré.",
  ui_story_5086_50861300_91_dialog_content = "Gracias, aunque realmente no tienes que preocuparte por eso.",
  ui_story_5086_50861300_92_dialog_content = "Estoy seguro de que podré vivir una vida mejor.",
  ui_story_5086_50861300_93_dialog_content = "Además, <color=#FFB400>yo</color> he descubierto algunas cosas.",
  ui_story_5086_50861300_94_dialog_content = "¿Qué es?",
  ui_story_5086_50861300_95_dialog_content = "¡Jeje! <color=#FFB400>Yo</color> lo registré en mis notas. Te dejaré leerlo cuando nos volvamos a encontrar.",
  ui_story_5086_50861300_96_dialog_content = "¡Pero es un secreto por ahora!",
  ui_story_5086_50861300_97_dialog_content = "<color=#e8d9bb>Los caballeros de Lumopolis se encargaron del trabajo restante.</color>",
  ui_story_5086_50861300_98_dialog_content = "<color=#e8d9bb>Aquellos que dieron un paso adelante fueron recompensados y se fueron.</color>",
  ui_story_5086_50861300_99_dialog_content = "<color=#e8d9bb>Y los visitantes agotados se fueron después de dar cuenta de todo lo que sabían.</color>",
  ui_story_5086_50861300_100_dialog_content = "<color=#e8d9bb>Una vez que los empleados también se fueron, Maya se quedó completamente sola en el acuario por la noche... Y otro que estaba regresando silenciosamente.</color>",
  ui_story_5086_50861300_101_dialog_content = "Hola, señorita Maya.",
  ui_story_5086_50861300_102_dialog_content = "¿Señor Minos? ¿Qué haces de vuelta aquí? ¿Olvidaste algo?",
  ui_story_5086_50861300_103_dialog_content = "Solo quería confirmar algo.",
  ui_story_5086_50861300_104_dialog_content = "¿Eh? ¿Qué se supone que significa eso?",
  ui_story_5086_50861300_105_dialog_content = "Entonces déjame explicar brevemente.",
  ui_story_5086_50861300_106_dialog_content = "Le contaste una historia a los niños.",
  ui_story_5086_50861300_107_dialog_content = "Trataba sobre un chico y un monstruo marino en un pequeño pueblo...",
  ui_story_5086_50861300_108_dialog_content = "¿Conté una historia así? ¡Suena realmente interesante!",
  ui_story_5086_50861300_109_dialog_content = "De hecho, así fue. Señorita Maya, tienes una imaginación absolutamente libre y vibrante.",
  ui_story_5086_50861300_110_dialog_content = "Pero tuve el placer de leer la historia original.",
  ui_story_5086_50861300_111_dialog_content = "En el original, una vez que el chico creció, se fue en busca de la ciudad nuevamente.",
  ui_story_5086_50861300_112_dialog_content = "Pero no importa cuántas playas y bosques cruzó, nunca pudo encontrar el camino de regreso allí.",
  ui_story_5086_50861300_113_dialog_content = "Resulta que el pueblo reside entre las grietas de un sueño, y solo se proyecta en la realidad cuando alguien lo ve o lo observa.",
  ui_story_5086_50861300_114_dialog_content = "El chico y la niña llorando se hicieron amigos, y él ayudó a la gente a eliminar al monstruo marino. Sin embargo, nunca más volvieron a visitar la ciudad.",
  ui_story_5086_50861300_115_dialog_content = "Con el paso del tiempo, el propio pueblo desapareció.",
  ui_story_5086_50861300_116_dialog_content = "Si eso sucediera, ¿crees que el gato lamentaría haber arrastrado al chico a todo esto?",
  ui_story_5086_50861300_117_dialog_content = "El gato posee un poder increíble, y \"sus\" pensamientos afectarán mi juicio en ciertos asuntos.",
  ui_story_5086_50861300_118_dialog_content = "Yo... en realidad no entiendo muy bien tu historia, Sr. Minos.",
  ui_story_5086_50861300_119_dialog_content = "Pero la niña que lloraba sola todos los días hizo un amigo gracias al chico.",
  ui_story_5086_50861300_120_dialog_content = "Y los visitantes que fueron atraídos allí por la leyenda parecen haberse ido después de disfrutar al máximo.",
  ui_story_5086_50861300_121_dialog_content = "Al final, todos del sueño regresaron a donde vinieron.",
  ui_story_5086_50861300_122_dialog_content = "Entonces quizás el gato... no pensó nada al respecto.",
  ui_story_5086_50861300_123_dialog_content = "Aunque hay algunos remordimientos, todos hicieron su mejor esfuerzo, y eso lo convierte en un final feliz.",
  ui_story_5086_50861300_124_dialog_content = "Un buen final... ¿Eh?",
  ui_story_5086_50861300_125_dialog_content = "Si tuviera que decir, definitivamente el gato querría ver al chico de nuevo.",
  ui_story_5086_50861300_126_dialog_content = "Querría dar otro paseo por la playa juntos.",
  ui_story_5086_50861300_127_dialog_content = "Observa las olas rompiendo sobre el arrecife de coral, los peces voladores saltando fuera del agua, y rueda en la arena y ríe mientras observas a un torpe cangrejo tambalearse de un lado a otro.",
  ui_story_5086_50861300_128_dialog_content = "Y al final del día, se acurrucarían bajo una palmera y dejarían que la brisa marina los llevara a dormir.",
  ui_story_5086_50861300_129_dialog_content = "¿Es ese el deseo actual del gato?",
  ui_story_5086_50861300_130_dialog_content = "Podría haber realizado ese deseo yendo con el chico.",
  ui_story_5086_50861300_131_dialog_content = "Pero la casa del gato está en el pueblo.",
  ui_story_5086_50861300_132_dialog_content = "Entonces, el gato esperará hasta que el chico regrese. Después de todo...",
  ui_story_5086_50861300_133_dialog_content = "El amor es eterno.",
  ui_story_5086_50861300_134_dialog_content = "Lo entiendo ahora. Gracias, eso es todo lo que quería preguntar.",
  ui_story_5086_50861300_135_dialog_content = "Bueno, me dirijo a informar el resultado de la investigación de negocios a la señorita Nina. ¡Adiós!",
  ui_story_5086_50861300_136_dialog_content = "...",
  ui_story_5086_50861300_137_dialog_content = "Espero que el gato consiga su deseo.",
  ui_story_5086_50861300_138_dialog_content = "No se preocupe por eso.",
  ui_story_5086_50861300_139_dialog_content = "Porque los cuentos de hadas...",
  ui_story_5086_50861300_140_dialog_content = "Siempre tiene un final feliz.",
  ui_story_5086_50861300_141_dialog_content = "¡Oye! ¿Estás tratando de hacerte matar?",
  ui_story_5086_50861300_142_dialog_content = "¡Argh! ¿Me atraparon?!",
  ui_story_5086_50861300_143_dialog_content = "No vayas corriendo bajo la brisa marina cuando aún estás enfermo.",
  ui_story_5086_50861300_144_dialog_content = "He tenido suficiente sueño, Jeno. Quiero contemplar mi casa mientras estoy despierto.",
  ui_story_5086_50861300_145_dialog_content = "Me pregunto cómo estará Maya...",
  ui_story_5086_50861300_146_dialog_content = "La línea de sangre del Dragón Espejismo, el último del clan Espejismo...",
  ui_story_5086_50861300_147_dialog_content = "Y has verificado que su pulsera contiene auténticas cerdas de dragón.",
  ui_story_5086_50861300_148_dialog_content = "Nada puede detenerla.",
  ui_story_5086_50861300_149_dialog_content = "En efecto. Es un objeto legendario que su padre superó innumerables pruebas para obtener del Sanctum.",
  ui_story_5086_50861300_150_dialog_content = "No estoy preocupado por su supervivencia.",
  ui_story_5086_50861300_151_dialog_content = "Solo... no quiero que ella pierda su sonrisa nunca.",
  ui_story_5086_50861300_152_dialog_content = "Espero que Harbor City, y yo fuéramos dignos de sus hermosos cuentos de hadas.",
  ui_story_5086_50861300_153_dialog_content = "Entonces, haz lo mejor para expiar una vez que te mejores.",
  ui_story_5086_50861300_154_dialog_content = "Compensa todo.",
  ui_story_5086_50861300_155_dialog_content = "... Estaré a tu lado.",
  ui_story_5086_50861300_156_dialog_content = "Lo haré."
}
return config
